// ═══════════════════════════════════════════════════════════════
// WORKER REGISTER — 10 steps
// ═══════════════════════════════════════════════════════════════
function WorkerRegister({ onDone, onBack }) {
  const [step, setStep] = useState(1);
  const [cepLoading, setCepLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [data, setData] = useState({
    // 1 — Dados pessoais
    nome:"", cpf:"", nascimento:"", telefone:"",
    cpfExists: false,
    emailExists: false,
    // 2 — Endereço + deslocamento
    cep:"", rua:"", numero:"", complemento:"", bairro:"", cidade:"", estado:"",
    raioKm: 10, deslocamento:"",
    // 3 — Funções (especialidades)
    specs:[], specCustom:"",
    // 4 — Tempo de experiência por função + empresas onde trabalhou
    funcExp:{},                    // { [specId]: { tempo: "1 a 3 anos" } }
    empresasSelected:[],           // IDs de redes preset
    empresasCustom:[],             // strings de nomes adicionados livremente
    // (legado) Nível por especialidade — mantido pra compatibilidade caso ainda use em algum lugar
    specLevels:{},
    // 5 — Disponibilidade (grid: { Seg: ['manha','tarde'], Ter: ['noite'], ... }) + flexibilidade
    disponibilidade:{},
    flexibilidade:"",  // "mesmo-dia" | "algumas-horas" | "agendar"
    // 6 — Perfil de trabalho (5 perguntas comportamentais)
    perfilTrabalho:{ corrido:"", diaADia:"", tarefa:"", diferente:"", imprevisto:"" },
    // (legado) campos antigos do step 6 — mantidos pra compatibilidade
    trabalhoEquipe:false, atendCliente:false, tipoTrabalho:"",
    // 7 — Documentação
    temPix:false, chavePix:"", pcd:false, pcdTipo:"",
    // 8 — Foto
    fotoRosto:null,
    // 9 — Documento + Login
    docTipo:"", selfieDoc:null,
    email:"", senha:"", confirma:"",
  });
  const photoRef = useRef(); const selfieRef = useRef();
  const set = (k,v) => setData(d=>({...d,[k]:v}));
  const toggleArr = (k,v) => setData(d=>({...d,[k]:d[k].includes(v)?d[k].filter(x=>x!==v):[...d[k],v]}));
  const readFile = (file,key) => { const r=new FileReader(); r.onload=e=>set(key,e.target.result); r.readAsDataURL(file); };
  const setSpecLevel = (specId, val) => setData(d=>({...d,specLevels:{...d.specLevels,[specId]:val}}));
  const setFuncExp = (specId, key, val) => setData(d=>({...d,funcExp:{...d.funcExp,[specId]:{...(d.funcExp?.[specId]||{}),[key]:val}}}));
  const toggleFuncExpArr = (specId, key, val) => setData(d=>{
    const cur=(d.funcExp?.[specId]?.[key])||[];
    const next=cur.includes(val)?cur.filter(x=>x!==val):[...cur,val];
    return {...d,funcExp:{...d.funcExp,[specId]:{...(d.funcExp?.[specId]||{}),[key]:next}}};
  });
  const [openFunc, setOpenFunc] = useState(null);
  const setPerfil = (key, val) => setData(d=>({...d,perfilTrabalho:{...d.perfilTrabalho,[key]:val}}));

  const [cpfChecking, setCpfChecking] = useState(false);
  const [fieldErrors, setFieldErrors] = useState([]);

  const cpfError   = data.cpf&&data.cpf.replace(/\D/g,"").length===11&&!validateCPF(data.cpf)?"CPF inválido":data.cpfExists?"CPF já cadastrado — se já tem conta, faça login":"";
  const ageError   = data.nascimento&&!validateAge(data.nascimento)?"É necessário ter 18 anos ou mais":"";
  const senhaError = data.confirma&&data.senha!==data.confirma?"Senhas não coincidem":"";
  const emailValid = (em) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test((em||"").trim());
  const emailError = data.email&&!emailValid(data.email)?"E-mail inválido":data.emailExists?"E-mail já cadastrado — se já tem conta, faça login":"";

  const checkCPF = async (cpf) => {
    const raw = cpf.replace(/\D/g,"");
    if(raw.length!==11||!validateCPF(cpf)) return;
    setCpfChecking(true);
    const { data: existing } = await supabase.from("workers").select("id").eq("cpf",cpf).maybeSingle();
    setCpfChecking(false);
    set("cpfExists", !!existing);
  };

  const [emailChecking, setEmailChecking] = useState(false);
  const [qrModalOpen, setQrModalOpen] = useState(false);
  const checkEmail = async (em) => {
    const v = (em||"").trim().toLowerCase();
    if(!emailValid(v)) return;
    setEmailChecking(true);
    const { data: existing } = await supabase.from("workers").select("id").eq("email", v).maybeSingle();
    setEmailChecking(false);
    set("emailExists", !!existing);
  };
  const allSpecs = [...SPECS, ...(data.specCustom?[{id:"custom",icon:"⭐",label:data.specCustom}]:[])];
  const selectedSpecs = allSpecs.filter(s=>data.specs.includes(s.id));
  const allLevelsFilled = selectedSpecs.every(s=>data.specLevels[s.id]?.nivel>0&&data.specLevels[s.id]?.experiencia);
  const isFuncExpFilled = (id) => !!data.funcExp?.[id]?.tempo;
  const allFuncExpFilled = selectedSpecs.every(s=>isFuncExpFilled(s.id));

  const getMissingFields = () => {
    if(step===1){
      const m=[];
      if(!data.nome) m.push("Nome completo");
      if(data.cpf.replace(/\D/g,"").length<11) m.push("CPF");
      if(cpfError) m.push("CPF inválido ou já cadastrado");
      if(!data.nascimento) m.push("Data de nascimento");
      if(ageError) m.push("Idade mínima de 18 anos");
      if(data.telefone.replace(/\D/g,"").length<10) m.push("WhatsApp");
      return m;
    }
    if(step===2){
      const m=[];
      if(!data.email) m.push("E-mail");
      else if(!emailValid(data.email)) m.push("E-mail inválido");
      else if(data.emailExists) m.push("E-mail já cadastrado");
      if(data.senha.length<8) m.push("Senha (mínimo 8 caracteres)");
      if(senhaError) m.push("Senhas não coincidem");
      return m;
    }
    if(step===3){
      const m=[];
      if(!data.cep) m.push("CEP");
      if(!data.rua) m.push("Rua/Avenida");
      if(!data.numero) m.push("Número");
      if(!data.bairro) m.push("Bairro");
      if(!data.cidade) m.push("Cidade");
      if(!data.deslocamento) m.push("Como você se desloca");
      return m;
    }
    if(step===4) return [];   // foto perfil opcional
    if(step===5) return [];   // foto documento opcional
    if(step===6) return data.specs.length===0?["Selecione ao menos uma função"]:[];
    if(step===7) return allFuncExpFilled?[]:["Informe o tempo de experiência em cada função"];
    if(step===8) return Object.values(data.disponibilidade).some(t=>t.length>0)?[]:["Selecione ao menos um turno disponível"];
    if(step===9){
      const m=[]; const p=data.perfilTrabalho||{};
      if(!p.corrido)    m.push("Pergunta 1 — Quando o trabalho está corrido");
      if(!p.diaADia)    m.push("Pergunta 2 — No dia a dia");
      if(!p.tarefa)     m.push("Pergunta 3 — Quando recebe uma tarefa nova");
      if(!p.diferente)  m.push("Pergunta 4 — Se algo sai diferente");
      if(!p.imprevisto) m.push("Pergunta 5 — Se surge um imprevisto");
      return m;
    }
    return [];
  };

  const canNext = {
    1:  data.nome&&data.cpf.replace(/\D/g,"").length===11&&validateCPF(data.cpf)&&!data.cpfExists&&data.nascimento&&validateAge(data.nascimento)&&data.telefone.replace(/\D/g,"").length>=10,
    2:  data.email&&emailValid(data.email)&&!data.emailExists&&data.senha.length>=8&&!senhaError,
    3:  data.cep&&data.rua&&data.numero&&data.bairro&&data.cidade&&data.deslocamento,
    4:  true,                                                                                       // foto perfil opcional (pode enviar depois)
    5:  true,                                                                                       // foto documento opcional (pode enviar depois)
    6:  data.specs.length>=1,
    7:  allFuncExpFilled,
    8:  Object.values(data.disponibilidade).some(turnos=>turnos.length>0),
    9:  !!(data.perfilTrabalho?.corrido && data.perfilTrabalho?.diaADia && data.perfilTrabalho?.tarefa && data.perfilTrabalho?.diferente && data.perfilTrabalho?.imprevisto),
    10: true,
  }[step];

  const handleNext = () => {
    const missing = getMissingFields();
    if(missing.length>0){ setFieldErrors(missing); return; }
    setFieldErrors([]);
    next();
  };

  const next = async () => {
    if(step<10){ setStep(s=>s+1); return; }
    setSubmitting(true); setSubmitError("");
    try {
      const saved=await saveWorker(data);
      try { localStorage.removeItem("vorker:worker_register_draft"); } catch {}
      onDone({...data,id:saved.id});
    }
    catch(e){ setSubmitError(e.message||"Erro ao salvar. Tente novamente."); }
    finally { setSubmitting(false); }
  };
  const back = ()=>{ setFieldErrors([]); step>1?setStep(s=>s-1):onBack(); };

  // Salvar e continuar depois (localStorage)
  const DRAFT_KEY = "vorker:worker_register_draft";
  const [draftPrompt, setDraftPrompt] = useState(false);
  const [draftSavedAt, setDraftSavedAt] = useState(null);
  const [savedToast, setSavedToast] = useState(false);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(DRAFT_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed?.data) {
          setDraftPrompt(true);
          setDraftSavedAt(parsed.savedAt || null);
        }
      }
    } catch {}
  }, []);

  const restoreDraft = () => {
    try {
      const raw = localStorage.getItem(DRAFT_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed?.data) setData(parsed.data);
        if (parsed?.step) setStep(parsed.step);
      }
    } catch {}
    setDraftPrompt(false);
  };
  const discardDraft = () => {
    try { localStorage.removeItem(DRAFT_KEY); } catch {}
    setDraftPrompt(false);
  };
  const saveAndExit = () => {
    try {
      localStorage.setItem(DRAFT_KEY, JSON.stringify({ data, step, savedAt: Date.now() }));
      setSavedToast(true);
      setTimeout(()=>{ setSavedToast(false); onBack(); }, 1500);
    } catch {
      alert("Não foi possível salvar localmente. Continue o cadastro nesta sessão.");
    }
  };

  const LABELS = [
    "Dados pessoais","Senha","Endereço e deslocamento",
    "Foto de perfil","Foto do documento","Funções","Experiência e empresas",
    "Disponibilidade","Perfil de trabalho","Informações adicionais",
  ];

  const CHECKLIST = [
    {label:"Informações pessoais", step:1},
    {label:"Senha",                step:2},
    {label:"Endereço",             step:3},
    {label:"Foto de perfil",       step:4},
    {label:"Foto do documento",    step:5},
    {label:"Funções",              step:6},
    {label:"Experiência",          step:7},
    {label:"Disponibilidade",      step:8},
    {label:"Perfil profissional",  step:9},
    {label:"Confirmar cadastro",   step:10},
  ];
  const progressPct = Math.round((step / 10) * 100);

  return (
    <div style={{minHeight:"90vh",padding:"32px 20px 80px",background:C.bg}}>
      <div style={{maxWidth: step===9 ? 1080 : 640, margin:"0 auto"}}>

        {/* Banner: cadastro em andamento detectado no localStorage */}
        {draftPrompt && (
          <div style={{background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:12,padding:"14px 18px",marginBottom:14,display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
            <span style={{fontSize:20}}>💾</span>
            <div style={{flex:1,minWidth:200}}>
              <div style={{...H,fontSize:14,fontWeight:700,color:C.green}}>Cadastro salvo encontrado</div>
              <div style={{...B,fontSize:12,color:C.sub,marginTop:2}}>Você pode continuar de onde parou{draftSavedAt?` (salvo em ${new Date(draftSavedAt).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"})})`:""}.</div>
            </div>
            <button onClick={restoreDraft} style={{padding:"8px 14px",borderRadius:8,background:C.green,border:"none",color:"#fff",...B,fontSize:13,fontWeight:700,cursor:"pointer",whiteSpace:"nowrap"}}>Continuar</button>
            <button onClick={discardDraft} style={{padding:"8px 14px",borderRadius:8,background:"transparent",border:`1.5px solid ${C.border2}`,color:C.sub,...B,fontSize:13,fontWeight:600,cursor:"pointer",whiteSpace:"nowrap"}}>Descartar</button>
          </div>
        )}

        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
          <button onClick={back} style={{...B,fontSize:13,color:C.sub,background:"none",border:"none",cursor:"pointer"}}>← {step>1?"Voltar":"Cancelar"}</button>
          <Prog step={step} total={9} />
        </div>
        <div style={{...B,fontSize:12,color:C.muted,marginBottom:20}}>{LABELS[step-1]}</div>

        <div className="vorker-step-wrap" style={step===9?{display:"grid",gridTemplateColumns:"minmax(0,1fr) 320px",gap:20,alignItems:"start"}:{}}>
        <div className="fu" key={step} style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:16,padding:"32px 36px",boxShadow:"0 2px 16px rgba(0,0,0,.05)"}}>

          {/* ── STEP 1: Dados pessoais ── */}
          {step===1&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Dados pessoais</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Preencha com seus dados reais. Serão verificados pela equipe VORKER.</p>
            <Field label="Nome completo" placeholder="João da Silva" value={data.nome} onChange={v=>set("nome",v)} required />
            <div className="g2">
              <div style={{marginBottom:16}}>
                <label style={{...B,fontSize:12,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>CPF <span style={{color:C.red}}>*</span></label>
                <input placeholder="000.000.000-00" value={data.cpf} maxLength={14}
                  onChange={e=>{ set("cpfExists",false); set("cpf",maskCPF(e.target.value)); }}
                  onBlur={()=>checkCPF(data.cpf)}
                  style={{width:"100%",padding:"11px 14px",borderRadius:8,border:`1.5px solid ${cpfError?C.red:C.border2}`,background:"#fff",...B,fontSize:14,color:C.text,outline:"none"}} />
                {cpfChecking&&<div style={{...B,fontSize:11,color:C.muted,marginTop:5}}>🔍 Verificando CPF...</div>}
                {cpfError&&!cpfChecking&&<div style={{...B,fontSize:11,color:C.red,marginTop:5}}>⚠ {cpfError}</div>}
                {!cpfError&&!cpfChecking&&data.cpf.replace(/\D/g,"").length===11&&validateCPF(data.cpf)&&!data.cpfExists&&<div style={{...B,fontSize:11,color:C.green,marginTop:5}}>✓ CPF disponível</div>}
              </div>
              <Field label="Data de nascimento" value={data.nascimento} onChange={v=>set("nascimento",v)} type="date" hint={ageError} required helper="Mínimo 18 anos" />
            </div>
            <Field label="WhatsApp" placeholder="(11) 99999-9999" value={data.telefone} onChange={v=>set("telefone",maskPhone(v))} type="tel" maxLength={15} required helper="Usado pelas empresas para entrar em contato com você" />
            <Alert type="info">Todos os dados são tratados com sigilo e usados apenas para verificação.</Alert>
          </>}

          {/* ── STEP 3: Endereço + deslocamento ── */}
          {step===3&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Endereço e deslocamento</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Usamos para mostrar vagas próximas com a distância exata de cada oportunidade.</p>
            <AddressBlock data={data} setData={setData} loading={cepLoading} setLoading={setCepLoading} />
            <Div />
            <div style={{...H,fontSize:15,fontWeight:700,color:C.navy,marginBottom:16}}>Como você se desloca?</div>
            <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:20}}>
              {DESLOCAMENTOS.map(d=>(
                <div key={d} onClick={()=>set("deslocamento",d)}
                  style={{padding:"9px 16px",borderRadius:9,cursor:"pointer",border:`1.5px solid ${data.deslocamento===d?C.green:C.border2}`,background:data.deslocamento===d?C.greenBg:"transparent",...B,fontSize:13,fontWeight:data.deslocamento===d?600:400,color:data.deslocamento===d?C.green:C.sub,transition:"all .15s"}}>
                  {d}
                </div>
              ))}
            </div>
            <div style={{...B,fontSize:12,fontWeight:600,color:C.sub,marginBottom:10}}>RAIO MÁXIMO DE DESLOCAMENTO</div>
            <div style={{display:"flex",alignItems:"center",gap:16}}>
              <input type="range" min="2" max="50" step="2" value={data.raioKm} onChange={e=>set("raioKm",parseInt(e.target.value))}
                style={{flex:1,accentColor:C.green}} />
              <div style={{...H,fontSize:20,fontWeight:900,color:C.green,minWidth:70,textAlign:"right"}}>{data.raioKm} km</div>
            </div>
            <div style={{...B,fontSize:12,color:C.muted,marginTop:6}}>Você aceita vagas num raio de até {data.raioKm}km da sua casa</div>
          </>}

          {/* ── STEP 6: Funções ── */}
          {step===6&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Em quais funções você pode trabalhar?</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Quanto mais completo seu perfil, mais convites você recebe.</p>

            <div style={{...H,fontSize:15,fontWeight:700,color:C.navy,marginBottom:4}}>Funções disponíveis</div>
            <p style={{...B,fontSize:13,color:C.sub,marginBottom:14,lineHeight:1.55}}>Selecione todas as funções que você tem interesse ou experiência.</p>

            <div style={{display:"flex",flexWrap:"wrap",gap:10,marginBottom:12}}>
              {SPECS.map(s=>{const on=data.specs.includes(s.id); return(
                <div key={s.id} className={`chip ${on?"on":""}`} onClick={()=>toggleArr("specs",s.id)}>
                  <span style={{fontSize:18}}>{s.icon}</span>
                  <span style={{...B,fontSize:13,fontWeight:on?600:400,color:on?C.green:C.sub}}>{s.label}</span>
                  {on&&<span style={{color:C.green,fontSize:11}}>✓</span>}
                </div>
              );})}
              {/* Especialidade customizada */}
              {data.specCustom&&(
                <div className={`chip ${data.specs.includes("custom")?"on":""}`} onClick={()=>toggleArr("specs","custom")}>
                  <span style={{fontSize:18}}>⭐</span>
                  <span style={{...B,fontSize:13,fontWeight:data.specs.includes("custom")?600:400,color:data.specs.includes("custom")?C.green:C.sub}}>{data.specCustom}</span>
                  {data.specs.includes("custom")&&<span style={{color:C.green,fontSize:11}}>✓</span>}
                  <span onClick={e=>{e.stopPropagation();set("specCustom","");setData(d=>({...d,specs:d.specs.filter(s=>s!=="custom"),specLevels:{...d.specLevels,custom:undefined}}));}} style={{color:C.red,fontWeight:700,fontSize:13,marginLeft:4,cursor:"pointer"}}>×</span>
                </div>
              )}
            </div>

            <p style={{...B,fontSize:12,color:C.muted,marginBottom:18,fontStyle:"italic"}}>💡 Dica: selecionar mais funções aumenta suas chances de receber convites.</p>

            {/* Adicionar especialidade customizada */}
            {!data.specCustom&&(
              <div style={{marginBottom:16}}>
                <div style={{...B,fontSize:12,fontWeight:600,color:C.sub,marginBottom:8}}>Não encontrou sua especialidade? Cadastre abaixo:</div>
                <div style={{display:"flex",gap:8}}>
                  <input placeholder="Ex: Sommelier, Confeiteiro, Operador de Câmara Fria..."
                    id="custom-spec-input"
                    style={{flex:1,padding:"10px 14px",borderRadius:8,border:`1.5px solid ${C.border2}`,background:"#fff",...B,fontSize:13,color:C.text,outline:"none"}}
                    onKeyDown={e=>{if(e.key==="Enter"&&e.target.value.trim()){set("specCustom",e.target.value.trim());toggleArr("specs","custom");e.target.value="";}}} />
                  <button onClick={()=>{const el=document.getElementById("custom-spec-input");if(el&&el.value.trim()){set("specCustom",el.value.trim());if(!data.specs.includes("custom"))toggleArr("specs","custom");el.value="";}}}
                    style={{padding:"10px 16px",borderRadius:8,background:C.green,border:"none",color:"#fff",...B,fontSize:13,fontWeight:600,cursor:"pointer"}}>+ Adicionar</button>
                </div>
              </div>
            )}

            {data.specs.length>0?<Alert type="success">{data.specs.length} especialidade{data.specs.length>1?"s":""} selecionada{data.specs.length>1?"s":""}. No próximo passo você define o nível em cada uma.</Alert>:<Alert type="warning">Selecione ao menos uma especialidade.</Alert>}
          </>}

          {/* ── STEP 7: Tempo de experiência + Empresas onde trabalhou ── */}
          {step===7&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Sua experiência</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Quanto tempo você tem em cada função e onde já trabalhou.</p>

            {/* Bloco A — Tempo de experiência por função */}
            <div style={{...H,fontSize:15,fontWeight:700,color:C.navy,marginBottom:4}}>Tempo de experiência</div>
            <p style={{...B,fontSize:13,color:C.sub,marginBottom:14,lineHeight:1.55}}>Para cada função selecionada, escolha quanto tempo de experiência você tem.</p>
            {selectedSpecs.map(s=>{
              const tempo = data.funcExp?.[s.id]?.tempo || "";
              return (
                <div key={s.id} style={{border:`1px solid ${tempo?C.greenBorder:C.border}`,background:tempo?C.greenBg+"40":"#fff",borderRadius:10,padding:"14px 16px",marginBottom:10}}>
                  <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
                    <span style={{fontSize:20}}>{s.icon}</span>
                    <span style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>{s.label}</span>
                  </div>
                  <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                    {EXP_TIMES.map(t=>{
                      const on=tempo===t;
                      return (
                        <div key={t} onClick={()=>setFuncExp(s.id,"tempo",t)}
                          style={{padding:"7px 12px",borderRadius:7,cursor:"pointer",border:`1.5px solid ${on?C.green:C.border2}`,background:on?C.greenBg:"#fff",...B,fontSize:12,fontWeight:on?700:500,color:on?C.green:C.sub,transition:"all .15s"}}>
                          {t}
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}

            <Div />

            {/* Bloco B — Empresas onde trabalhou */}
            <div style={{...H,fontSize:15,fontWeight:700,color:C.navy,marginBottom:4}}>Empresas onde você já trabalhou</div>
            <p style={{...B,fontSize:13,color:C.sub,marginBottom:14,lineHeight:1.55}}>Selecione todas em que tem experiência. Não encontrou? Adicione abaixo.</p>

            <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:14}}>
              {EMPRESAS_PRESET.map(e=>{
                const on=data.empresasSelected.includes(e.id);
                return (
                  <div key={e.id} onClick={()=>toggleArr("empresasSelected",e.id)}
                    style={{padding:"9px 14px",borderRadius:8,cursor:"pointer",border:`1.5px solid ${on?C.green:C.border2}`,background:on?C.greenBg:"#fff",...B,fontSize:13,fontWeight:on?700:500,color:on?C.green:C.sub,transition:"all .15s",userSelect:"none"}}>
                    {e.label}{on&&" ✓"}
                  </div>
                );
              })}
            </div>

            {/* Customs já adicionados */}
            {data.empresasCustom.length>0&&(
              <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:14}}>
                {data.empresasCustom.map((nome,idx)=>(
                  <div key={idx} style={{display:"flex",alignItems:"center",gap:6,padding:"7px 12px",borderRadius:8,border:`1.5px solid ${C.green}`,background:C.greenBg,...B,fontSize:13,fontWeight:600,color:C.green}}>
                    <span>⭐ {nome}</span>
                    <span onClick={()=>setData(d=>({...d,empresasCustom:d.empresasCustom.filter((_,i)=>i!==idx)}))}
                      style={{color:C.red,fontWeight:700,fontSize:14,cursor:"pointer",lineHeight:1}}>×</span>
                  </div>
                ))}
              </div>
            )}

            {/* Adicionar empresa custom */}
            <div style={{...B,fontSize:12,fontWeight:600,color:C.sub,marginBottom:8}}>Adicionar outra empresa:</div>
            <div style={{display:"flex",gap:8,marginBottom:8}}>
              <input placeholder="Ex: Mercadinho do Bairro, Hortifruti Bom Preço..."
                id="custom-empresa-input"
                style={{flex:1,padding:"10px 14px",borderRadius:8,border:`1.5px solid ${C.border2}`,background:"#fff",...B,fontSize:13,color:C.text,outline:"none"}}
                onKeyDown={e=>{
                  if(e.key==="Enter"&&e.target.value.trim()){
                    const nome=e.target.value.trim();
                    if(!data.empresasCustom.includes(nome)) setData(d=>({...d,empresasCustom:[...d.empresasCustom,nome]}));
                    e.target.value="";
                  }
                }} />
              <button onClick={()=>{
                const el=document.getElementById("custom-empresa-input");
                if(el&&el.value.trim()){
                  const nome=el.value.trim();
                  if(!data.empresasCustom.includes(nome)) setData(d=>({...d,empresasCustom:[...d.empresasCustom,nome]}));
                  el.value="";
                }
              }} style={{padding:"10px 16px",borderRadius:8,background:C.green,border:"none",color:"#fff",...B,fontSize:13,fontWeight:600,cursor:"pointer"}}>+ Adicionar</button>
            </div>
            <p style={{...B,fontSize:11,color:C.muted,marginBottom:18}}>Pode adicionar quantas empresas quiser. Pressione Enter ou clique em "+ Adicionar".</p>

            {!allFuncExpFilled&&<Alert type="warning">Informe o tempo de experiência em cada função.</Alert>}
          </>}

          {/* ── STEP 8: Disponibilidade ── */}
          {step===8&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Disponibilidade</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Marque os turnos que você quer trabalhar. Deixe em branco os turnos que não deseja trabalhar.</p>

            <div style={{overflowX:"auto"}}>
              <table className="vorker-disp-table" style={{width:"100%",borderCollapse:"separate",borderSpacing:"6px"}}>
                <thead>
                  <tr>
                    <th style={{padding:"10px 8px",minWidth:96}}></th>
                    {SHIFTS.map(sh=>(
                      <th key={sh.id} style={{textAlign:"center",padding:"10px 8px",minWidth:108,verticalAlign:"bottom"}}>
                        <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
                          <span style={{fontSize:18,lineHeight:1}}>{sh.icon}</span>
                          <span style={{...H,fontSize:13,fontWeight:700,color:sh.color}}>{sh.label}</span>
                          <span style={{...B,fontSize:11,color:C.muted,fontWeight:500}}>{sh.time}</span>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {DAYS.map(day=>{
                    const dayShifts = data.disponibilidade[day]||[];
                    const hasAny = dayShifts.length>0;
                    const toggle = (shiftId) => {
                      const curr = data.disponibilidade[day]||[];
                      const next = curr.includes(shiftId)?curr.filter(s=>s!==shiftId):[...curr,shiftId];
                      setData(d=>({...d,disponibilidade:{...d.disponibilidade,[day]:next}}));
                    };
                    return (
                      <tr key={day}>
                        <td style={{...H,fontSize:13,fontWeight:700,color:hasAny?C.green:C.sub,padding:"10px 8px",whiteSpace:"nowrap",borderRight:`1px solid ${C.border}`}}>
                          <span className="vorker-day-full">{DAY_FULL[day]||day}</span>
                          <span className="vorker-day-short" style={{display:"none"}}>{day}</span>
                        </td>
                        {SHIFTS.map(sh=>{
                          const on = dayShifts.includes(sh.id);
                          return (
                            <td key={sh.id} style={{padding:"3px"}}>
                              <div onClick={()=>toggle(sh.id)}
                                style={{padding:"14px 8px",borderRadius:10,cursor:"pointer",border:`1.5px solid ${on?C.green:C.border2}`,background:on?C.greenBg:"#fff",textAlign:"center",transition:"all .15s",userSelect:"none",minHeight:46,display:"flex",alignItems:"center",justifyContent:"center"}}>
                                <span style={{...H,fontSize:18,fontWeight:700,color:on?C.green:"#CBD5E1",lineHeight:1}}>{on?"✓":"+"}</span>
                              </div>
                            </td>
                          );
                        })}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* Summary */}
            {Object.values(data.disponibilidade).some(t=>t.length>0)&&(
              <div style={{marginTop:16,background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:10,padding:"12px 16px"}}>
                <div style={{...B,fontSize:12,fontWeight:600,color:C.green,marginBottom:8}}>✓ Disponibilidade selecionada</div>
                {DAYS.filter(d=>(data.disponibilidade[d]||[]).length>0).map(d=>(
                  <div key={d} style={{display:"flex",gap:8,alignItems:"center",marginBottom:4}}>
                    <span style={{...H,fontSize:12,fontWeight:700,color:C.navy,minWidth:72}}>{DAY_FULL[d]||d}</span>
                    <div style={{display:"flex",gap:5}}>
                      {(data.disponibilidade[d]||[]).map(sid=>{
                        const sh=SHIFTS.find(s=>s.id===sid);
                        return sh?<span key={sid} style={{...B,fontSize:11,fontWeight:600,color:sh.color,background:sh.color+"15",padding:"2px 8px",borderRadius:5}}>{sh.label}</span>:null;
                      })}
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Bloco Flexibilidade — Aviso curto */}
            <Div />
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:6}}>
              <div style={{width:26,height:26,borderRadius:13,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                <span style={{...H,fontSize:13,fontWeight:800,color:"#fff"}}>3</span>
              </div>
              <h3 style={{...H,fontSize:17,fontWeight:800,color:C.navy,margin:0}}>Você pode trabalhar com aviso curto?</h3>
            </div>
            <p style={{...B,fontSize:13,color:C.sub,marginBottom:16,lineHeight:1.55,marginLeft:36}}>Isso nos ajuda a te chamar mais rápido quando surgir uma oportunidade.</p>
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10}} className="vorker-flex-grid">
              {[
                {v:"mesmo-dia",     icon:"⚡", iconBg:"#DCFCE7", iconColor:"#16A34A", title:"Sim, posso ir no mesmo dia",    desc:"Tenho flexibilidade para trabalhos de última hora."},
                {v:"algumas-horas", icon:"🕐", iconBg:"#DBEAFE", iconColor:"#2563EB", title:"Preciso de algumas horas",       desc:"Consigo me organizar com algumas horas de antecedência."},
                {v:"agendar",       icon:"📅", iconBg:"#DBEAFE", iconColor:"#2563EB", title:"Prefiro agendar antes",          desc:"Prefiro me organizar com 1 dia ou mais de antecedência."},
              ].map(opt=>{
                const on=data.flexibilidade===opt.v;
                return (
                  <div key={opt.v} onClick={()=>set("flexibilidade",opt.v)}
                    style={{position:"relative",padding:"18px 16px",borderRadius:12,cursor:"pointer",border:`1.5px solid ${on?C.green:C.border2}`,background:on?C.greenBg:"#fff",transition:"all .15s",userSelect:"none"}}>
                    {on && <div style={{position:"absolute",top:12,right:12,width:14,height:14,borderRadius:7,background:C.green,display:"flex",alignItems:"center",justifyContent:"center"}}><div style={{width:5,height:5,borderRadius:3,background:"#fff"}} /></div>}
                    <div style={{width:36,height:36,borderRadius:9,background:opt.iconBg,display:"flex",alignItems:"center",justifyContent:"center",marginBottom:12,fontSize:18}}>{opt.icon}</div>
                    <div style={{...H,fontSize:14,fontWeight:800,color:C.navy,marginBottom:6,lineHeight:1.25}}>{opt.title}</div>
                    <div style={{...B,fontSize:12,color:C.sub,lineHeight:1.45}}>{opt.desc}</div>
                  </div>
                );
              })}
            </div>
          </>}

          {/* ── STEP 9: Perfil de trabalho ── */}
          {step===9&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Seu perfil de trabalho</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:24,lineHeight:1.65}}>Responda de forma rápida e natural. Não existem respostas certas ou erradas — isso ajuda as empresas a te conhecerem melhor e fazerem as melhores escolhas.</p>

            {[
              {
                num:1, key:"corrido",
                title:"Quando o trabalho está muito corrido, você...",
                opts:[
                  {v:"manter",     icon:"⚡", title:"Mantém a velocidade",  desc:"fazendo o melhor possível"},
                  {v:"equilibrar", icon:"⚖️", title:"Equilibra velocidade", desc:"e atenção"},
                  {v:"diminuir",   icon:"🐢", title:"Diminui o ritmo",      desc:"para garantir qualidade"},
                ],
              },
              {
                num:2, key:"diaADia",
                title:"No dia a dia, o que te identifica mais?",
                opts:[
                  {v:"praticas",  icon:"🔧", title:"Tarefas práticas",      desc:"e operacionais"},
                  {v:"equilibrio",icon:"🎯", title:"Equilíbrio rápido",     desc:"e organização"},
                  {v:"cuidado",   icon:"🧠", title:"Pensar com cuidado",    desc:"em cada etapa"},
                ],
              },
              {
                num:3, key:"tarefa",
                title:"Quando recebe uma tarefa nova, você costuma...",
                opts:[
                  {v:"iniciativa", icon:"🚀", title:"Tomar iniciativa",      desc:"sozinho mesmo"},
                  {v:"perguntar",  icon:"💬", title:"Perguntar",             desc:"se necessário"},
                  {v:"orientacao", icon:"📋", title:"Pedir orientação",      desc:"antes de começar"},
                ],
              },
              {
                num:4, key:"diferente",
                title:"Se algo sai diferente do esperado no trabalho...",
                opts:[
                  {v:"ajusta",   icon:"🔄", title:"Me ajusto",            desc:"e sigo em frente"},
                  {v:"entender", icon:"🔍", title:"Tento entender",       desc:"o que aconteceu"},
                  {v:"avisar",   icon:"📣", title:"Prefiro avisar",       desc:"alguém antes"},
                ],
              },
              {
                num:5, key:"imprevisto",
                title:"Se você marcou um turno e surge um imprevisto pessoal...",
                opts:[
                  {v:"resolver", icon:"💪", title:"Tento resolver",        desc:"e cumprir o que assumi"},
                  {v:"aviso",    icon:"⏰", title:"Aviso o quanto antes",  desc:"para não atrapalhar"},
                  {v:"cancelar", icon:"❌", title:"Prefiro cancelar",      desc:"se não conseguir"},
                ],
              },
            ].map(q=>(
              <div key={q.key} style={{marginBottom:24}}>
                <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}>
                  <div style={{width:26,height:26,borderRadius:13,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                    <span style={{...H,fontSize:13,fontWeight:800,color:"#fff"}}>{q.num}</span>
                  </div>
                  <h3 style={{...H,fontSize:15,fontWeight:800,color:C.navy,margin:0,lineHeight:1.3}}>{q.title}</h3>
                </div>
                <div className="vorker-q-grid" style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10}}>
                  {q.opts.map(o=>{
                    const on = data.perfilTrabalho?.[q.key] === o.v;
                    return (
                      <div key={o.v} onClick={()=>setPerfil(q.key, o.v)}
                        style={{position:"relative",padding:"16px 14px",borderRadius:12,cursor:"pointer",border:`1.5px solid ${on?C.green:C.border2}`,background:on?C.greenBg:"#fff",transition:"all .15s",userSelect:"none"}}>
                        {on && <div style={{position:"absolute",top:10,right:10,width:14,height:14,borderRadius:7,background:C.green,display:"flex",alignItems:"center",justifyContent:"center"}}><div style={{width:5,height:5,borderRadius:3,background:"#fff"}} /></div>}
                        <div style={{width:34,height:34,borderRadius:9,background:on?"#DCFCE7":"#F1F5F9",display:"flex",alignItems:"center",justifyContent:"center",marginBottom:10,fontSize:17}}>{o.icon}</div>
                        <div style={{...H,fontSize:13,fontWeight:800,color:C.navy,marginBottom:3,lineHeight:1.3}}>{o.title}</div>
                        <div style={{...B,fontSize:11.5,color:C.sub,lineHeight:1.4}}>{o.desc}</div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}

            <div style={{marginTop:8,padding:"12px 16px",background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:10,display:"flex",alignItems:"center",gap:10}}>
              <span style={{fontSize:16}}>💚</span>
              <span style={{...B,fontSize:12.5,color:C.green,lineHeight:1.5}}>Respostas sinceras aumentam suas chances de receber convites das empresas certas.</span>
            </div>
          </>}

          {/* ── STEP 10: Informações adicionais ── */}
          {step===10&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Informações adicionais</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Última etapa antes de finalizar seu cadastro.</p>

            <div style={{...H,fontSize:15,fontWeight:700,color:C.navy,marginBottom:12}}>Pessoa com deficiência (PCD)?</div>
            <div style={{display:"flex",gap:10,marginBottom:14}}>
              {[{v:true,l:"Sim, sou PCD"},{v:false,l:"Não"}].map(({v,l})=>(
                <div key={String(v)} onClick={()=>set("pcd",v)}
                  style={{flex:1,padding:"12px 16px",borderRadius:10,cursor:"pointer",border:`1.5px solid ${data.pcd===v?C.green:C.border2}`,background:data.pcd===v?C.greenBg:"transparent",textAlign:"center",...B,fontSize:13,fontWeight:data.pcd===v?600:400,color:data.pcd===v?C.green:C.sub,transition:"all .15s"}}>
                  {l}
                </div>
              ))}
            </div>
            {data.pcd&&(
              <Field label="Tipo de deficiência (opcional)" placeholder="Ex: Auditiva, Visual, Física, Intelectual..." value={data.pcdTipo} onChange={v=>set("pcdTipo",v)} helper="Permite que empresas com cotas PCD priorizem seu perfil" />
            )}
            <Alert type="info">Informação usada para conectar com empresas que possuem cotas PCD.</Alert>
            {submitError&&<Alert type="error">{submitError}</Alert>}
          </>}

          {/* ── STEP 2: Senha (criar conta) ── */}
          {step===2&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Crie sua conta</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Defina o e-mail e senha que você usará para acessar o app a partir de agora.</p>

            <div style={{marginBottom:16}}>
              <label style={{...B,fontSize:12,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>E-mail <span style={{color:C.red}}>*</span></label>
              <input type="email" placeholder="seu@email.com" value={data.email}
                onChange={e=>{ set("emailExists",false); set("email",e.target.value); }}
                onBlur={()=>checkEmail(data.email)}
                style={{width:"100%",padding:"11px 14px",borderRadius:8,border:`1.5px solid ${emailError?C.red:C.border2}`,background:"#fff",...B,fontSize:14,color:C.text,outline:"none"}} />
              {emailChecking&&<div style={{...B,fontSize:11,color:C.muted,marginTop:5}}>🔍 Verificando e-mail...</div>}
              {emailError&&!emailChecking&&<div style={{...B,fontSize:11,color:C.red,marginTop:5}}>⚠ {emailError}</div>}
              {!emailError&&!emailChecking&&data.email&&emailValid(data.email)&&!data.emailExists&&<div style={{...B,fontSize:11,color:C.green,marginTop:5}}>✓ E-mail disponível</div>}
              {!emailError&&!emailChecking&&!data.email&&<div style={{...B,fontSize:11,color:C.muted,marginTop:5}}>Usaremos este e-mail para login e comunicação.</div>}
            </div>
            <div className="g2">
              <Field label="Senha" placeholder="Mínimo 8 caracteres" value={data.senha} onChange={v=>set("senha",v)} type="password" required />
              <Field label="Confirmar senha" placeholder="Repita a senha" value={data.confirma} onChange={v=>set("confirma",v)} type="password" hint={senhaError} required />
            </div>
            <Alert type="info">Em breve: cadastro com Google ou Meta.</Alert>
          </>}

          {/* ── STEP 4: Foto de perfil ── */}
          {step===4&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Foto de perfil</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:18,lineHeight:1.65}}>Perfis com foto recebem muito mais convites. Use uma foto clara, de rosto.</p>

            {/* Mockup ilustrativo */}
            <div style={{display:"grid",gridTemplateColumns:"auto 1fr",gap:18,alignItems:"center",background:C.bg,border:`1px dashed ${C.border2}`,borderRadius:12,padding:18,marginBottom:18}} className="vorker-mockup">
              <div style={{position:"relative",width:120,height:120,flexShrink:0}}>
                <div style={{position:"absolute",inset:0,border:`2.5px dashed ${C.green}`,borderRadius:60}} />
                <div style={{position:"absolute",inset:8,background:"linear-gradient(160deg,#DCFCE7,#BBF7D0)",borderRadius:52,display:"flex",alignItems:"flex-end",justifyContent:"center",overflow:"hidden"}}>
                  <svg viewBox="0 0 100 100" style={{width:"100%",height:"100%"}}>
                    <circle cx="50" cy="36" r="18" fill="#16A34A" opacity=".75" />
                    <path d="M18,100 Q50,58 82,100 Z" fill="#16A34A" opacity=".75" />
                  </svg>
                </div>
              </div>
              <div>
                <div style={{...H,fontSize:13,fontWeight:700,color:C.navy,marginBottom:8}}>Como deve ficar</div>
                {["Rosto centralizado e visível","Boa iluminação, fundo neutro","Sem óculos escuros nem boné","Foto recente — só você"].map(t=>(
                  <div key={t} style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}>
                    <span style={{color:C.green,fontWeight:900,fontSize:12}}>✓</span>
                    <span style={{...B,fontSize:12,color:C.sub}}>{t}</span>
                  </div>
                ))}
              </div>
            </div>

            <div className={`upload-zone ${data.fotoRosto?"has":""}`} onClick={()=>photoRef.current?.click()}>
              {data.fotoRosto
                ?<div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:12}}>
                  <img src={data.fotoRosto} alt="" style={{width:130,height:130,borderRadius:65,objectFit:"cover",border:`3px solid ${C.green}`}} />
                  <span style={{...H,fontSize:15,fontWeight:700,color:C.green}}>✓ Foto enviada</span>
                  <span style={{...B,fontSize:12,color:C.muted}}>Clique para substituir</span>
                 </div>
                :<div><div style={{fontSize:52,marginBottom:12}}>📷</div><div style={{...H,fontSize:16,fontWeight:700,color:C.navy,marginBottom:6}}>Clique para enviar sua foto</div><div style={{...B,fontSize:13,color:C.muted}}>JPG ou PNG · máx. 5MB</div></div>}
            </div>
            <input ref={photoRef} type="file" accept="image/*" style={{display:"none"}} onChange={e=>{const f=e.target.files[0];if(f)readFile(f,"fotoRosto");}} />

            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,flexWrap:"wrap",marginTop:14}}>
              <span style={{...B,fontSize:12,color:C.muted}}>💡 Você pode enviar depois pelo seu perfil.</span>
              <button onClick={()=>setQrModalOpen(true)} className="vorker-mobile-btn" style={{...H,fontSize:13,fontWeight:700,color:C.green,background:"transparent",border:`1.5px solid ${C.green}`,borderRadius:8,padding:"8px 14px",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:8}}>
                <span>📱</span> Continuar no celular
              </button>
            </div>
          </>}

          {/* ── STEP 5: Foto do documento ── */}
          {step===5&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Foto do documento</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:18,lineHeight:1.65}}>Envie uma foto do seu documento de identificação (RG ou CNH) para verificar sua identidade.</p>

            <div style={{background:C.greenBg,border:`1.5px solid ${C.greenBorder}`,borderRadius:10,padding:"12px 16px",marginBottom:18,display:"flex",gap:10,alignItems:"flex-start"}}>
              <span style={{fontSize:18}}>ℹ️</span>
              <div style={{...B,fontSize:13,color:C.green,lineHeight:1.55}}><strong>Você só precisa enviar UM documento</strong> — RG <strong>ou</strong> CNH (não os dois). Escolha o que você tem em mãos.</div>
            </div>

            <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:12}}>Qual documento você vai usar?</div>
            <div style={{display:"flex",gap:12,marginBottom:18}}>
              {[["RG","🪪","Identidade"],["CNH","🚗","Habilitação"]].map(([t,ic,sub])=>(
                <div key={t} onClick={()=>set("docTipo",t)} style={{flex:1,background:data.docTipo===t?C.greenBg:"#fff",borderRadius:12,padding:"16px 14px",border:`2px solid ${data.docTipo===t?C.green:C.border2}`,textAlign:"center",cursor:"pointer",transition:"all .15s"}}>
                  <div style={{fontSize:30,marginBottom:7}}>{ic}</div>
                  <div style={{...H,fontSize:16,fontWeight:700,color:data.docTipo===t?C.green:C.navy}}>{t}</div>
                  <div style={{...B,fontSize:12,color:C.muted,marginTop:2}}>{sub}</div>
                </div>
              ))}
            </div>

            {data.docTipo&&<>
              {/* Mockup ilustrativo do enquadramento do documento */}
              <div style={{display:"grid",gridTemplateColumns:"auto 1fr",gap:18,alignItems:"center",background:C.bg,border:`1px dashed ${C.border2}`,borderRadius:12,padding:18,marginBottom:14}} className="vorker-mockup">
                <div style={{position:"relative",width:140,height:120,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center"}}>
                  {/* Documento centralizado */}
                  <div style={{width:120,height:78,borderRadius:9,background:"#fff",border:`2px solid ${C.green}`,padding:"10px 12px",boxShadow:"0 4px 12px rgba(22,163,74,.15)"}}>
                    <div style={{width:24,height:30,background:"#CBD5E1",borderRadius:4,float:"left",marginRight:9}} />
                    <div style={{height:6,background:"#CBD5E1",borderRadius:2,marginBottom:5,marginLeft:33}} />
                    <div style={{height:5,background:"#E2E8F0",borderRadius:2,marginBottom:4,marginLeft:33,width:"70%"}} />
                    <div style={{height:5,background:"#E2E8F0",borderRadius:2,marginBottom:4,width:"80%"}} />
                    <div style={{height:5,background:"#E2E8F0",borderRadius:2,width:"55%"}} />
                  </div>
                </div>
                <div>
                  <div style={{...H,fontSize:13,fontWeight:700,color:C.navy,marginBottom:8}}>Como deve ficar</div>
                  {["Documento aberto e centralizado","Texto e foto bem legíveis","Sem reflexos sobre o documento","Fundo simples e boa iluminação"].map(t=>(
                    <div key={t} style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}>
                      <span style={{color:C.green,fontWeight:900,fontSize:12}}>✓</span>
                      <span style={{...B,fontSize:12,color:C.sub}}>{t}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className={`upload-zone ${data.selfieDoc?"has":""}`} onClick={()=>selfieRef.current?.click()} style={{marginBottom:8}}>
                {data.selfieDoc
                  ?<div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:12}}>
                    <img src={data.selfieDoc} alt="" style={{maxWidth:220,maxHeight:165,borderRadius:10,objectFit:"cover",border:`2px solid ${C.green}`}} />
                    <span style={{...H,fontSize:15,fontWeight:700,color:C.green}}>✓ Documento enviado</span>
                    <span style={{...B,fontSize:12,color:C.muted}}>Clique para substituir</span>
                   </div>
                  :<div><div style={{fontSize:48,marginBottom:12}}>🪪</div><div style={{...H,fontSize:16,fontWeight:700,color:C.navy,marginBottom:6}}>Foto do seu {data.docTipo}</div><div style={{...B,fontSize:13,color:C.muted}}>Foto · máx. 10MB</div></div>}
              </div>
              <input ref={selfieRef} type="file" accept="image/*" style={{display:"none"}} onChange={e=>{const f=e.target.files[0];if(f)readFile(f,"selfieDoc");}} />
              <div style={{...B,fontSize:11,color:C.muted,textAlign:"center",marginBottom:6}}>🔒 Visível apenas à equipe VORKER.</div>
            </>}

            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,flexWrap:"wrap",marginTop:14}}>
              <span style={{...B,fontSize:12,color:C.muted}}>💡 Você pode enviar depois pelo seu perfil.</span>
              <button onClick={()=>setQrModalOpen(true)} className="vorker-mobile-btn" style={{...H,fontSize:13,fontWeight:700,color:C.green,background:"transparent",border:`1.5px solid ${C.green}`,borderRadius:8,padding:"8px 14px",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:8}}>
                <span>📱</span> Continuar no celular
              </button>
            </div>
          </>}
        </div>

        {/* Sidebar progresso (visível apenas no step 9 — desktop ao lado, mobile abaixo) */}
        {step===9 && (
          <aside className="vorker-sidebar" style={{display:"flex",flexDirection:"column",gap:14,position:"sticky",top:20}}>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:"22px 22px",boxShadow:"0 2px 12px rgba(0,0,0,.04)"}}>
              <div style={{...H,fontSize:15,fontWeight:800,color:C.navy,marginBottom:6}}>Seu progresso</div>
              <p style={{...B,fontSize:12,color:C.sub,marginBottom:16,lineHeight:1.5}}>Perfis completos têm até 3x mais chances de receber convites.</p>

              <div style={{display:"flex",alignItems:"baseline",gap:6,marginBottom:8}}>
                <span style={{...H,fontSize:32,fontWeight:900,color:C.green,letterSpacing:-1,lineHeight:1}}>{progressPct}%</span>
                <span style={{...B,fontSize:12,color:C.sub}}>completo</span>
              </div>
              <div style={{height:6,borderRadius:3,background:"#E2E8F0",overflow:"hidden",marginBottom:18}}>
                <div style={{height:"100%",width:`${progressPct}%`,background:C.green,borderRadius:3,transition:"width .3s"}} />
              </div>

              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {CHECKLIST.map(it=>{
                  const done = step > it.step;
                  const current = step === it.step;
                  return (
                    <div key={it.label} style={{display:"flex",alignItems:"center",gap:10}}>
                      <div style={{width:18,height:18,borderRadius:9,background:done?C.green:current?C.greenBg:"#F1F5F9",border:`1.5px solid ${done?C.green:current?C.green:"#E2E8F0"}`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                        {done && <span style={{fontSize:10,color:"#fff",fontWeight:900,lineHeight:1}}>✓</span>}
                        {current && <div style={{width:6,height:6,borderRadius:3,background:C.green}} />}
                      </div>
                      <span style={{...B,fontSize:12.5,fontWeight:current?700:500,color:done?C.navy:current?C.green:C.muted}}>{it.label}</span>
                    </div>
                  );
                })}
              </div>
            </div>

            <div style={{background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:14,padding:"18px 18px"}}>
              <div style={{...H,fontSize:13,fontWeight:800,color:C.green,marginBottom:6}}>💡 Sabia que?</div>
              <p style={{...B,fontSize:12.5,color:C.text,lineHeight:1.55}}>Vorkers com perfil completo recebem em média <strong style={{color:C.green,fontWeight:700}}>5 convites por semana</strong>.</p>
            </div>
          </aside>
        )}
        </div>

        {fieldErrors.length>0&&(
          <div style={{background:C.redBg,border:`1px solid ${C.redBorder}`,borderRadius:10,padding:"12px 16px",marginTop:14}}>
            <div style={{...B,fontSize:13,fontWeight:600,color:C.red,marginBottom:6}}>⚠ Preencha os campos obrigatórios:</div>
            {fieldErrors.map((e,i)=><div key={i} style={{...B,fontSize:13,color:C.red}}>• {e}</div>)}
          </div>
        )}

        <div className="vorker-nav-row" style={{marginTop:16,display:"flex",justifyContent:"space-between",alignItems:"center",gap:12,flexWrap:"wrap"}}>
          <div style={{display:"flex",flexDirection:"column",gap:6}}>
            <span style={{...B,fontSize:13,color:C.sub}}>Já tem conta? <span onClick={onBack} style={{color:C.green,cursor:"pointer",fontWeight:600}}>Fazer login</span></span>
            <span onClick={saveAndExit} style={{...B,fontSize:12,color:C.muted,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:6,userSelect:"none"}}>
              <span>💾</span>
              <span style={{borderBottom:`1px dashed ${C.muted}`}}>Salvar e continuar depois</span>
            </span>
          </div>
          <Btn label={step===10?"Criar minha conta →":"Continuar →"} variant="primary" size="lg" onClick={handleNext} loading={submitting} />
        </div>

        {/* Toast: cadastro salvo */}
        {savedToast && (
          <div style={{position:"fixed",bottom:24,left:"50%",transform:"translateX(-50%)",background:C.green,color:"#fff",padding:"12px 22px",borderRadius:10,boxShadow:"0 12px 32px rgba(0,0,0,.25)",...H,fontSize:14,fontWeight:700,zIndex:9999,display:"flex",alignItems:"center",gap:10}}>
            <span>✓</span> Cadastro salvo. Você pode voltar a qualquer momento neste navegador.
          </div>
        )}

        {/* Modal: continuar no celular (QR code) */}
        {qrModalOpen && (
          <div onClick={()=>setQrModalOpen(false)} style={{position:"fixed",inset:0,background:"rgba(10,22,40,.6)",backdropFilter:"blur(4px)",zIndex:9998,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
            <div onClick={e=>e.stopPropagation()} style={{background:"#fff",borderRadius:16,maxWidth:420,width:"100%",padding:"28px 28px 24px",boxShadow:"0 24px 60px rgba(0,0,0,.3)",position:"relative"}}>
              <button onClick={()=>setQrModalOpen(false)} style={{position:"absolute",top:14,right:14,width:32,height:32,borderRadius:16,border:"none",background:C.bg,cursor:"pointer",...H,fontSize:18,color:C.muted}}>×</button>
              <div style={{...H,fontSize:18,fontWeight:800,color:C.navy,marginBottom:6}}>📱 Continuar no celular</div>
              <p style={{...B,fontSize:13,color:C.sub,marginBottom:18,lineHeight:1.5}}>Escaneie o QR code com a câmera do seu celular para abrir esta página e enviar a foto pelo seu dispositivo móvel.</p>
              <div style={{display:"flex",justifyContent:"center",marginBottom:14}}>
                <img src={`https://api.qrserver.com/v1/create-qr-code/?size=240x240&data=${encodeURIComponent("https://giobbis.vercel.app")}&bgcolor=ffffff&color=0A1628&qzone=2`}
                  alt="QR code para celular"
                  style={{width:200,height:200,borderRadius:10,border:`1px solid ${C.border}`}} />
              </div>
              <div style={{...B,fontSize:12,fontWeight:600,color:C.navy,textAlign:"center",marginBottom:14,padding:"8px 12px",background:C.bg,borderRadius:8,border:`1px solid ${C.border}`,fontFamily:"monospace"}}>giobbis.vercel.app</div>
              <div style={{...B,fontSize:11,color:C.muted,lineHeight:1.5,padding:"10px 12px",background:C.amberBg||"#FEF3C7",border:`1px solid ${C.amberBorder||"#FDE68A"}`,borderRadius:8}}>
                <strong style={{color:C.amber||"#92400E"}}>Em breve:</strong> continuação automática (você abre no celular e o cadastro continua de onde parou). Por enquanto, ao abrir no celular, use o "Salvar e continuar depois" no mesmo navegador, ou refaça o cadastro.
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// COMPANY REGISTER — 6 steps (unchanged)
// ═══════════════════════════════════════════════════════════════
function CompanyRegister({ onDone, onBack }) {
  const [step, setStep] = useState(1);
  const [cepLoading, setCepLoading] = useState(false);
  const [uCepLoading, setUCepLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [cnpjChecking, setCnpjChecking] = useState(false);
  const [data, setData] = useState({
    cnpj:"", cnpjExists:false, razao:"", nomeFant:"", site:"", seg:"",
    cep:"", rua:"", numero:"", complemento:"", bairro:"", cidade:"", estado:"",
    respNome:"", respCargo:"", respTel:"", respEmail:"",
    unidades:[],
    email:"", senha:"", confirma:"",
  });
  const [newUnit, setNewUnit] = useState({nome:"",cep:"",rua:"",numero:"",complemento:"",bairro:"",cidade:"",estado:""});
  const set = (k,v) => setData(d=>({...d,[k]:v}));
  const senhaError = data.confirma&&data.senha!==data.confirma?"Senhas não coincidem":"";

  const checkCNPJ = async (cnpj) => {
    const raw = cnpj.replace(/\D/g,"");
    if(raw.length!==14) return;
    setCnpjChecking(true);
    const { data: existing } = await supabase.from("companies").select("id").eq("cnpj", cnpj).maybeSingle();
    setCnpjChecking(false);
    set("cnpjExists", !!existing);
  };

  const addUnit = () => {
    if(!newUnit.nome||!newUnit.cep||!newUnit.rua||!newUnit.numero) return;
    setData(d=>({...d,unidades:[...d.unidades,{...newUnit,id:Date.now()}]}));
    setNewUnit({nome:"",cep:"",rua:"",numero:"",complemento:"",bairro:"",cidade:"",estado:""});
  };

  const canNext = {
    1: data.cnpj.replace(/\D/g,"").length===14&&!data.cnpjExists&&data.razao&&data.seg,
    2: data.cep&&data.rua&&data.numero&&data.bairro&&data.cidade,
    3: data.respNome&&data.respCargo&&data.respTel.replace(/\D/g,"").length>=10&&data.respEmail,
    4: true, 5: true,
    6: data.email&&data.senha.length>=8&&!senhaError,
  }[step];

  const next = async () => {
    if(step<6){ setStep(s=>s+1); return; }
    setSubmitting(true); setSubmitError("");
    try { const saved=await saveCompany(data); onDone({...data,id:saved.id}); }
    catch(e){ setSubmitError(e.message||"Erro ao salvar. Tente novamente."); }
    finally { setSubmitting(false); }
  };
  const back = ()=>step>1?setStep(s=>s-1):onBack();
  const LABELS = ["Dados corporativos","Endereço da sede","Responsável","Unidades de trabalho","Como funciona","Criar conta"];

  return (
    <div style={{minHeight:"90vh",padding:"32px 20px 80px",background:C.bg}}>
      <div style={{maxWidth:620,margin:"0 auto"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
          <button onClick={back} style={{...B,fontSize:13,color:C.sub,background:"none",border:"none",cursor:"pointer"}}>← {step>1?"Voltar":"Cancelar"}</button>
          <Prog step={step} total={6} />
        </div>
        <div style={{...B,fontSize:12,color:C.muted,marginBottom:20}}>{LABELS[step-1]}</div>
        <div className="fu" key={step} style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:16,padding:"32px 36px",boxShadow:"0 2px 16px rgba(0,0,0,.05)"}}>

          {step===1&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Dados da empresa</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Usaremos o CNPJ para verificar sua empresa na Receita Federal.</p>
            <div className="g2">
              <div>
                <label style={{...B,fontSize:12,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>CNPJ <span style={{color:C.red}}>*</span></label>
                <input placeholder="00.000.000/0000-00" value={data.cnpj} maxLength={18}
                  onChange={e=>{ set("cnpjExists",false); set("cnpj",maskCNPJ(e.target.value)); }}
                  onBlur={()=>checkCNPJ(data.cnpj)}
                  style={{width:"100%",padding:"11px 14px",borderRadius:8,border:`1.5px solid ${data.cnpjExists?C.red:C.border2}`,background:"#fff",...B,fontSize:14,color:C.text,outline:"none"}} />
                {cnpjChecking&&<div style={{...B,fontSize:11,color:C.muted,marginTop:5}}>🔍 Verificando CNPJ...</div>}
                {data.cnpjExists&&<div style={{...B,fontSize:11,color:C.red,marginTop:5}}>⚠ CNPJ já cadastrado — se já tem conta, faça login.</div>}
                {!data.cnpjExists&&!cnpjChecking&&data.cnpj.replace(/\D/g,"").length===14&&<div style={{...B,fontSize:11,color:C.green,marginTop:5}}>✓ CNPJ disponível</div>}
              </div>
              <Field label="Nome fantasia" placeholder="Como aparece no sistema" value={data.nomeFant} onChange={v=>set("nomeFant",v)} />
            </div>
            <Field label="Razão social" placeholder="Nome Fantasia Ltda." value={data.razao} onChange={v=>set("razao",v)} required />
            <Field label="Site" placeholder="https://www.suaempresa.com.br" value={data.site} onChange={v=>set("site",v)} helper="Opcional" />
            <div>
              <label style={{...B,fontSize:12,fontWeight:600,color:C.sub,display:"block",marginBottom:8}}>Segmento <span style={{color:C.red}}>*</span></label>
              <div style={{display:"flex",flexWrap:"wrap",gap:8}}>
                {SEGS.map(s=><div key={s} onClick={()=>set("seg",s)} style={{padding:"7px 14px",borderRadius:7,cursor:"pointer",border:`1.5px solid ${data.seg===s?C.green:C.border2}`,background:data.seg===s?C.greenBg:"transparent",...B,fontSize:13,fontWeight:data.seg===s?600:400,color:data.seg===s?C.green:C.sub,transition:"all .15s"}}>{s}</div>)}
              </div>
            </div>
          </>}
          {step===2&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Endereço da sede</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Endereço principal. As unidades são configuradas no próximo passo.</p>
            <AddressBlock data={data} setData={setData} loading={cepLoading} setLoading={setCepLoading} />
          </>}
          {step===3&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Responsável</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Quem vai gerenciar as vagas e contratações.</p>
            <Field label="Nome completo" placeholder="Maria Souza" value={data.respNome} onChange={v=>set("respNome",v)} required />
            <Field label="Cargo" placeholder="Gerente de Operações" value={data.respCargo} onChange={v=>set("respCargo",v)} required />
            <div className="g2">
              <Field label="WhatsApp" placeholder="(11) 99999-9999" value={data.respTel} onChange={v=>set("respTel",maskPhone(v))} type="tel" maxLength={15} required />
              <Field label="E-mail direto" placeholder="maria@empresa.com.br" value={data.respEmail} onChange={v=>set("respEmail",v)} type="email" required />
            </div>
          </>}
          {step===4&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Unidades de trabalho</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:20,lineHeight:1.65}}>Cada vaga é vinculada a uma unidade. O colaborador vê a distância exata.</p>
            {data.unidades.map(u=>(
              <div key={u.id} style={{background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:12,padding:"14px 18px",marginBottom:10,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <div>
                  <div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>{u.nome}</div>
                  <div style={{...B,fontSize:12,color:C.sub,marginTop:2}}>{u.rua}, {u.numero} — {u.cidade}/{u.estado}</div>
                </div>
                <button onClick={()=>setData(d=>({...d,unidades:d.unidades.filter(x=>x.id!==u.id)}))}
                  style={{background:C.redBg,border:`1px solid ${C.redBorder}`,borderRadius:7,padding:"5px 10px",cursor:"pointer",...B,fontSize:12,color:C.red}}>Remover</button>
              </div>
            ))}
            <div style={{background:C.bg,border:`1.5px dashed ${C.border2}`,borderRadius:14,padding:22}}>
              <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:14}}>{data.unidades.length===0?"Adicionar primeira unidade":"+ Nova unidade"}</div>
              <Field label="Nome da unidade" placeholder="Ex: Loja Lapa, CD Guarulhos" value={newUnit.nome} onChange={v=>setNewUnit(u=>({...u,nome:v}))} />
              <AddressBlock data={newUnit} setData={setNewUnit} loading={uCepLoading} setLoading={setUCepLoading} />
              <Btn label="+ Adicionar unidade" variant={newUnit.nome&&newUnit.cep&&newUnit.rua&&newUnit.numero?"primary":"ghost"} size="md" onClick={addUnit} disabled={!newUnit.nome||!newUnit.cep||!newUnit.rua||!newUnit.numero} />
            </div>
            {data.unidades.length===0&&<Alert type="warning" style={{marginTop:14}}>Adicione ao menos uma unidade.</Alert>}
            {data.unidades.length>0&&<Alert type="success" style={{marginTop:14}}>{data.unidades.length} unidade{data.unidades.length>1?"s":""} cadastrada{data.unidades.length>1?"s":""}.</Alert>}
          </>}
          {step===5&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Como o VORKER funciona</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Entenda antes de finalizar.</p>
            {[
              {icon:"👁",t:"Você escolhe quem trabalha",d:"No Talent Browser você vê perfis verificados, filtra por especialidade e nível, e convida diretamente."},
              {icon:"📋",t:"Publique vagas por unidade",d:"Cada vaga é vinculada a uma de suas unidades. Colaboradores veem a distância exata."},
              {icon:"🔒",t:"Perfis verificados",d:"Documentos conferidos antes de aparecerem na plataforma."},
              {icon:"⭐",t:"Avaliação bidirecional",d:"Empresa e colaborador se avaliam ao final de cada turno."},
              {icon:"⚖️",t:"Você é o contratante",d:"O VORKER conecta. O vínculo é entre sua empresa e o colaborador."},
            ].map(({icon,t,d})=>(
              <div key={t} style={{display:"flex",gap:14,marginBottom:16,paddingBottom:16,borderBottom:`1px solid ${C.border}`}}>
                <div style={{width:40,height:40,borderRadius:10,background:C.greenBg,border:`1px solid ${C.greenBorder}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,flexShrink:0}}>{icon}</div>
                <div><div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:3}}>{t}</div><div style={{...B,fontSize:13,color:C.sub,lineHeight:1.65}}>{d}</div></div>
              </div>
            ))}
          </>}
          {step===6&&<>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Criar conta</h2>
            <p style={{...B,fontSize:14,color:C.sub,marginBottom:22,lineHeight:1.65}}>Dados de acesso ao painel da empresa.</p>
            <Field label="E-mail de acesso" placeholder="acesso@empresa.com.br" value={data.email} onChange={v=>set("email",v)} type="email" required />
            <div className="g2">
              <Field label="Senha" placeholder="Mínimo 8 caracteres" value={data.senha} onChange={v=>set("senha",v)} type="password" required />
              <Field label="Confirmar senha" placeholder="Repita a senha" value={data.confirma} onChange={v=>set("confirma",v)} type="password" hint={senhaError} required />
            </div>
            <Div />
            <div style={{...B,fontSize:11,color:C.muted,fontWeight:700,letterSpacing:.8,textTransform:"uppercase",marginBottom:12}}>Resumo</div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"5px 24px"}}>
              {[["Empresa",data.nomeFant||data.razao],["CNPJ",data.cnpj],["Segmento",data.seg],["Sede",`${data.cidade}/${data.estado}`],["Responsável",data.respNome],["Unidades",`${data.unidades.length} cadastrada${data.unidades.length!==1?"s":""}`]].map(([k,v])=>(
                <div key={k} style={{display:"flex",justifyContent:"space-between",padding:"5px 0",borderBottom:`1px solid ${C.border}`}}>
                  <span style={{...B,fontSize:12,color:C.muted}}>{k}</span>
                  <span style={{...B,fontSize:12,color:C.navy,fontWeight:600}}>{v||"—"}</span>
                </div>
              ))}
            </div>
            {submitError&&<Alert type="error" style={{marginTop:14}}>{submitError}</Alert>}
          </>}
        </div>
        <div style={{marginTop:20,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <span style={{...B,fontSize:13,color:C.sub}}>Já tem conta? <span onClick={onBack} style={{color:C.green,cursor:"pointer",fontWeight:600}}>Fazer login</span></span>
          <Btn label={step===6?"Cadastrar empresa →":"Continuar →"} variant="primary" size="lg" onClick={next} disabled={!canNext} loading={submitting} />
        </div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// SUCCESS SCREENS
// ═══════════════════════════════════════════════════════════════
function CompanySuccess({ data, onEnter }) {
  return (
    <div style={{minHeight:"75vh",display:"flex",alignItems:"center",justifyContent:"center",padding:"60px 20px",background:C.bg}}>
      <div style={{maxWidth:480,width:"100%",textAlign:"center"}}>
        <div style={{width:96,height:96,borderRadius:48,background:C.greenBg,border:`3px solid ${C.green}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:44,margin:"0 auto 24px",animation:"popIn .4s ease both"}}>🏢</div>
        <h2 style={{...H,fontSize:34,fontWeight:900,color:C.navy,letterSpacing:-1.2,lineHeight:1,marginBottom:14}}>Cadastro enviado!</h2>
        <p style={{...B,fontSize:15,color:C.sub,lineHeight:1.75,marginBottom:22}}><strong style={{color:C.navy}}>{data?.nomeFant||data?.razao}</strong> está em análise. Retorno em até <strong style={{color:C.green}}>24 horas úteis</strong>.</p>
        <Alert type="success">Cadastro salvo com sucesso no sistema VORKER! ✓</Alert>
        <Btn label="Voltar ao início" variant="primary" size="xl" full onClick={onEnter} />
      </div>
    </div>
  );
}

function WorkerSuccess({ data, onEnter }) {
  return (
    <div style={{minHeight:"75vh",display:"flex",alignItems:"center",justifyContent:"center",padding:"60px 20px",background:C.bg}}>
      <div style={{maxWidth:480,width:"100%",textAlign:"center"}}>
        <div style={{width:96,height:96,borderRadius:48,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 24px",animation:"popIn .4s ease both",overflow:"hidden"}}>
          {data?.fotoRosto?<img src={data.fotoRosto} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}} />:<span style={{fontSize:42,color:"#fff"}}>✓</span>}
        </div>
        <h2 style={{...H,fontSize:34,fontWeight:900,color:C.navy,letterSpacing:-1.2,lineHeight:1,marginBottom:14}}>Cadastro enviado,<br />{data?.nome?.split(" ")[0]}!</h2>
        <p style={{...B,fontSize:15,color:C.sub,lineHeight:1.75,marginBottom:22}}>Nossa equipe vai revisar seu documento. Em até <strong style={{color:C.green}}>48 horas úteis</strong> você receberá confirmação.</p>
        <Alert type="success">Cadastro salvo com sucesso! ✓</Alert>
        <Btn label="Voltar ao início" variant="primary" size="xl" full onClick={onEnter} />
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// ADMIN LOGIN
// ═══════════════════════════════════════════════════════════════
function AdminLogin({ onLogin }) {
  const [email,setEmail]=useState(""); const [pass,setPass]=useState(""); const [error,setError]=useState(""); const [loading,setLoading]=useState(false);
  const handleLogin = async () => {
    setLoading(true); await new Promise(r=>setTimeout(r,600)); setLoading(false);
    if(email==="admin@vorker.com"&&pass==="vorker2024") onLogin();
    else setError("E-mail ou senha incorretos.");
  };
  return (
    <div style={{minHeight:"75vh",display:"flex",alignItems:"center",justifyContent:"center",padding:"60px 20px",background:C.bg}}>
      <div style={{maxWidth:400,width:"100%"}}>
        <div style={{textAlign:"center",marginBottom:32}}>
          <div style={{width:56,height:56,background:C.navy,borderRadius:14,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 16px",fontSize:26}}>🔐</div>
          <h2 style={{...H,fontSize:28,fontWeight:900,color:C.navy,marginBottom:6}}>Admin VORKER</h2>
          <p style={{...B,fontSize:14,color:C.muted}}>Acesso restrito à equipe interna</p>
        </div>
        <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:28,boxShadow:"0 4px 20px rgba(0,0,0,.06)"}}>
          <Field label="E-mail" placeholder="admin@vorker.com" value={email} onChange={setEmail} type="email" />
          <Field label="Senha" placeholder="••••••••" value={pass} onChange={setPass} type="password" />
          {error&&<Alert type="error">{error}</Alert>}
          <Btn label="Acessar painel" variant="navy" size="lg" full onClick={handleLogin} loading={loading} />
        </div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// ADMIN PANEL
// ═══════════════════════════════════════════════════════════════
function AdminPanel({ onLogout }) {
  const [tab, setTab] = useState("dashboard");
  const [companies, setCompanies] = useState([]);
  const [workers, setWorkers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selCompany, setSelCompany] = useState(null);
  const [selWorker, setSelWorker] = useState(null);
  const [rejectModal,  setRejectModal]  = useState(null);
  const [rejectNote,   setRejectNote]   = useState("");
  const [deleteModal,  setDeleteModal]  = useState(null);
  const [saving,  setSaving]  = useState(false);
  const [search,  setSearch]  = useState("");
  const [adminNotes, setAdminNotes] = useState("");
  useEffect(()=>{
    if(selWorker?.id){
      try { setAdminNotes(localStorage.getItem(`vorker:notes:${selWorker.id}`) || ""); } catch { setAdminNotes(""); }
    } else { setAdminNotes(""); }
  },[selWorker?.id]);
  const saveAdminNotes = (txt) => {
    setAdminNotes(txt);
    try { if(selWorker?.id) localStorage.setItem(`vorker:notes:${selWorker.id}`, txt); } catch {}
  };

  const load = async () => {
    setLoading(true);
    try { const [cos,wos]=await Promise.all([fetchCompanies(),fetchWorkers()]); setCompanies(cos||[]); setWorkers(wos||[]); }
    catch(e){ console.error(e); } finally { setLoading(false); }
  };
  useEffect(()=>{ load(); },[]);

  const updateCo = async (id,changes) => { setSaving(true); await updateCompanyDB(id,changes); setCompanies(cs=>cs.map(c=>c.id===id?{...c,...changes}:c)); setSelCompany(s=>s?.id===id?{...s,...changes}:s); setSaving(false); };
  const updateWo = async (id,changes) => { setSaving(true); await updateWorkerDB(id,changes); setWorkers(ws=>ws.map(w=>w.id===id?{...w,...changes}:w)); setSelWorker(s=>s?.id===id?{...s,...changes}:s); setSaving(false); };

  const deleteCo = async (id) => {
    setSaving(true);
    try { await deleteCompanyDB(id); setCompanies(cs=>cs.filter(c=>c.id!==id)); setSelCompany(null); setDeleteModal(null); }
    catch(e){ alert("Erro ao excluir."); } finally { setSaving(false); }
  };
  const deleteWo = async (id) => {
    setSaving(true);
    try { await deleteWorkerDB(id); setWorkers(ws=>ws.filter(w=>w.id!==id)); setSelWorker(null); setDeleteModal(null); }
    catch(e){ alert("Erro ao excluir."); } finally { setSaving(false); }
  };

  const pending_co  = companies.filter(c=>c.status==="pending").length;
  const pending_wo  = workers.filter(w=>w.status==="pending").length;
  const approved_co = companies.filter(c=>c.status==="approved").length;
  const overdue     = companies.filter(c=>c.pay_status==="overdue").length;
  const fmtDate     = iso => iso?new Date(iso).toLocaleDateString("pt-BR"):"—";
  const levelColors = ["#9CA3AF","#60A5FA","#FBBF24","#F97316","#16A34A"];
  const levelWidth  = [0,25,50,75,100];

  const NAV = [
    {id:"dashboard",icon:"📊",label:"Dashboard"},
    {id:"companies",icon:"🏢",label:`Empresas${pending_co>0?` (${pending_co})`:""}`},
    {id:"workers",  icon:"👥",label:`Colaboradores${pending_wo>0?` (${pending_wo})`:""}`},
    {id:"billing",  icon:"💳",label:"Cobranças"},
  ];

  const RejectModal = () => (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <div style={{background:C.white,borderRadius:16,padding:28,maxWidth:440,width:"100%",boxShadow:"0 20px 60px rgba(0,0,0,.15)"}}>
        <h3 style={{...H,fontSize:20,fontWeight:800,color:C.navy,marginBottom:6}}>Reprovar cadastro</h3>
        <p style={{...B,fontSize:14,color:C.sub,marginBottom:16,lineHeight:1.65}}>Informe o motivo. Será enviado por e-mail.</p>
        <div style={{marginBottom:16}}>
          <label style={{...B,fontSize:12,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>Motivo *</label>
          <textarea value={rejectNote} onChange={e=>setRejectNote(e.target.value)} placeholder="Ex: Documento ilegível. Por favor reenvie com melhor iluminação."
            style={{width:"100%",padding:"11px 14px",borderRadius:8,border:`1.5px solid ${C.border2}`,...B,fontSize:14,color:C.text,minHeight:100,resize:"vertical"}} />
        </div>
        <div style={{display:"flex",gap:10}}>
          <Btn label="Cancelar" variant="ghost" size="md" full onClick={()=>{setRejectModal(null);setRejectNote("");}} />
          <Btn label="Confirmar reprovação" variant="danger" size="md" full disabled={!rejectNote} loading={saving}
            onClick={async()=>{
              if(rejectModal.type==="company") await updateCo(rejectModal.id,{status:"rejected",reject_note:rejectNote,pay_status:"inactive"});
              else await updateWo(rejectModal.id,{status:"rejected",reject_note:rejectNote});
              setRejectModal(null); setRejectNote("");
            }} />
        </div>
      </div>
    </div>
  );

  const AdminDeleteModal = () => (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <div style={{background:C.white,borderRadius:16,padding:28,maxWidth:420,width:"100%",boxShadow:"0 20px 60px rgba(0,0,0,.15)"}}>
        <h3 style={{...H,fontSize:20,fontWeight:800,color:C.red,marginBottom:8}}>⚠ Excluir permanentemente</h3>
        <p style={{...B,fontSize:14,color:C.sub,marginBottom:8,lineHeight:1.65}}>Você está prestes a excluir <strong>{deleteModal?.name}</strong>.</p>
        <Alert type="error">Esta ação é irreversível. Todos os dados serão apagados do sistema.</Alert>
        <div style={{display:"flex",gap:10,marginTop:8}}>
          <Btn label="Cancelar" variant="ghost" size="md" full onClick={()=>setDeleteModal(null)} />
          <Btn label="Excluir definitivamente" variant="danger" size="md" full loading={saving}
            onClick={()=>deleteModal.type==="company"?deleteCo(deleteModal.id):deleteWo(deleteModal.id)} />
        </div>
      </div>
    </div>
  );

  if(loading) return (
    <div style={{display:"flex",alignItems:"center",justifyContent:"center",minHeight:"60vh",flexDirection:"column",gap:16}}>
      <span style={{width:36,height:36,borderRadius:18,border:`3px solid ${C.border2}`,borderTopColor:C.green,animation:"spin .8s linear infinite",display:"block"}} />
      <div style={{...B,fontSize:14,color:C.muted}}>Carregando dados...</div>
    </div>
  );

  return (
    <>
    <header className="hdr">
      <div style={{width:"100%",padding:"0 24px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:24}}>
        <div style={{display:"flex",alignItems:"center",gap:14}}>
          <img src={VORKER_LOGO} alt="Giobbi's" style={{height:38,objectFit:"contain"}} />
          <span style={{...H,fontSize:11,fontWeight:700,color:C.green,letterSpacing:.5,textTransform:"uppercase",padding:"4px 10px",background:C.greenBg,borderRadius:6,border:`1px solid ${C.greenBorder}`}}>Painel Admin</span>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:12}}>
          <span style={{...B,fontSize:13,color:C.sub}}>Olá, Admin</span>
          <Btn label="Sair" variant="ghost" size="sm" onClick={onLogout} />
        </div>
      </div>
    </header>
    <div style={{display:"grid",gridTemplateColumns:"220px 1fr",minHeight:"calc(100vh - 60px)"}}>
      {rejectModal&&<RejectModal />}
      {deleteModal&&<AdminDeleteModal />}
      <aside style={{background:C.white,borderRight:`1px solid ${C.border}`,padding:"20px 0",position:"sticky",top:60,height:"calc(100vh - 60px)",overflowY:"auto"}}>
        <div style={{padding:"0 16px 18px",borderBottom:`1px solid ${C.border}`,marginBottom:10}}>
          <div style={{...B,fontSize:11,fontWeight:700,color:C.muted,letterSpacing:1,textTransform:"uppercase",marginBottom:4}}>Painel Interno</div>
          <div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>Equipe VORKER</div>
          <button onClick={load} style={{...B,fontSize:11,color:C.green,background:"none",border:"none",cursor:"pointer",marginTop:6,fontWeight:600}}>↻ Atualizar</button>
        </div>
        {NAV.map(n=>(
          <div key={n.id} className={`admin-item ${tab===n.id?"active":""}`} onClick={()=>{setTab(n.id);setSelCompany(null);setSelWorker(null);}}>
            <span style={{fontSize:16}}>{n.icon}</span>
            <span style={{...B,fontSize:13,color:tab===n.id?C.green:C.sub}}>{n.label}</span>
          </div>
        ))}
        <Div />
        <div style={{padding:"0 14px"}}>
          {pending_co>0&&<div style={{background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:9,padding:"10px 12px",marginBottom:8,...B,fontSize:12,color:C.amber}}>⏳ {pending_co} empresa{pending_co>1?"s":""} pendente{pending_co>1?"s":""}</div>}
          {pending_wo>0&&<div style={{background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:9,padding:"10px 12px",marginBottom:8,...B,fontSize:12,color:C.amber}}>⏳ {pending_wo} colaborador{pending_wo>1?"es":""} pendente{pending_wo>1?"s":""}</div>}
          {overdue>0&&<div style={{background:C.redBg,border:`1px solid ${C.redBorder}`,borderRadius:9,padding:"10px 12px",...B,fontSize:12,color:C.red}}>! {overdue} em atraso</div>}
          {pending_co===0&&pending_wo===0&&overdue===0&&<div style={{...B,fontSize:12,color:C.green}}>✓ Tudo em dia</div>}
        </div>
      </aside>

      <main style={{padding:"28px 32px",background:C.bg,minWidth:0}}>

        {tab==="dashboard"&&(
          <div>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Dashboard</h2>
            <p style={{...B,fontSize:14,color:C.muted,marginBottom:24}}>Visão geral da plataforma</p>
            <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:14,marginBottom:28}}>
              {[{v:companies.length,l:"Empresas",c:C.navy,icon:"🏢",sub:`${pending_co} pendentes`},{v:workers.length,l:"Colaboradores",c:C.blue,icon:"👥",sub:`${pending_wo} pendentes`},{v:approved_co,l:"Ativas",c:C.green,icon:"✓",sub:"empresas aprovadas"},{v:overdue,l:"Em atraso",c:C.red,icon:"⚠",sub:"inadimplentes"}].map(({v,l,c,icon,sub})=>(
                <div key={l} style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:"20px 18px"}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}><span style={{fontSize:22}}>{icon}</span><div style={{...H,fontSize:30,fontWeight:900,color:c}}>{v}</div></div>
                  <div style={{...H,fontSize:13,fontWeight:700,color:C.navy}}>{l}</div>
                  <div style={{...B,fontSize:11,color:C.muted,marginTop:2}}>{sub}</div>
                </div>
              ))}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:20}}>
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,overflow:"hidden"}}>
                <div style={{padding:"14px 20px",borderBottom:`1px solid ${C.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>Empresas pendentes</div>
                </div>
                {companies.filter(c=>c.status==="pending").length===0?<div style={{padding:32,textAlign:"center",...B,fontSize:13,color:C.muted}}>Nenhuma ✓</div>:companies.filter(c=>c.status==="pending").map(co=>(
                  <div key={co.id} className="card-h" onClick={()=>{setTab("companies");setSelCompany(co);}} style={{padding:"14px 20px",borderBottom:`1px solid ${C.border}`}}>
                    <div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>{co.nome_fant||co.razao}</div>
                    <div style={{...B,fontSize:12,color:C.muted}}>{co.seg} · {co.cidade} · {fmtDate(co.created_at)}</div>
                  </div>
                ))}
              </div>
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,overflow:"hidden"}}>
                <div style={{padding:"14px 20px",borderBottom:`1px solid ${C.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>Colaboradores pendentes</div>
                </div>
                {workers.filter(w=>w.status==="pending").length===0?<div style={{padding:32,textAlign:"center",...B,fontSize:13,color:C.muted}}>Nenhum ✓</div>:workers.filter(w=>w.status==="pending").map(wo=>(
                  <div key={wo.id} className="card-h" onClick={()=>{setTab("workers");setSelWorker(wo);}} style={{padding:"14px 20px",borderBottom:`1px solid ${C.border}`}}>
                    <div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>{wo.nome}</div>
                    <div style={{...B,fontSize:12,color:C.muted}}>{wo.cidade} · {wo.specs?.length||0} especialidades · {fmtDate(wo.created_at)}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {tab==="companies"&&!selCompany&&(
          <div>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:16}}>Empresas</h2>
            <input placeholder="🔍 Buscar por nome ou CNPJ..." value={search} onChange={e=>setSearch(e.target.value)}
              style={{width:"100%",maxWidth:400,padding:"9px 14px",borderRadius:8,border:`1.5px solid ${C.border2}`,background:"#fff",...B,fontSize:13,marginBottom:16,outline:"none"}} />
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,overflow:"hidden"}}>
              <div style={{display:"grid",gridTemplateColumns:"2fr 1fr 1fr 1fr 1fr",padding:"12px 20px",borderBottom:`1px solid ${C.border}`,background:C.bg}}>
                {["Empresa","Segmento","Unidades","Status","Pagamento"].map(h=><div key={h} style={{...B,fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:.5}}>{h}</div>)}
              </div>
              {companies.filter(c=>!search||(c.nome_fant||c.razao||"").toLowerCase().includes(search.toLowerCase())||c.cnpj?.includes(search)).length===0
                ?<div style={{padding:48,textAlign:"center",...B,fontSize:14,color:C.muted}}>Nenhuma empresa encontrada.</div>
                :companies.filter(c=>!search||(c.nome_fant||c.razao||"").toLowerCase().includes(search.toLowerCase())||c.cnpj?.includes(search)).map(co=>(
                <div key={co.id} className="card-h" onClick={()=>setSelCompany(co)} style={{display:"grid",gridTemplateColumns:"2fr 1fr 1fr 1fr 1fr",padding:"14px 20px",borderBottom:`1px solid ${C.border}`,alignItems:"center"}}>
                  <div><div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>{co.nome_fant||co.razao}</div><div style={{...B,fontSize:12,color:C.muted}}>{co.cnpj} · {co.cidade}/{co.estado}</div></div>
                  <div style={{...B,fontSize:13,color:C.sub}}>{co.seg}</div>
                  <div style={{...B,fontSize:13,color:C.sub}}>{co.company_units?.length||0}</div>
                  <Badge status={co.status} />
                  <Badge status={co.pay_status} />
                </div>
              ))}
            </div>
          </div>
        )}

        {tab==="companies"&&selCompany&&(
          <div>
            <button onClick={()=>setSelCompany(null)} style={{...B,fontSize:13,color:C.sub,background:"none",border:"none",cursor:"pointer",marginBottom:22}}>← Voltar</button>
            <div style={{display:"grid",gridTemplateColumns:"1fr 280px",gap:20,alignItems:"start"}}>
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:28}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:22}}>
                  <div><h3 style={{...H,fontSize:22,fontWeight:900,color:C.navy,marginBottom:4}}>{selCompany.nome_fant||selCompany.razao}</h3><div style={{...B,fontSize:13,color:C.muted}}>{selCompany.razao}</div></div>
                  <div style={{display:"flex",gap:8}}><Badge status={selCompany.status} /><Badge status={selCompany.pay_status} /></div>
                </div>
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"8px 32px",marginBottom:20}}>
                  {[["CNPJ",selCompany.cnpj],["Segmento",selCompany.seg],["Site",selCompany.site||"—"],["Cadastro",fmtDate(selCompany.created_at)],["Cidade",`${selCompany.cidade}/${selCompany.estado}`]].map(([k,v])=>(
                    <div key={k} style={{padding:"7px 0",borderBottom:`1px solid ${C.border}`}}><div style={{...B,fontSize:11,color:C.muted,marginBottom:2}}>{k}</div><div style={{...B,fontSize:13,color:C.navy,fontWeight:600}}>{v}</div></div>
                  ))}
                </div>
                <Div />
                <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:14}}>Responsável</div>
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"8px 32px",marginBottom:20}}>
                  {[["Nome",selCompany.resp_nome],["Cargo",selCompany.resp_cargo],["WhatsApp",selCompany.resp_tel],["E-mail",selCompany.resp_email]].map(([k,v])=>(
                    <div key={k} style={{padding:"7px 0",borderBottom:`1px solid ${C.border}`}}><div style={{...B,fontSize:11,color:C.muted,marginBottom:2}}>{k}</div><div style={{...B,fontSize:13,color:C.navy,fontWeight:600}}>{v||"—"}</div></div>
                  ))}
                </div>
                {selCompany.company_units?.length>0&&<>
                  <Div />
                  <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:12}}>Unidades ({selCompany.company_units.length})</div>
                  {selCompany.company_units.map(u=>(
                    <div key={u.id} style={{background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:10,padding:"12px 16px",marginBottom:8}}>
                      <div style={{...H,fontSize:13,fontWeight:700,color:C.navy}}>{u.nome}</div>
                      <div style={{...B,fontSize:12,color:C.sub,marginTop:2}}>{u.rua}, {u.numero} — {u.cidade}/{u.estado}</div>
                    </div>
                  ))}
                </>}
                {selCompany.reject_note&&<><Div /><Alert type="error"><strong>Motivo da reprovação:</strong> {selCompany.reject_note}</Alert></>}
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:12}}>
                {selCompany.status==="pending"&&(<div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:20}}>
                  <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:14}}>Decisão</div>
                  <div style={{display:"flex",flexDirection:"column",gap:10}}>
                    <Btn label="✓ Aprovar" variant="approve" size="md" full loading={saving} onClick={()=>updateCo(selCompany.id,{status:"approved",pay_status:"trial",plan:"Trial (30 dias)"})} />
                    <Btn label="✕ Reprovar" variant="danger" size="md" full onClick={()=>setRejectModal({id:selCompany.id,type:"company"})} />
                  </div>
                </div>)}
                {selCompany.status==="approved"&&<>
                  <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:20}}>
                    <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:10}}>Plano</div>
                    {PLANS.map(p=>(
                      <div key={p} onClick={()=>updateCo(selCompany.id,{plan:p})} style={{padding:"8px 12px",borderRadius:7,cursor:"pointer",border:`1.5px solid ${selCompany.plan===p?C.green:C.border2}`,background:selCompany.plan===p?C.greenBg:"transparent",...B,fontSize:12,color:selCompany.plan===p?C.green:C.sub,marginBottom:5,transition:"all .15s"}}>
                        {selCompany.plan===p?"✓ ":""}{p}
                      </div>
                    ))}
                  </div>
                  <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:20}}>
                    <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:10}}>Pagamento</div>
                    <div style={{display:"flex",flexDirection:"column",gap:8}}>
                      <Btn label="✓ Marcar como pago" variant="approve" size="sm" full loading={saving} onClick={()=>updateCo(selCompany.id,{pay_status:"paid"})} />
                      <Btn label="! Marcar em atraso" variant="danger" size="sm" full onClick={()=>updateCo(selCompany.id,{pay_status:"overdue"})} />
                    </div>
                  </div>
                </>}
                {selCompany.status==="rejected"&&(<div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:20}}>
                  <Btn label="↩ Reabrir para análise" variant="amber" size="sm" full loading={saving} onClick={()=>updateCo(selCompany.id,{status:"pending",reject_note:"",pay_status:"trial"})} />
                </div>)}
                <div style={{background:C.white,border:`1px solid ${C.redBorder}`,borderRadius:12,padding:20}}>
                  <div style={{...H,fontSize:13,fontWeight:700,color:C.red,marginBottom:10}}>Zona de perigo</div>
                  <Btn label="🗑 Excluir empresa" variant="danger" size="sm" full onClick={()=>setDeleteModal({id:selCompany.id,name:selCompany.nome_fant||selCompany.razao,type:"company"})} />
                  <div style={{...B,fontSize:11,color:C.muted,marginTop:8}}>Remove permanentemente todos os dados desta empresa.</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {tab==="workers"&&!selWorker&&(
          <div>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:16}}>Colaboradores</h2>
            <input placeholder="🔍 Buscar por nome ou CPF..." value={search} onChange={e=>setSearch(e.target.value)}
              style={{width:"100%",maxWidth:400,padding:"9px 14px",borderRadius:8,border:`1.5px solid ${C.border2}`,background:"#fff",...B,fontSize:13,marginBottom:16,outline:"none"}} />
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,overflow:"hidden"}}>
              <div style={{display:"grid",gridTemplateColumns:"2fr 1fr 1fr 1fr",padding:"12px 20px",borderBottom:`1px solid ${C.border}`,background:C.bg}}>
                {["Colaborador","Especialidades","Disponibilidade","Status"].map(h=><div key={h} style={{...B,fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:.5}}>{h}</div>)}
              </div>
              {workers.filter(w=>!search||w.nome?.toLowerCase().includes(search.toLowerCase())||w.cpf?.includes(search)).length===0
                ?<div style={{padding:48,textAlign:"center",...B,fontSize:14,color:C.muted}}>Nenhum colaborador encontrado.</div>
                :workers.filter(w=>!search||w.nome?.toLowerCase().includes(search.toLowerCase())||w.cpf?.includes(search)).map(wo=>(
                <div key={wo.id} className="card-h" onClick={()=>setSelWorker(wo)} style={{display:"grid",gridTemplateColumns:"2fr 1fr 1fr 1fr",padding:"14px 20px",borderBottom:`1px solid ${C.border}`,alignItems:"center"}}>
                  <div><div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>{wo.nome}</div><div style={{...B,fontSize:12,color:C.muted}}>{wo.cpf} · {wo.cidade} · {fmtDate(wo.created_at)}</div></div>
                  <div style={{...B,fontSize:12,color:C.sub}}>{wo.specs?.length||0} esp.</div>
                  <div style={{...B,fontSize:12,color:C.sub}}>{wo.dias?.length||0}d</div>
                  <Badge status={wo.status} />
                </div>
              ))}
            </div>
          </div>
        )}

        {tab==="workers"&&selWorker&&(()=>{
          const score = computeWorkerScore(selWorker);
          const idade = calcIdade(selWorker.nascimento);
          const TRAIT_BY_ANSWER = {
            corrido: {
              manter:     {title:"Trabalha bem sob pressão", desc:"Mantém a velocidade fazendo o melhor possível", icon:"⚡"},
              equilibrar: {title:"Equilibra ritmo",          desc:"Equilibra velocidade e atenção",                 icon:"⚖️"},
              diminuir:   {title:"Caprichoso",                desc:"Diminui o ritmo para garantir qualidade",        icon:"🎯"},
            },
            diaADia: {
              praticas:   {title:"Mão na massa",             desc:"Tarefas práticas e operacionais",                icon:"🔧"},
              equilibrio: {title:"Organização",              desc:"Equilibra rapidez e organização",                icon:"⚖️"},
              cuidado:    {title:"Pensa com cuidado",        desc:"Pensa com cuidado em cada etapa",                icon:"🧠"},
            },
            tarefa: {
              iniciativa: {title:"Autonomia",                desc:"Tenta resolver sozinho primeiro",                icon:"👤"},
              perguntar:  {title:"Colaborativo",             desc:"Pergunta se necessário",                          icon:"💬"},
              orientacao: {title:"Pede orientação",          desc:"Pede orientação antes de começar",                icon:"📋"},
            },
            diferente: {
              ajusta:     {title:"Adaptação",                desc:"Se ajusta rápido quando algo muda",              icon:"🔄"},
              entender:   {title:"Analítico",                desc:"Tenta entender o que aconteceu",                  icon:"🔍"},
              avisar:     {title:"Comunicativo",             desc:"Prefere avisar alguém antes",                    icon:"📣"},
            },
            imprevisto: {
              resolver:   {title:"Comprometimento",          desc:"Tenta resolver e cumprir o que assumiu",         icon:"🛡"},
              aviso:      {title:"Avisa antes",              desc:"Avisa o quanto antes para não atrapalhar",       icon:"⏰"},
              cancelar:   {title:"Conservador",              desc:"Prefere cancelar quando há imprevisto",          icon:"⏸"},
            },
          };
          const alertas = [];
          if (idade!=null && idade<18) alertas.push({lv:"red",txt:"Menor de 18 anos — não pode atuar."});
          if (score.total < 50) alertas.push({lv:"red",txt:`Score baixo (${score.total}) — perfil incompleto ou pouco aderente.`});
          if (score.breakdown.documentacao < 100) alertas.push({lv:"amber",txt:"Documentação incompleta."});
          if (score.breakdown.disponibilidade < 40) alertas.push({lv:"amber",txt:"Disponibilidade muito limitada."});
          if (score.breakdown.experiencia === 0) alertas.push({lv:"amber",txt:"Sem tempo de experiência declarado."});
          if (!selWorker.perfil_trabalho || Object.keys(PERFIL_LABELS).every(k=>!selWorker.perfil_trabalho?.[k])) {
            alertas.push({lv:"amber",txt:"Perfil de trabalho não respondido."});
          }
          if (!selWorker.flexibilidade) alertas.push({lv:"amber",txt:"Flexibilidade não informada."});
          if (alertas.length===0) alertas.push({lv:"green",txt:"✓ Nenhum alerta encontrado."});
          const cellsFilled = Object.values(selWorker.disponibilidade||{}).reduce((a,b)=>a+(b?.length||0),0);
          const dispTag = cellsFilled>=14 ? {l:"Disponibilidade ampla",c:C.green,bg:C.greenBg,bd:C.greenBorder}
                          : cellsFilled>=6 ? {l:"Disponibilidade parcial",c:"#CA8A04",bg:"#FEFCE8",bd:"#FDE68A"}
                          : {l:"Disponibilidade limitada",c:C.red,bg:C.redBg,bd:C.redBorder};
          const statusInfo = {
            pending:  { label:"⏱ Aguardando análise",      bg:"#FEF3C7", color:"#92400E", border:"#FDE68A" },
            approved: { label:"✓ Aprovado na plataforma",  bg:C.greenBg, color:C.green,   border:C.greenBorder },
            paused:   { label:"⏸ Perfil pausado",          bg:C.blueBg,  color:C.blue,    border:C.blueBorder },
            rejected: { label:"✕ Reprovado",               bg:C.redBg,   color:C.red,     border:C.redBorder },
          }[selWorker.status] || { label:"—", bg:C.bg, color:C.muted, border:C.border };
          const cadastradoEm = selWorker.created_at ? new Date(selWorker.created_at).toLocaleDateString("pt-BR") : null;
          return (
          <div>
            <div style={{marginBottom:14}}>
              <button onClick={()=>setSelWorker(null)} style={{...B,fontSize:13,color:C.sub,background:"none",border:"none",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:4}}>← Voltar para candidatos</button>
            </div>

            {/* CABEÇALHO — Card único: identidade (left) + decisão (right) */}
            <div className="vorker-admin-header" style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:24,marginBottom:14,display:"grid",gridTemplateColumns:"1fr 280px",gap:24,alignItems:"stretch"}}>

              {/* Esquerda — Identidade */}
              <div className="vorker-admin-identity" style={{display:"flex",flexDirection:"column",gap:18}}>
                <div style={{display:"flex",gap:18,alignItems:"center"}}>
                  {selWorker.foto_rosto ? (
                    <img src={selWorker.foto_rosto} alt={selWorker.nome} style={{width:88,height:88,borderRadius:44,objectFit:"cover",border:`2px solid ${C.greenBorder}`,flexShrink:0}} />
                  ) : (
                    <div style={{width:88,height:88,borderRadius:44,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                      <span style={{...H,fontSize:34,fontWeight:900,color:"#fff"}}>{selWorker.nome?.[0]}</span>
                    </div>
                  )}
                  <div style={{flex:1,minWidth:0}}>
                    <h3 style={{...H,fontSize:24,fontWeight:900,color:C.navy,marginBottom:7,lineHeight:1.15}}>{selWorker.nome}</h3>
                    <div style={{display:"flex",gap:14,alignItems:"center",flexWrap:"wrap",...B,fontSize:13,color:C.sub,marginBottom:10}}>
                      <span style={{display:"inline-flex",alignItems:"center",gap:5}}><span>📍</span>{selWorker.cidade}/{selWorker.estado}</span>
                      <span>·</span>
                      <span>{selWorker.raio_km||10}km de raio</span>
                      {idade!=null && <><span>·</span><span>{idade} anos</span></>}
                    </div>
                    <div style={{display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}>
                      <span style={{display:"inline-flex",alignItems:"center",gap:5,background:statusInfo.bg,border:`1px solid ${statusInfo.border}`,borderRadius:7,padding:"4px 11px",...B,fontSize:12,fontWeight:700,color:statusInfo.color}}>{statusInfo.label}</span>
                      {cadastradoEm && <span style={{...B,fontSize:12,color:C.muted}}>Cadastrado em {cadastradoEm}</span>}
                    </div>
                  </div>
                </div>

                {/* Mini-facts row — 5 colunas */}
                <div className="vorker-admin-facts" style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:14,paddingTop:18,borderTop:`1px solid ${C.border}`}}>
                  {[
                    {icon:"🪪", label:"CPF",      value:selWorker.cpf},
                    {icon:"📱", label:"WhatsApp", value:selWorker.telefone},
                    {icon:"✉️", label:"E-mail",   value:selWorker.email},
                    {icon:"♿", label:"PCD",      value:selWorker.pcd ? (selWorker.pcd_tipo||"Sim") : "Não"},
                    {icon:"🚗", label:"Veículo",  value:selWorker.deslocamento||"—"},
                  ].map(({icon,label,value})=>(
                    <div key={label} style={{minWidth:0}}>
                      <div style={{...B,fontSize:11,color:C.muted,marginBottom:4,display:"inline-flex",alignItems:"center",gap:5}}><span>{icon}</span>{label}</div>
                      <div style={{...B,fontSize:13,fontWeight:600,color:C.navy,wordBreak:"break-all",lineHeight:1.35}}>{value||"—"}</div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Direita — Decisão do curador */}
              <div className="vorker-admin-decision" style={{display:"flex",flexDirection:"column",gap:8,paddingLeft:24,borderLeft:`1px solid ${C.border}`}}>
                <div style={{...B,fontSize:11,fontWeight:700,color:C.muted,letterSpacing:.5,textTransform:"uppercase",marginBottom:6}}>Decisão do curador</div>

                {selWorker.status==="pending" && (<>
                  <button onClick={()=>updateWo(selWorker.id,{status:"approved"})} disabled={saving}
                    style={{background:C.green,color:"#fff",border:"none",borderRadius:10,padding:"12px 16px",cursor:saving?"default":"pointer",textAlign:"left",transition:"opacity .15s",opacity:saving?.6:1}}>
                    <div style={{...H,fontSize:14,fontWeight:800,marginBottom:2}}>✓ Aprovar</div>
                    <div style={{...B,fontSize:11,color:"rgba(255,255,255,.85)"}}>Liberar para receber convites</div>
                  </button>
                  <button onClick={()=>setSelWorker(null)}
                    style={{background:"#FEFCE8",color:"#92400E",border:"1.5px solid #FDE68A",borderRadius:10,padding:"11px 16px",cursor:"pointer",textAlign:"left"}}>
                    <div style={{...H,fontSize:14,fontWeight:800,marginBottom:2}}>🕐 Revisar depois</div>
                    <div style={{...B,fontSize:11,color:"#92400E",opacity:.8}}>Adicionar à fila de revisão</div>
                  </button>
                  <button onClick={()=>setRejectModal({id:selWorker.id,type:"worker"})}
                    style={{background:C.redBg,color:C.red,border:`1.5px solid ${C.redBorder}`,borderRadius:10,padding:"11px 16px",cursor:"pointer",textAlign:"left"}}>
                    <div style={{...H,fontSize:14,fontWeight:800,marginBottom:2}}>✕ Reprovar</div>
                    <div style={{...B,fontSize:11,color:C.red,opacity:.8}}>Não aprovar candidato</div>
                  </button>
                </>)}

                {selWorker.status==="approved" && (<>
                  <div style={{padding:"12px 14px",background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:10,...B,fontSize:13,color:C.green,fontWeight:600,textAlign:"center"}}>✓ Perfil ativo</div>
                  <button onClick={()=>updateWo(selWorker.id,{status:"paused"})} disabled={saving}
                    style={{background:C.blueBg,color:C.blue,border:`1.5px solid ${C.blueBorder}`,borderRadius:10,padding:"10px 16px",cursor:saving?"default":"pointer",textAlign:"left",opacity:saving?.6:1}}>
                    <div style={{...H,fontSize:13,fontWeight:800,marginBottom:2}}>⏸ Pausar</div>
                    <div style={{...B,fontSize:11,color:C.blue,opacity:.8}}>Oculta o perfil das buscas temporariamente</div>
                  </button>
                  <button onClick={()=>updateWo(selWorker.id,{status:"rejected",reject_note:"Perfil suspenso."})} disabled={saving}
                    style={{background:C.redBg,color:C.red,border:`1.5px solid ${C.redBorder}`,borderRadius:10,padding:"10px 16px",cursor:saving?"default":"pointer",textAlign:"left",opacity:saving?.6:1}}>
                    <div style={{...H,fontSize:13,fontWeight:800,marginBottom:2}}>⛔ Suspender</div>
                    <div style={{...B,fontSize:11,color:C.red,opacity:.8}}>Remove o perfil da plataforma</div>
                  </button>
                </>)}

                {selWorker.status==="paused" && (<>
                  <div style={{padding:"12px 14px",background:C.blueBg,border:`1px solid ${C.blueBorder}`,borderRadius:10,...B,fontSize:13,color:C.blue,fontWeight:600,textAlign:"center"}}>⏸ Perfil pausado</div>
                  <button onClick={()=>updateWo(selWorker.id,{status:"approved"})} disabled={saving}
                    style={{background:C.greenBg,color:C.green,border:`1.5px solid ${C.greenBorder}`,borderRadius:10,padding:"10px 16px",cursor:saving?"default":"pointer",textAlign:"left",opacity:saving?.6:1}}>
                    <div style={{...H,fontSize:13,fontWeight:800,marginBottom:2}}>▶ Reativar</div>
                    <div style={{...B,fontSize:11,color:C.green,opacity:.8}}>Volta a aparecer nas buscas</div>
                  </button>
                  <button onClick={()=>updateWo(selWorker.id,{status:"rejected",reject_note:"Perfil suspenso."})} disabled={saving}
                    style={{background:C.redBg,color:C.red,border:`1.5px solid ${C.redBorder}`,borderRadius:10,padding:"10px 16px",cursor:saving?"default":"pointer",textAlign:"left",opacity:saving?.6:1}}>
                    <div style={{...H,fontSize:13,fontWeight:800,marginBottom:2}}>⛔ Suspender</div>
                    <div style={{...B,fontSize:11,color:C.red,opacity:.8}}>Remove o perfil da plataforma</div>
                  </button>
                </>)}

                {selWorker.status==="rejected" && (<>
                  {selWorker.reject_note && <div style={{padding:"10px 12px",background:C.redBg,border:`1px solid ${C.redBorder}`,borderRadius:9,...B,fontSize:11.5,color:C.red,lineHeight:1.5}}><strong>Motivo:</strong> {selWorker.reject_note}</div>}
                  <button onClick={()=>updateWo(selWorker.id,{status:"pending",reject_note:""})} disabled={saving}
                    style={{background:"#FEFCE8",color:"#92400E",border:"1.5px solid #FDE68A",borderRadius:10,padding:"11px 16px",cursor:saving?"default":"pointer",textAlign:"left",opacity:saving?.6:1}}>
                    <div style={{...H,fontSize:14,fontWeight:800,marginBottom:2}}>↩ Reabrir para análise</div>
                    <div style={{...B,fontSize:11,color:"#92400E",opacity:.8}}>Volta o perfil para a fila</div>
                  </button>
                </>)}
              </div>
            </div>

            {/* CORPO PRINCIPAL: 2 colunas — conteúdo | painel lateral */}
            <div className="vorker-admin-body" style={{display:"grid",gridTemplateColumns:"1fr 280px",gap:14,alignItems:"start"}}>

              <div style={{display:"flex",flexDirection:"column",gap:14}}>
                {/* ENDEREÇO (será redesenhado em parte futura) */}
                {(selWorker.rua || selWorker.cep) && (
                  <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                    <div style={{...B,fontSize:11,fontWeight:700,color:C.green,letterSpacing:.5,textTransform:"uppercase",marginBottom:10}}>📍 Endereço</div>
                    <div style={{...B,fontSize:13,color:C.navy,fontWeight:500,lineHeight:1.6}}>
                      {selWorker.rua}{selWorker.numero?`, ${selWorker.numero}`:""}{selWorker.complemento?` — ${selWorker.complemento}`:""}
                      {selWorker.bairro&&<><br/>{selWorker.bairro} · {selWorker.cidade}/{selWorker.estado}</>}
                      {selWorker.cep&&<>{" · CEP "}{selWorker.cep}</>}
                    </div>
                  </div>
                )}


                {/* DISPONIBILIDADE — linha com 7 cards de dia */}
                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14,flexWrap:"wrap",gap:8}}>
                    <div style={{display:"flex",alignItems:"center",gap:10}}>
                      <div style={{width:22,height:22,borderRadius:11,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                        <span style={{...H,fontSize:11,fontWeight:800,color:"#fff"}}>1</span>
                      </div>
                      <div style={{...B,fontSize:11,fontWeight:700,color:C.green,letterSpacing:.5,textTransform:"uppercase"}}>Disponibilidade</div>
                    </div>
                    <span style={{...B,fontSize:11,fontWeight:700,color:dispTag.c,background:dispTag.bg,border:`1px solid ${dispTag.bd}`,padding:"3px 10px",borderRadius:14}}>{dispTag.l}</span>
                  </div>

                  <div className="vorker-day-row" style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:8}}>
                    {DAYS.map(day=>{
                      const shifts=selWorker.disponibilidade?.[day]||[];
                      const primary = SHIFTS.find(s=>shifts.includes(s.id));
                      const hasAny = shifts.length>0;
                      const extra = shifts.length-1;
                      return (
                        <div key={day} style={{textAlign:"center",padding:"12px 6px",borderRadius:9,background:hasAny?"#fff":C.bg,border:`1.5px solid ${hasAny?C.border:C.border}`,display:"flex",flexDirection:"column",alignItems:"center",gap:5,position:"relative"}}>
                          <div style={{...H,fontSize:12,fontWeight:800,color:hasAny?C.green:C.muted,letterSpacing:.3}}>{day}</div>
                          {primary ? (
                            <>
                              <div style={{fontSize:22,lineHeight:1}}>{primary.icon}</div>
                              <div style={{...B,fontSize:11,fontWeight:600,color:primary.color}}>{primary.label}</div>
                            </>
                          ) : (
                            <>
                              <div style={{fontSize:22,lineHeight:1,opacity:.3}}>·</div>
                              <div style={{...B,fontSize:11,fontWeight:500,color:C.muted,fontStyle:"italic"}}>Indisponível</div>
                            </>
                          )}
                          {extra>0 && (
                            <span style={{position:"absolute",top:6,right:6,...B,fontSize:9,fontWeight:800,color:C.green,background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:8,padding:"1px 5px",lineHeight:1.4}}>+{extra}</span>
                          )}
                        </div>
                      );
                    })}
                  </div>

                  {selWorker.flexibilidade && FLEX_LABEL[selWorker.flexibilidade] && (
                    <div style={{marginTop:12,display:"flex",alignItems:"center",gap:8,...B,fontSize:12,color:C.sub}}>
                      <span style={{fontSize:14}}>{FLEX_LABEL[selWorker.flexibilidade].icon}</span>
                      <span><strong style={{color:C.navy,fontWeight:700}}>{FLEX_LABEL[selWorker.flexibilidade].desc}</strong></span>
                    </div>
                  )}
                </div>

                {/* EXPERIÊNCIA — 2 colunas: função principal + empresas */}
                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                  <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}>
                    <div style={{width:22,height:22,borderRadius:11,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                      <span style={{...H,fontSize:11,fontWeight:800,color:"#fff"}}>3</span>
                    </div>
                    <div style={{...B,fontSize:11,fontWeight:700,color:C.green,letterSpacing:.5,textTransform:"uppercase"}}>Experiência</div>
                  </div>

                  {(()=>{
                    const TIER = (tempo) => {
                      if(!tempo) return null;
                      if(tempo==="Menos de 6 meses" || tempo==="6 meses a 1 ano") return {label:"Baixa experiência", bg:"#FEE2E2", color:"#DC2626", border:"#FECACA"};
                      if(tempo==="1 a 3 anos") return {label:"Experiência média", bg:"#FEF3C7", color:"#92400E", border:"#FDE68A"};
                      return {label:"Alta experiência", bg:"#DCFCE7", color:"#16A34A", border:"#BBF7D0"};
                    };
                    const list = [
                      ...SPECS.filter(s=>selWorker.specs?.includes(s.id)).map(s=>({id:s.id,label:s.label,icon:s.icon,tempo:selWorker.func_exp?.[s.id]?.tempo})),
                      ...(selWorker.specs?.includes("custom") ? [{id:"custom",label:selWorker.spec_levels?.custom?.label||"Função própria",icon:"⭐",tempo:selWorker.func_exp?.custom?.tempo}] : []),
                    ];
                    const primary = list[0];
                    const others = list.slice(1);
                    const tier = primary ? TIER(primary.tempo) : null;

                    if(!primary) return <div style={{...B,fontSize:13,color:C.muted}}>Nenhuma função selecionada.</div>;

                    const empresas = [
                      ...(selWorker.empresas_selected||[]).map(id=>{ const e=EMPRESAS_PRESET.find(x=>x.id===id); return e ? {label:e.label,custom:false} : null; }).filter(Boolean),
                      ...(selWorker.empresas_custom||[]).map(nome=>({label:nome,custom:true})),
                    ];

                    return (
                      <div className="vorker-exp-grid" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}>

                        {/* Função principal */}
                        <div style={{padding:"16px 18px",border:`1px solid ${C.border}`,borderRadius:11,background:"#fff"}}>
                          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:12,flexWrap:"wrap"}}>
                            <div style={{flex:1,minWidth:0}}>
                              <div style={{...B,fontSize:11,color:C.muted,marginBottom:5,fontWeight:600}}>Função principal</div>
                              <div style={{...H,fontSize:17,fontWeight:800,color:C.navy,display:"flex",alignItems:"center",gap:8,lineHeight:1.2}}>
                                <span style={{fontSize:18}}>{primary.icon}</span><span>{primary.label}</span>
                              </div>
                              {others.length>0 && <div style={{...B,fontSize:11,color:C.muted,marginTop:6,lineHeight:1.4}}>+ {others.length} outra{others.length>1?"s":""}: {others.map(o=>o.label).join(", ")}</div>}
                            </div>
                            <div style={{textAlign:"right",flexShrink:0}}>
                              {primary.tempo ? (<>
                                {tier && <span style={{...B,fontSize:11,fontWeight:700,color:tier.color,background:tier.bg,border:`1px solid ${tier.border}`,padding:"3px 10px",borderRadius:7,whiteSpace:"nowrap"}}>{tier.label}</span>}
                                <div style={{...B,fontSize:11.5,color:C.muted,marginTop:6}}>{primary.tempo}</div>
                              </>) : <span style={{...B,fontSize:11,color:C.muted,fontStyle:"italic"}}>Sem tempo informado</span>}
                            </div>
                          </div>
                        </div>

                        {/* Empresas */}
                        <div style={{padding:"16px 18px",border:`1px solid ${C.border}`,borderRadius:11,background:"#fff"}}>
                          <div style={{...B,fontSize:11,color:C.muted,marginBottom:8,fontWeight:600}}>Empresas onde já trabalhou</div>
                          {empresas.length>0 ? (<>
                            <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:8}}>
                              {empresas.map((e,i)=>(
                                <span key={i} style={{display:"inline-flex",alignItems:"center",gap:4,...B,fontSize:11.5,fontWeight:600,color:e.custom?C.green:C.navy,background:e.custom?C.greenBg:C.bg,border:`1px solid ${e.custom?C.greenBorder:C.border2}`,borderRadius:7,padding:"4px 11px"}}>
                                  {e.custom && <span style={{fontSize:9}}>⭐</span>}{e.label}
                                </span>
                              ))}
                            </div>
                            <div style={{...B,fontSize:11,color:C.muted,fontStyle:"italic"}}>Período não informado</div>
                          </>) : (
                            <div style={{...B,fontSize:12,color:C.muted,fontStyle:"italic"}}>Nenhuma empresa informada</div>
                          )}
                        </div>

                      </div>
                    );
                  })()}
                </div>

                {/* PERFIL DE TRABALHO — 5 traits interpretativos baseados nas respostas */}
                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                  <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,flexWrap:"wrap"}}>
                    <div style={{width:22,height:22,borderRadius:11,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                      <span style={{...H,fontSize:11,fontWeight:800,color:"#fff"}}>4</span>
                    </div>
                    <div style={{...B,fontSize:11,fontWeight:700,color:C.green,letterSpacing:.5,textTransform:"uppercase"}}>Perfil de trabalho</div>
                    <span style={{...B,fontSize:11,color:C.muted}}>(comportamental)</span>
                  </div>
                  {selWorker.perfil_trabalho && Object.keys(TRAIT_BY_ANSWER).some(k=>selWorker.perfil_trabalho?.[k]) ? (
                    <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:14}} className="vorker-traits-grid">
                      {Object.keys(TRAIT_BY_ANSWER).map(key=>{
                        const ans = selWorker.perfil_trabalho?.[key];
                        const trait = ans ? TRAIT_BY_ANSWER[key]?.[ans] : null;
                        if (!trait) return (
                          <div key={key} style={{padding:"14px 16px",background:C.bg,border:`1px dashed ${C.border}`,borderRadius:11,display:"flex",alignItems:"center",gap:10}}>
                            <span style={{...B,fontSize:12,color:C.muted,fontStyle:"italic"}}>Sem resposta</span>
                          </div>
                        );
                        return (
                          <div key={key} style={{padding:"14px 16px",background:C.bg,border:`1px solid ${C.border}`,borderRadius:11,display:"flex",alignItems:"flex-start",gap:12}}>
                            <div style={{width:32,height:32,borderRadius:8,background:C.greenBg,border:`1px solid ${C.greenBorder}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:15,flexShrink:0}}>{trait.icon}</div>
                            <div style={{flex:1,minWidth:0}}>
                              <div style={{...H,fontSize:13,fontWeight:800,color:C.navy,marginBottom:4,lineHeight:1.25}}>{trait.title}</div>
                              <div style={{...B,fontSize:11.5,color:C.sub,lineHeight:1.4}}>{trait.desc}</div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  ) : (
                    <div style={{...B,fontSize:13,color:C.muted,fontStyle:"italic"}}>Perfil ainda não preenchido pelo candidato.</div>
                  )}
                </div>

                {/* DOCUMENTAÇÃO — fotos reais com confirmação */}
                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                  <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}>
                    <div style={{width:22,height:22,borderRadius:11,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                      <span style={{...H,fontSize:11,fontWeight:800,color:"#fff"}}>5</span>
                    </div>
                    <div style={{...B,fontSize:11,fontWeight:700,color:C.green,letterSpacing:.5,textTransform:"uppercase"}}>Documentação</div>
                  </div>
                  <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:14}} className="vorker-docs-grid">
                    {[
                      {label:"Foto de perfil", src:selWorker.foto_rosto, fallback:"📷"},
                      {label:`Foto do ${selWorker.doc_tipo||"documento"}`, src:selWorker.selfie_doc, fallback:"🪪"},
                    ].map(({label,src,fallback})=>(
                      <div key={label} style={{display:"flex",alignItems:"center",gap:14}}>
                        <div style={{width:64,height:64,borderRadius:12,overflow:"hidden",background:"#0F172A",border:`1px solid ${C.border}`,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center"}}>
                          {src
                            ? <a href={src} target="_blank" rel="noopener noreferrer" style={{display:"block",width:"100%",height:"100%"}}>
                                <img src={src} alt={label} style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}} />
                              </a>
                            : <span style={{fontSize:24,color:"#64748B"}}>{fallback}</span>}
                        </div>
                        <div style={{flex:1,minWidth:0}}>
                          <div style={{...H,fontSize:13,fontWeight:700,color:C.navy,marginBottom:4}}>{label}</div>
                          <div style={{...B,fontSize:11.5,fontWeight:600,color:src?C.green:C.muted,display:"flex",alignItems:"center",gap:5}}>
                            <span>{src?"✓":"—"}</span>{src?"Validado visualmente":"Não enviado"}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                  {(selWorker.foto_rosto && selWorker.selfie_doc) && (
                    <div style={{padding:"10px 14px",background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:9,...B,fontSize:12.5,color:C.green,fontWeight:600,display:"flex",alignItems:"center",gap:7}}>
                      <span>✓</span> Documentos enviados e validados
                    </div>
                  )}
                </div>

                {/* DICA DO SISTEMA — sugestão automática para a curadoria */}
                {(()=>{
                  const primaryFunc = SPECS.find(s=>selWorker.specs?.includes(s.id));
                  const cells = Object.values(selWorker.disponibilidade||{}).reduce((a,b)=>a+(b?.length||0),0);
                  const dispAdj = cells>=14 ? "ampla" : cells>=6 ? "parcial" : "limitada";
                  const dica = primaryFunc
                    ? `Candidatos com disponibilidade ${dispAdj} e experiência em ${primaryFunc.label.toLowerCase()} têm 3x mais chances de serem chamados.`
                    : `Candidatos com perfil completo e disponibilidade ampla têm 3x mais chances de serem chamados.`;
                  return (
                    <div style={{background:"#F0F9FF",border:"1px solid #BAE6FD",borderRadius:11,padding:"14px 18px",display:"flex",alignItems:"flex-start",gap:12}}>
                      <span style={{fontSize:18,marginTop:1}}>📊</span>
                      <div style={{flex:1}}>
                        <div style={{...B,fontSize:11,fontWeight:700,color:"#0369A1",letterSpacing:.5,textTransform:"uppercase",marginBottom:4}}>Dica do sistema</div>
                        <div style={{...B,fontSize:12.5,color:"#075985",lineHeight:1.5}}>{dica}</div>
                      </div>
                    </div>
                  );
                })()}
              </div>

              {/* RIGHT RAIL: score + alertas + anotações + histórico + zona de perigo */}
              <div style={{display:"flex",flexDirection:"column",gap:14}} className="vorker-admin-rail">

                {/* Score (será redesenhado em parte futura) */}
                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:18}}>
                  <div style={{...B,fontSize:11,fontWeight:700,color:C.muted,letterSpacing:.5,textTransform:"uppercase",marginBottom:6}}>Recomendação do sistema</div>
                  <div style={{display:"flex",alignItems:"baseline",gap:6,marginBottom:6}}>
                    <span style={{...H,fontSize:36,fontWeight:900,color:scoreColor(score.total),letterSpacing:-1.2,lineHeight:1}}>{score.total}</span>
                    <span style={{...B,fontSize:12,color:C.muted,fontWeight:600}}>/100</span>
                  </div>
                  <div style={{height:5,borderRadius:3,background:"#E2E8F0",overflow:"hidden",marginBottom:12}}>
                    <div style={{height:"100%",borderRadius:3,background:scoreColor(score.total),width:`${score.total}%`,transition:"width .3s"}} />
                  </div>
                  <div style={{display:"flex",flexDirection:"column",gap:6}}>
                    {[["Comportamental",score.breakdown.comportamental],["Experiência",score.breakdown.experiencia],["Disponibilidade",score.breakdown.disponibilidade],["Flexibilidade",score.breakdown.flexibilidade],["Documentação",score.breakdown.documentacao],["Histórico",score.breakdown.historico]].map(([label,value])=>(
                      <div key={label}>
                        <div style={{display:"flex",justifyContent:"space-between",marginBottom:2}}>
                          <span style={{...B,fontSize:10.5,color:C.sub}}>{label}</span>
                          <span style={{...B,fontSize:10.5,fontWeight:700,color:scoreColor(value)}}>{value}</span>
                        </div>
                        <div style={{height:3,borderRadius:2,background:"#E2E8F0",overflow:"hidden"}}>
                          <div style={{height:"100%",borderRadius:2,background:scoreColor(value),width:`${value}%`}} />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:18}}>
                  <div style={{...B,fontSize:11,fontWeight:700,color:C.muted,letterSpacing:.5,textTransform:"uppercase",marginBottom:12}}>⚠ Alertas</div>
                  <div style={{display:"flex",flexDirection:"column",gap:7}}>
                    {alertas.map((a,i)=>{
                      const colorMap = { red:{c:C.red,bg:C.redBg,bd:C.redBorder}, amber:{c:"#92400E",bg:"#FEF3C7",bd:"#FDE68A"}, green:{c:C.green,bg:C.greenBg,bd:C.greenBorder} };
                      const cm = colorMap[a.lv]||colorMap.amber;
                      return (
                        <div key={i} style={{padding:"8px 10px",background:cm.bg,border:`1px solid ${cm.bd}`,borderRadius:7,...B,fontSize:11.5,color:cm.c,lineHeight:1.45}}>{a.txt}</div>
                      );
                    })}
                  </div>
                </div>

                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:18}}>
                  <div style={{...B,fontSize:11,fontWeight:700,color:C.muted,letterSpacing:.5,textTransform:"uppercase",marginBottom:8}}>📝 Anotações da curadoria</div>
                  <textarea value={adminNotes} onChange={e=>saveAdminNotes(e.target.value)} placeholder="Adicione observações que ajudem na decisão (privadas)…"
                    style={{width:"100%",minHeight:120,padding:"10px 12px",borderRadius:8,border:`1.5px solid ${C.border2}`,...B,fontSize:12.5,color:C.text,outline:"none",resize:"vertical",lineHeight:1.5,fontFamily:"inherit"}} />
                  <div style={{...B,fontSize:10,color:C.muted,marginTop:6,fontStyle:"italic"}}>Salvo automaticamente neste navegador.</div>
                </div>

                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:18}}>
                  <div style={{...B,fontSize:11,fontWeight:700,color:C.muted,letterSpacing:.5,textTransform:"uppercase",marginBottom:8}}>🕒 Histórico de ações</div>
                  <div style={{...B,fontSize:11.5,color:C.muted,lineHeight:1.55}}>Cadastrado em <strong style={{color:C.navy}}>{selWorker.created_at?new Date(selWorker.created_at).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric"}):"—"}</strong></div>
                  <div style={{...B,fontSize:10,color:C.muted,marginTop:8,fontStyle:"italic"}}>Em breve: log automático de aprovações, reprovações e edições.</div>
                </div>

                <div style={{background:C.white,border:`1px solid ${C.redBorder}`,borderRadius:12,padding:18}}>
                  <div style={{...H,fontSize:11,fontWeight:700,color:C.red,marginBottom:10,letterSpacing:.3,textTransform:"uppercase"}}>Zona de perigo</div>
                  <Btn label="🗑 Excluir colaborador" variant="danger" size="sm" full onClick={()=>setDeleteModal({id:selWorker.id,name:selWorker.nome,type:"worker"})} />
                  <div style={{...B,fontSize:10.5,color:C.muted,marginTop:8,lineHeight:1.5}}>Remove permanentemente todos os dados.</div>
                </div>
              </div>
            </div>
          </div>
          );
        })()}

        {tab==="billing"&&(
          <div>
            <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginBottom:6}}>Cobranças</h2>
            <p style={{...B,fontSize:14,color:C.muted,marginBottom:22}}>Gestão de planos e pagamentos.</p>
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:14,marginBottom:28}}>
              {[{v:companies.filter(c=>c.pay_status==="paid").length,l:"Pagamentos confirmados",c:C.green,icon:"💰"},{v:companies.filter(c=>c.pay_status==="trial").length,l:"Em trial",c:C.blue,icon:"⏱"},{v:overdue,l:"Em atraso",c:C.red,icon:"⚠"}].map(({v,l,c,icon})=>(
                <div key={l} style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:"20px 18px"}}>
                  <div style={{fontSize:24,marginBottom:8}}>{icon}</div>
                  <div style={{...H,fontSize:30,fontWeight:900,color:c}}>{v}</div>
                  <div style={{...B,fontSize:13,color:C.sub,marginTop:3}}>{l}</div>
                </div>
              ))}
            </div>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,overflow:"hidden"}}>
              <div style={{display:"grid",gridTemplateColumns:"2fr 2fr 1fr 1fr",padding:"12px 20px",borderBottom:`1px solid ${C.border}`,background:C.bg}}>
                {["Empresa","Plano","Pagamento","Ações"].map(h=><div key={h} style={{...B,fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:.5}}>{h}</div>)}
              </div>
              {companies.filter(c=>c.status==="approved").length===0?<div style={{padding:48,textAlign:"center",...B,fontSize:14,color:C.muted}}>Nenhuma empresa aprovada ainda.</div>:companies.filter(c=>c.status==="approved").map(co=>(
                <div key={co.id} style={{display:"grid",gridTemplateColumns:"2fr 2fr 1fr 1fr",padding:"14px 20px",borderBottom:`1px solid ${C.border}`,alignItems:"center"}}>
                  <div><div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>{co.nome_fant||co.razao}</div><div style={{...B,fontSize:12,color:C.muted}}>{co.seg}</div></div>
                  <div style={{...B,fontSize:13,color:C.sub}}>{co.plan}</div>
                  <Badge status={co.pay_status} />
                  <div style={{display:"flex",gap:6}}>
                    <button onClick={()=>updateCo(co.id,{pay_status:"paid"})} style={{background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:6,padding:"5px 9px",cursor:"pointer",...B,fontSize:11,color:C.green,fontWeight:600}}>✓</button>
                    <button onClick={()=>updateCo(co.id,{pay_status:"overdue"})} style={{background:C.redBg,border:`1px solid ${C.redBorder}`,borderRadius:6,padding:"5px 9px",cursor:"pointer",...B,fontSize:11,color:C.red,fontWeight:600}}>!</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>
    </div>
    </>
  );
}

// ─── AUTH ──────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════
// CEP → LAT/LNG + HAVERSINE DISTANCE
// ═══════════════════════════════════════════════════════════════
const cepToCoords = async (cep) => {
  const d = cep.replace(/\D/g,"");
  try {
    const r = await fetch(`https://viacep.com.br/ws/${d}/json/`);
    const j = await r.json();
    if(j.erro) return null;
    const geo = await fetch(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(j.logradouro+", "+j.localidade+", "+j.uf+", Brasil")}&format=json&limit=1`);
    const gj = await geo.json();
    if(gj.length===0) return null;
    return { lat: parseFloat(gj[0].lat), lng: parseFloat(gj[0].lon) };
  } catch { return null; }
};

const haversine = (lat1, lng1, lat2, lng2) => {
  const R=6371, dLat=(lat2-lat1)*Math.PI/180, dLng=(lng2-lng1)*Math.PI/180;
  const a=Math.sin(dLat/2)**2+Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLng/2)**2;
  return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
};

// ═══════════════════════════════════════════════════════════════
// COMPANY LOGIN (real — loads from Supabase)
// ═══════════════════════════════════════════════════════════════
function CompanyLogin({ onLogin, onRegister, onBack }) {
  const [email, setEmail] = useState("");
  const [pass,  setPass]  = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleLogin = async () => {
    if(!email||!pass){ setError("Preencha e-mail e senha."); return; }
    setLoading(true); setError("");
    try {
      const { data: company, error: err } = await supabase
        .from("companies")
        .select("*, company_units(*)")
        .eq("email", email)
        .maybeSingle();

      if(err||!company) { setError("E-mail não encontrado."); setLoading(false); return; }
      if(company.status==="pending") { setError("Seu cadastro ainda está em análise. Aguarde a aprovação da equipe VORKER."); setLoading(false); return; }
      if(company.status==="rejected") { setError("Seu cadastro foi reprovado. Entre em contato com a equipe VORKER."); setLoading(false); return; }
      onLogin(company);
    } catch(e) {
      setError("Erro ao conectar. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{minHeight:"75vh",display:"flex",alignItems:"center",justifyContent:"center",padding:"60px 20px",background:C.bg}}>
      <div style={{maxWidth:420,width:"100%"}}>
        <button onClick={onBack} style={{...B,fontSize:13,color:C.sub,background:"none",border:"none",cursor:"pointer",marginBottom:24}}>← Voltar</button>
        <SL>Área da Empresa</SL>
        <h2 style={{...H,fontSize:32,fontWeight:900,color:C.navy,letterSpacing:-1.2,marginBottom:28}}>Bem-vindo de volta.</h2>
        <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:28,boxShadow:"0 4px 20px rgba(0,0,0,.06)"}}>
          <Field label="E-mail de acesso" placeholder="acesso@empresa.com.br" value={email} onChange={setEmail} type="email" />
          <Field label="Senha" placeholder="••••••••" value={pass} onChange={setPass} type="password" />
          {error&&<Alert type="error">{error}</Alert>}
          <Btn label="Entrar →" variant="primary" size="lg" full onClick={handleLogin} loading={loading} />
          <div style={{display:"flex",alignItems:"center",gap:12,margin:"16px 0"}}>
            <div style={{flex:1,height:1,background:C.border}} /><span style={{...B,fontSize:12,color:C.muted}}>ou</span><div style={{flex:1,height:1,background:C.border}} />
          </div>
          <Btn label="Cadastrar minha empresa →" variant="ghost" size="lg" full onClick={onRegister} />
        </div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// TALENT BROWSER
// ═══════════════════════════════════════════════════════════════
function TalentBrowser({ company, onLogout, onUpdateCompany }) {
  const [tab,       setTab]       = useState("profile");
  const [subTab,    setSubTab]    = useState("visao-geral");
  const [editingCompany, setEditingCompany] = useState(false);
  const [editData,  setEditData]  = useState(null);
  const [savingCompany, setSavingCompany] = useState(false);
  const [editCepLoad, setEditCepLoad] = useState(false);
  const [companyToast, setCompanyToast] = useState(null);
  const [selUnit,   setSelUnit]   = useState(null);
  const [workers,   setWorkers]   = useState([]);
  const [filtered,  setFiltered]  = useState([]);
  const [loading,   setLoading]   = useState(false);
  const [calcMsg,   setCalcMsg]   = useState("");
  const [selWorker, setSelWorker] = useState(null);
  const [units,     setUnits]     = useState(company.company_units||[]);
  const [savingUnit,setSavingUnit]= useState(false);
  const [uCepLoad,  setUCepLoad]  = useState(false);
  const [newUnit,   setNewUnit]   = useState({nome:"",cep:"",rua:"",numero:"",complemento:"",bairro:"",cidade:"",estado:""});
  const [deleteModal, setDeleteModal] = useState(null); // {type, id, name}
  const [invites,   setInvites]   = useState([]);
  const [invModal,  setInvModal]  = useState(null); // {worker, unitId, message}
  const [invSaving, setInvSaving] = useState(false);
  const [invError,  setInvError]  = useState("");
  const [invToast,  setInvToast]  = useState(null);

  const fSpec  = useState("all");   const [fSpecV,  setFSpec]  = [fSpec[0],  fSpec[1]];
  const fLevel = useState(0);       const [fLevelV, setFLevel] = [fLevel[0], fLevel[1]];
  const fDia   = useState("all");   const [fDiaV,   setFDia]   = [fDia[0],   fDia[1]];
  const fTurno = useState("all");   const [fTurnoV, setFTurno] = [fTurno[0], fTurno[1]];

  const levelColors = ["#9CA3AF","#60A5FA","#FBBF24","#F97316","#16A34A"];
  const levelWidth  = [0,25,50,75,100];

  useEffect(()=>{ if(selUnit) loadWorkers(); },[selUnit]);

  useEffect(()=>{ if(company?.id) fetchInvitesByCompany(company.id).then(setInvites).catch(()=>{}); }, [company?.id]);

  const refreshInvites = async () => { if(company?.id) try { setInvites(await fetchInvitesByCompany(company.id)); } catch {} };

  const openInviteModal = (worker) => { setInvModal({worker, unitId: selUnit?.id || units[0]?.id || "", message: ""}); setInvError(""); };
  const sendInvite = async () => {
    if(!invModal) return;
    setInvSaving(true); setInvError("");
    try {
      await createInvite({company_id: company.id, worker_id: invModal.worker.id, unit_id: invModal.unitId, message: invModal.message});
      await refreshInvites();
      setInvModal(null);
      setInvToast({type:"success", msg:`Convite enviado a ${invModal.worker.nome.split(" ")[0]}. Você verá o WhatsApp quando ${(/a$/i.test(invModal.worker.nome.split(" ")[0]))?"ela aceitar":"ele aceitar"}.`});
      setTimeout(()=>setInvToast(null), 6000);
    } catch(e) { setInvError(e.message || "Erro ao enviar convite."); }
    finally { setInvSaving(false); }
  };
  const inviteFor = (workerId) => invites.find(i => i.worker_id === workerId);

  useEffect(()=>{
    let list=workers;
    if(fSpecV!=="all"){
      list=list.filter(w=>{
        if(!w.specs?.includes(fSpecV)) return false;
        if(fLevelV<=0) return true;
        const t = w.func_exp?.[fSpecV]?.tempo;
        return (TEMPO_PTS[t]||0) >= fLevelV;
      });
    }
    if(fDiaV!=="all")  list=list.filter(w=>(w.disponibilidade?.[fDiaV]||[]).length>0);
    if(fTurnoV!=="all") list=list.filter(w=>Object.values(w.disponibilidade||{}).some(t=>t.includes(fTurnoV)));
    setFiltered(list);
  },[workers,fSpecV,fLevelV,fDiaV,fTurnoV]);

  const loadWorkers = async () => {
    setLoading(true); setCalcMsg("Buscando colaboradores aprovados..."); setWorkers([]); setFiltered([]);
    try {
      const { data: wList } = await supabase.from("workers").select("*").eq("status","approved");
      if(!wList||wList.length===0){ setLoading(false); setCalcMsg("Nenhum colaborador aprovado ainda."); return; }
      setCalcMsg(`Calculando distâncias para ${wList.length} colaboradores...`);
      const unitCoords = await cepToCoords(selUnit.cep);
      const withDist = await Promise.all(wList.map(async w=>{
        try {
          const wCoords = await cepToCoords(w.cep);
          if(!unitCoords||!wCoords) return {...w,distKm:999,distLabel:"—",withinRadius:false};
          const dist = haversine(unitCoords.lat,unitCoords.lng,wCoords.lat,wCoords.lng);
          return {...w,distKm:dist,distLabel:`${dist.toFixed(1)}km`,withinRadius:dist<=(w.raio_km||10)};
        } catch { return {...w,distKm:999,distLabel:"—",withinRadius:false}; }
      }));
      const available = withDist.filter(w=>w.withinRadius).sort((a,b)=>a.distKm-b.distKm);
      setWorkers(available); setFiltered(available);
      setCalcMsg(`${available.length} colaboradores disponíveis na região`);
    } catch(e) { setCalcMsg("Erro ao buscar colaboradores."); }
    finally { setLoading(false); }
  };

  const startEditCompany = () => {
    setEditData({
      razao:company.razao||"", nome_fant:company.nome_fant||"", seg:company.seg||"", site:company.site||"",
      cep:company.cep||"", rua:company.rua||"", numero:company.numero||"", complemento:company.complemento||"",
      bairro:company.bairro||"", cidade:company.cidade||"", estado:company.estado||"",
      resp_nome:company.resp_nome||"", resp_cargo:company.resp_cargo||"", resp_tel:company.resp_tel||"", resp_email:company.resp_email||"",
    });
    setEditingCompany(true);
  };

  const saveCompanyEdit = async () => {
    setSavingCompany(true);
    try {
      const changes = {...editData, status:"pending", reject_note:""};
      await updateCompanyDB(company.id, changes);
      onUpdateCompany({...company, ...changes});
      setEditingCompany(false);
      setCompanyToast({type:"warning", msg:"Dados atualizados. Seu cadastro voltou para análise da equipe Vorker."});
      setTimeout(()=>setCompanyToast(null), 6000);
    } catch(e){ setCompanyToast({type:"error", msg:"Erro ao salvar. Tente novamente."}); setTimeout(()=>setCompanyToast(null), 4000); }
    finally { setSavingCompany(false); }
  };

  const addUnit = async () => {
    if(!newUnit.nome||!newUnit.cep||!newUnit.rua||!newUnit.numero) return;
    setSavingUnit(true);
    try {
      const saved = await addUnitToDB(company.id, newUnit);
      const updated = [...units, saved];
      setUnits(updated);
      onUpdateCompany({...company, company_units: updated});
      setNewUnit({nome:"",cep:"",rua:"",numero:"",complemento:"",bairro:"",cidade:"",estado:""});
    } catch(e){ alert("Erro ao salvar unidade."); }
    finally { setSavingUnit(false); }
  };

  const removeUnit = async (unitId) => {
    try {
      await deleteUnitFromDB(unitId);
      const updated = units.filter(u=>u.id!==unitId);
      setUnits(updated);
      if(selUnit?.id===unitId){ setSelUnit(null); setWorkers([]); setFiltered([]); }
    } catch(e){ alert("Erro ao remover unidade."); }
    finally { setDeleteModal(null); }
  };

  const whatsappMsg = (w) => {
    const msg = `Olá ${w.nome.split(" ")[0]}! Sou da empresa *${company.nome_fant||company.razao}* e encontrei seu perfil no VORKER. Temos uma oportunidade de trabalho na nossa unidade *${selUnit?.nome}*. Podemos conversar?`;
    return `https://wa.me/55${w.telefone?.replace(/\D/g,"")}?text=${encodeURIComponent(msg)}`;
  };

  // Delete confirmation modal
  const DeleteModal = () => (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <div style={{background:"#fff",borderRadius:16,padding:28,maxWidth:400,width:"100%",boxShadow:"0 20px 60px rgba(0,0,0,.15)"}}>
        <h3 style={{...H,fontSize:20,fontWeight:800,color:C.navy,marginBottom:8}}>Remover unidade</h3>
        <p style={{...B,fontSize:14,color:C.sub,marginBottom:20,lineHeight:1.65}}>Tem certeza que deseja remover a unidade <strong>{deleteModal?.name}</strong>? Esta ação não pode ser desfeita.</p>
        <div style={{display:"flex",gap:10}}>
          <Btn label="Cancelar" variant="ghost" size="md" full onClick={()=>setDeleteModal(null)} />
          <Btn label="Remover" variant="danger" size="md" full onClick={()=>removeUnit(deleteModal.id)} />
        </div>
      </div>
    </div>
  );

  const TABS = [{id:"talent",icon:"🔍",label:"Talent Browser"},{id:"profile",icon:"🏢",label:"Meu Perfil"}];

  // Worker detail page (visão da empresa)
  if(selWorker) return (()=>{
    const score = computeWorkerScore(selWorker);
    const idade = calcIdade(selWorker.nascimento);
    const TRAIT_BY_ANSWER = {
      corrido: {
        manter:     {title:"Bem sob pressão",    desc:"Mantém velocidade fazendo o melhor possível", icon:"⚡"},
        equilibrar: {title:"Equilibra ritmo",    desc:"Equilibra velocidade e atenção",              icon:"⚖️"},
        diminuir:   {title:"Caprichoso",         desc:"Diminui o ritmo para garantir qualidade",     icon:"🎯"},
      },
      diaADia: {
        praticas:   {title:"Foco operacional",   desc:"Tarefas práticas e operacionais",             icon:"🔧"},
        equilibrio: {title:"Organização",        desc:"Equilibra rapidez e organização",             icon:"⚖️"},
        cuidado:    {title:"Pensa com cuidado",  desc:"Pensa com cuidado em cada etapa",             icon:"🧠"},
      },
      tarefa: {
        iniciativa: {title:"Autonomia",          desc:"Tenta resolver sozinho primeiro",             icon:"👤"},
        perguntar:  {title:"Colaborativa",       desc:"Pergunta se necessário",                       icon:"💬"},
        orientacao: {title:"Pede orientação",    desc:"Pede orientação antes de começar",             icon:"📋"},
      },
      diferente: {
        ajusta:     {title:"Adaptação rápida",   desc:"Se ajusta rápido quando algo muda",           icon:"🔄"},
        entender:   {title:"Analítica",          desc:"Tenta entender o que aconteceu",               icon:"🔍"},
        avisar:     {title:"Comunicativa",       desc:"Prefere avisar alguém antes",                  icon:"📣"},
      },
      imprevisto: {
        resolver:   {title:"Comprometida",       desc:"Tenta resolver e cumprir o que assumiu",      icon:"🛡"},
        aviso:      {title:"Avisa antes",        desc:"Avisa o quanto antes",                          icon:"⏰"},
        cancelar:   {title:"Conservadora",       desc:"Prefere cancelar quando há imprevisto",        icon:"⏸"},
      },
    };
    const TIER = (tempo) => {
      if(!tempo) return null;
      if(tempo==="Menos de 6 meses" || tempo==="6 meses a 1 ano") return {label:"Baixa experiência", bg:"#FEE2E2", color:"#DC2626", border:"#FECACA"};
      if(tempo==="1 a 3 anos") return {label:"Experiência média", bg:"#FEF3C7", color:"#92400E", border:"#FDE68A"};
      return {label:"Alta experiência", bg:"#DCFCE7", color:"#16A34A", border:"#BBF7D0"};
    };
    const primaryFunc = SPECS.find(s=>selWorker.specs?.includes(s.id));
    const primaryTempo = primaryFunc ? selWorker.func_exp?.[primaryFunc.id]?.tempo : null;
    const tier = TIER(primaryTempo);
    const cellsFilled = Object.values(selWorker.disponibilidade||{}).reduce((a,b)=>a+(b?.length||0),0);
    const dispTag = cellsFilled>=14 ? {l:"Disponibilidade ampla",c:C.green,bg:C.greenBg,bd:C.greenBorder}
                    : cellsFilled>=6 ? {l:"Disponibilidade parcial",c:"#CA8A04",bg:"#FEFCE8",bd:"#FDE68A"}
                    : {l:"Disponibilidade limitada",c:C.red,bg:C.redBg,bd:C.redBorder};
    const flex = selWorker.flexibilidade && FLEX_LABEL[selWorker.flexibilidade];
    const empresas = [
      ...(selWorker.empresas_selected||[]).map(id=>{ const e=EMPRESAS_PRESET.find(x=>x.id===id); return e?{label:e.label,custom:false}:null; }).filter(Boolean),
      ...(selWorker.empresas_custom||[]).map(nome=>({label:nome,custom:true})),
    ];
    const scoreLabel = score.total>=80?"Excelente":score.total>=60?"Bom":score.total>=40?"Regular":"Baixo";
    const firstName = (selWorker.nome||"").split(" ")[0];
    const isFem = firstName && /a$/i.test(firstName);
    const pron = isFem?"ela":"ele";
    const atencoes = [];
    if(cellsFilled<6) atencoes.push("Disponibilidade limitada na semana");
    if(score.breakdown.experiencia<30) atencoes.push("Pouca experiência declarada");
    if(empresas.length===0) atencoes.push("Sem histórico de empresas");

    return (
    <div style={{minHeight:"90vh",background:C.bg}}>
      <div style={{maxWidth:1200,margin:"0 auto",padding:"24px 32px 60px"}}>

        {/* Top nav */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,gap:12,flexWrap:"wrap"}}>
          <button onClick={()=>setSelWorker(null)} style={{...B,fontSize:13,color:C.sub,background:"none",border:"none",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:5}}>← Voltar ao Talent Browser</button>
          <button style={{...B,fontSize:12.5,color:C.red,background:"none",border:"none",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:5,opacity:.85}}><span>⚠</span> Denunciar perfil</button>
        </div>

        {/* 2-column layout */}
        <div className="vorker-worker-detail" style={{display:"grid",gridTemplateColumns:"1fr 320px",gap:18,alignItems:"flex-start"}}>

          {/* MAIN COLUMN */}
          <div style={{display:"flex",flexDirection:"column",gap:14}}>

            {/* Header card: identity + score */}
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:24}}>
              <div className="vorker-worker-head" style={{display:"grid",gridTemplateColumns:"1.4fr 1fr",gap:24,alignItems:"flex-start"}}>

                <div>
                  <div style={{display:"flex",gap:14,alignItems:"center",marginBottom:14}}>
                    {selWorker.foto_rosto ? (
                      <img src={selWorker.foto_rosto} alt={selWorker.nome} style={{width:72,height:72,borderRadius:36,objectFit:"cover",border:`2px solid ${C.greenBorder}`,flexShrink:0}} />
                    ) : (
                      <div style={{width:72,height:72,borderRadius:36,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                        <span style={{...H,fontSize:28,fontWeight:900,color:"#fff"}}>{selWorker.nome?.[0]}</span>
                      </div>
                    )}
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{display:"inline-flex",alignItems:"center",gap:5,background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:6,padding:"3px 9px",marginBottom:6,...B,fontSize:11,fontWeight:700,color:C.green}}>✓ {isFem?"Pronta":"Pronto"} para trabalhar</div>
                      <h2 style={{...H,fontSize:22,fontWeight:900,color:C.navy,letterSpacing:-.4,lineHeight:1.15}}>{selWorker.nome}</h2>
                    </div>
                  </div>
                  <div className="vorker-worker-facts" style={{display:"flex",gap:16,paddingTop:14,borderTop:`1px solid ${C.border}`,flexWrap:"wrap"}}>
                    {[
                      {icon:"🎂", value:idade!=null?`${idade} anos`:"—"},
                      {icon:"📍", value:`${selWorker.cidade||"—"}/${selWorker.estado||""}`},
                      {icon:"🚗", value:selWorker.deslocamento||"—"},
                      flex && {icon:flex.icon, value:flex.label},
                      primaryTempo && {icon:"⏱", value:primaryTempo},
                    ].filter(Boolean).map((f,i)=>(
                      <div key={i} style={{display:"inline-flex",alignItems:"center",gap:6,...B,fontSize:12.5,color:C.navy,fontWeight:600}}>
                        <span style={{fontSize:14}}>{f.icon}</span><span>{f.value}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div style={{textAlign:"center",paddingLeft:20,borderLeft:`1px solid ${C.border}`}}>
                  <div style={{...B,fontSize:11,fontWeight:700,color:C.muted,letterSpacing:.4,textTransform:"uppercase",marginBottom:8}}>Recomendação do Vorker</div>
                  <div style={{display:"flex",alignItems:"baseline",justifyContent:"center",gap:5,marginBottom:8}}>
                    <span style={{...H,fontSize:46,fontWeight:900,color:scoreColor(score.total),letterSpacing:-1.5,lineHeight:1}}>{score.total}</span>
                    <span style={{...B,fontSize:14,color:C.muted,fontWeight:600}}>/100</span>
                  </div>
                  <div style={{height:6,borderRadius:3,background:"#E2E8F0",overflow:"hidden",marginBottom:8,maxWidth:200,marginLeft:"auto",marginRight:"auto"}}>
                    <div style={{height:"100%",borderRadius:3,background:scoreColor(score.total),width:`${score.total}%`,transition:"width .3s"}} />
                  </div>
                  <div style={{...B,fontSize:12,fontWeight:700,color:scoreColor(score.total)}}>{scoreLabel}</div>
                </div>
              </div>
            </div>

            {/* Como ela trabalha no dia a dia */}
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
              <div style={{...H,fontSize:14,fontWeight:800,color:C.navy,marginBottom:14}}>Como {pron} trabalha no dia a dia</div>
              {selWorker.perfil_trabalho && Object.keys(TRAIT_BY_ANSWER).some(k=>selWorker.perfil_trabalho?.[k]) ? (
                <div className="vorker-traits-grid" style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:10}}>
                  {Object.keys(TRAIT_BY_ANSWER).map(key=>{
                    const ans = selWorker.perfil_trabalho?.[key];
                    const trait = ans ? TRAIT_BY_ANSWER[key]?.[ans] : null;
                    if(!trait) return (
                      <div key={key} style={{padding:"12px 10px",textAlign:"center",background:C.bg,border:`1px dashed ${C.border}`,borderRadius:10}}>
                        <div style={{...B,fontSize:11,color:C.muted,fontStyle:"italic"}}>—</div>
                      </div>
                    );
                    return (
                      <div key={key} style={{padding:"14px 12px",textAlign:"center",background:C.bg,border:`1px solid ${C.border}`,borderRadius:10}}>
                        <div style={{width:34,height:34,margin:"0 auto 8px",borderRadius:9,background:C.greenBg,border:`1px solid ${C.greenBorder}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16}}>{trait.icon}</div>
                        <div style={{...H,fontSize:12,fontWeight:800,color:C.navy,marginBottom:3,lineHeight:1.25}}>{trait.title}</div>
                        <div style={{...B,fontSize:10.5,color:C.sub,lineHeight:1.4}}>{trait.desc}</div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div style={{...B,fontSize:13,color:C.muted,fontStyle:"italic"}}>Perfil de trabalho ainda não preenchido.</div>
              )}
            </div>

            {/* Experiência + Disponibilidade */}
            <div className="vorker-exp-disp" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}>

              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                <div style={{...H,fontSize:14,fontWeight:800,color:C.navy,marginBottom:12}}>Experiência profissional</div>
                {primaryFunc ? (
                  <>
                    <div style={{padding:"12px 14px",border:`1px solid ${C.border}`,borderRadius:10,background:C.bg,marginBottom:10}}>
                      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10,flexWrap:"wrap"}}>
                        <div style={{flex:1,minWidth:0}}>
                          <div style={{...B,fontSize:10.5,color:C.muted,marginBottom:3,fontWeight:600,textTransform:"uppercase",letterSpacing:.3}}>Função principal</div>
                          <div style={{...H,fontSize:15,fontWeight:800,color:C.navy,display:"flex",alignItems:"center",gap:6}}><span style={{fontSize:16}}>{primaryFunc.icon}</span>{primaryFunc.label}</div>
                        </div>
                        {tier && <span style={{...B,fontSize:10.5,fontWeight:700,color:tier.color,background:tier.bg,border:`1px solid ${tier.border}`,padding:"3px 9px",borderRadius:7,whiteSpace:"nowrap"}}>{tier.label}</span>}
                      </div>
                      {primaryTempo && <div style={{...B,fontSize:11.5,color:C.sub,marginTop:6}}>{primaryTempo}</div>}
                    </div>
                    {selWorker.specs?.length>1 && (
                      <div style={{...B,fontSize:11,color:C.muted}}>+ {selWorker.specs.length-1} outra{selWorker.specs.length>2?"s":""} função: {SPECS.filter(s=>selWorker.specs?.includes(s.id)).slice(1).map(s=>s.label).join(", ")}</div>
                    )}
                  </>
                ) : (
                  <div style={{...B,fontSize:13,color:C.muted,fontStyle:"italic"}}>Nenhuma função informada.</div>
                )}
              </div>

              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12,flexWrap:"wrap",gap:6}}>
                  <div style={{...H,fontSize:14,fontWeight:800,color:C.navy}}>Disponibilidade semanal</div>
                  <span style={{...B,fontSize:10.5,fontWeight:700,color:dispTag.c,background:dispTag.bg,border:`1px solid ${dispTag.bd}`,padding:"2px 8px",borderRadius:12}}>{dispTag.l}</span>
                </div>
                <div className="vorker-day-row" style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:5}}>
                  {DAYS.map(day=>{
                    const shifts=selWorker.disponibilidade?.[day]||[];
                    const primary = SHIFTS.find(s=>shifts.includes(s.id));
                    const hasAny = shifts.length>0;
                    return (
                      <div key={day} style={{textAlign:"center",padding:"8px 3px",borderRadius:7,background:hasAny?"#fff":C.bg,border:`1.5px solid ${C.border}`}}>
                        <div style={{...H,fontSize:10.5,fontWeight:800,color:hasAny?C.green:C.muted}}>{day}</div>
                        <div style={{fontSize:14,lineHeight:1,marginTop:3}}>{primary?primary.icon:"·"}</div>
                        <div style={{...B,fontSize:9.5,fontWeight:600,color:primary?primary.color:C.muted,marginTop:3}}>{primary?primary.label:"—"}</div>
                      </div>
                    );
                  })}
                </div>
                {flex && <div style={{marginTop:10,...B,fontSize:11.5,color:C.sub,display:"flex",alignItems:"center",gap:5}}><span>{flex.icon}</span><span><strong style={{color:C.navy,fontWeight:700}}>{flex.desc}</strong></span></div>}
              </div>
            </div>

            {/* Verificação + Empresas */}
            <div className="vorker-verif-emp" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}>

              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                <div style={{...H,fontSize:14,fontWeight:800,color:C.navy,marginBottom:12}}>Verificação e segurança</div>
                <div style={{display:"flex",flexDirection:"column",gap:8}}>
                  {[
                    {ok:!!selWorker.foto_rosto,        label:"Foto de perfil verificada"},
                    {ok:!!selWorker.selfie_doc,        label:`Documento (${selWorker.doc_tipo||"RG/CNH"}) verificado`},
                    {ok:!!selWorker.cpf,               label:"CPF validado"},
                    {ok:selWorker.status==="approved", label:"Aprovado pela curadoria Vorker"},
                  ].map(({ok,label})=>(
                    <div key={label} style={{display:"flex",alignItems:"center",gap:8,padding:"7px 10px",background:ok?C.greenBg+"60":C.bg,border:`1px solid ${ok?C.greenBorder:C.border}`,borderRadius:7}}>
                      <span style={{fontSize:13,color:ok?C.green:C.muted,fontWeight:900}}>{ok?"✓":"·"}</span>
                      <span style={{...B,fontSize:12,fontWeight:600,color:ok?C.green:C.muted}}>{label}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22}}>
                <div style={{...H,fontSize:14,fontWeight:800,color:C.navy,marginBottom:12}}>Empresas onde já trabalhou</div>
                {empresas.length>0 ? (
                  <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                    {empresas.map((e,i)=>(
                      <span key={i} style={{display:"inline-flex",alignItems:"center",gap:4,...B,fontSize:11.5,fontWeight:600,color:e.custom?C.green:C.navy,background:e.custom?C.greenBg:C.bg,border:`1px solid ${e.custom?C.greenBorder:C.border2}`,borderRadius:7,padding:"4px 10px"}}>
                        {e.custom && <span style={{fontSize:9}}>⭐</span>}{e.label}
                      </span>
                    ))}
                  </div>
                ) : (
                  <div style={{...B,fontSize:12,color:C.muted,fontStyle:"italic"}}>Sem histórico declarado.</div>
                )}
              </div>
            </div>

            <div style={{...B,fontSize:11.5,color:C.muted,textAlign:"center",fontStyle:"italic",padding:"8px 16px"}}>💡 Dica Vorker: ao convidar pelo WhatsApp, seja {isFem?"clara":"claro"} sobre datas, horários e remuneração para aumentar a chance de aceite.</div>
          </div>

          {/* RIGHT RAIL */}
          <div className="vorker-worker-rail" style={{display:"flex",flexDirection:"column",gap:14,position:"sticky",top:20}}>

            {(() => {
              const inv = inviteFor(selWorker.id);
              if(inv?.status === "accepted") {
                return (
                  <div style={{background:C.white,border:`2px solid ${C.greenBorder}`,borderRadius:14,padding:20,boxShadow:"0 4px 20px rgba(22,163,74,.08)"}}>
                    <div style={{display:"inline-flex",alignItems:"center",gap:6,background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:6,padding:"3px 9px",marginBottom:10,...B,fontSize:11,fontWeight:700,color:C.green}}>✓ Convite aceito</div>
                    <div style={{...H,fontSize:15,fontWeight:800,color:C.navy,marginBottom:10}}>Fale agora com {firstName}</div>
                    <a href={whatsappMsg(selWorker)} target="_blank" rel="noopener noreferrer" style={{textDecoration:"none",display:"block"}}>
                      <div style={{background:"#25D366",borderRadius:10,padding:"14px 16px",textAlign:"center",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:8,boxShadow:"0 4px 12px rgba(37,211,102,.3)"}}>
                        <span style={{fontSize:18}}>💬</span>
                        <span style={{...H,fontSize:14,fontWeight:800,color:"#fff"}}>Conversar pelo WhatsApp</span>
                      </div>
                    </a>
                    <div style={{marginTop:10,padding:"8px 12px",background:C.bg,borderRadius:8,...B,fontSize:11.5,color:C.sub,lineHeight:1.5}}>
                      📱 {selWorker.telefone}<br/>
                      ✉️ {selWorker.email}
                    </div>
                    <div style={{marginTop:10,padding:"8px 12px",background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:8,display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
                      <span style={{...B,fontSize:11,color:C.sub,fontWeight:600}}>📍 Distância</span>
                      <span style={{...H,fontSize:14,fontWeight:900,color:C.green}}>{selWorker.distLabel}</span>
                    </div>
                  </div>
                );
              }
              if(inv?.status === "pending") {
                return (
                  <div style={{background:C.white,border:`2px solid ${C.amberBorder}`,borderRadius:14,padding:20,boxShadow:"0 4px 20px rgba(217,119,6,.08)"}}>
                    <div style={{display:"inline-flex",alignItems:"center",gap:6,background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:6,padding:"3px 9px",marginBottom:10,...B,fontSize:11,fontWeight:700,color:C.amber}}>⏳ Convite enviado</div>
                    <div style={{...H,fontSize:15,fontWeight:800,color:C.navy,marginBottom:6}}>Aguardando resposta de {firstName}</div>
                    <p style={{...B,fontSize:12,color:C.sub,marginBottom:10,lineHeight:1.5}}>Enviado em {new Date(inv.created_at).toLocaleDateString("pt-BR")}. Quando {firstName} aceitar, o WhatsApp será revelado aqui.</p>
                    <div style={{marginTop:10,padding:"8px 12px",background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:8,display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
                      <span style={{...B,fontSize:11,color:C.sub,fontWeight:600}}>📍 Distância</span>
                      <span style={{...H,fontSize:14,fontWeight:900,color:C.green}}>{selWorker.distLabel}</span>
                    </div>
                  </div>
                );
              }
              return (
                <div style={{background:C.white,border:`2px solid ${C.greenBorder}`,borderRadius:14,padding:20,boxShadow:"0 4px 20px rgba(22,163,74,.08)"}}>
                  {inv?.status === "declined" && <div style={{display:"inline-flex",alignItems:"center",gap:6,background:C.redBg,border:`1px solid ${C.redBorder}`,borderRadius:6,padding:"3px 9px",marginBottom:10,...B,fontSize:11,fontWeight:700,color:C.red}}>✕ Recusou anteriormente</div>}
                  <div style={{...H,fontSize:15,fontWeight:800,color:C.navy,marginBottom:6}}>Convide {firstName} para conversar</div>
                  <p style={{...B,fontSize:12,color:C.sub,marginBottom:14,lineHeight:1.5}}>Envie uma mensagem para {firstName}. {pron==="ela"?"Ela":"Ele"} vai receber no app e poderá aceitar ou recusar. Quando aceitar, vocês conversam pelo WhatsApp.</p>
                  <button onClick={()=>openInviteModal(selWorker)} style={{background:C.green,color:"#fff",border:"none",borderRadius:10,padding:"13px 16px",cursor:"pointer",width:"100%",...H,fontSize:14,fontWeight:800,boxShadow:"0 4px 12px rgba(22,163,74,.25)",transition:"all .15s",display:"flex",alignItems:"center",justifyContent:"center",gap:8}}
                    onMouseEnter={e=>{e.currentTarget.style.background="#15803D";e.currentTarget.style.transform="translateY(-1px)";}}
                    onMouseLeave={e=>{e.currentTarget.style.background=C.green;e.currentTarget.style.transform="translateY(0)";}}>
                    <span style={{fontSize:16}}>📨</span>
                    <span>Convidar para conversar</span>
                  </button>
                  <div style={{marginTop:10,padding:"8px 12px",background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:8,display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
                    <span style={{...B,fontSize:11,color:C.sub,fontWeight:600}}>📍 Distância da unidade</span>
                    <span style={{...H,fontSize:14,fontWeight:900,color:C.green}}>{selWorker.distLabel}</span>
                  </div>
                </div>
              );
            })()}

            {atencoes.length>0 && (
              <div style={{background:"#FEFCE8",border:"1px solid #FDE68A",borderRadius:14,padding:18}}>
                <div style={{...H,fontSize:12,fontWeight:800,color:"#92400E",marginBottom:10,letterSpacing:.3,textTransform:"uppercase",display:"flex",alignItems:"center",gap:6}}><span>⚠</span> Atenção</div>
                <div style={{display:"flex",flexDirection:"column",gap:6}}>
                  {atencoes.map((a,i)=>(
                    <div key={i} style={{...B,fontSize:12,color:"#92400E",lineHeight:1.45,display:"flex",gap:6,alignItems:"flex-start"}}>
                      <span style={{flexShrink:0}}>·</span><span>{a}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:18}}>
              <div style={{...H,fontSize:12,fontWeight:800,color:C.navy,marginBottom:10,letterSpacing:.3,textTransform:"uppercase"}}>Por que convidar pelo WhatsApp?</div>
              <div style={{display:"flex",flexDirection:"column",gap:7}}>
                {[
                  "Resposta rápida — Vorkers respondem em média em 2h",
                  "Sem login extra ou cadastro adicional",
                  "Mensagem já vem formatada com sua unidade",
                  "Conversa direta sem intermediários",
                ].map((t,i)=>(
                  <div key={i} style={{display:"flex",gap:7,alignItems:"flex-start"}}>
                    <span style={{color:C.green,fontSize:12,fontWeight:900,marginTop:1}}>✓</span>
                    <span style={{...B,fontSize:11.5,color:C.sub,lineHeight:1.45}}>{t}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    );
  })();

  return (
    <div style={{minHeight:"90vh",background:C.bg}}>
      {deleteModal&&<DeleteModal />}
      {invModal && (
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
          <div style={{background:C.white,borderRadius:14,maxWidth:480,width:"100%",overflow:"hidden",boxShadow:"0 20px 60px rgba(0,0,0,.25)"}}>
            <div style={{padding:"20px 24px",borderBottom:`1px solid ${C.border}`}}>
              <h3 style={{...H,fontSize:18,fontWeight:900,color:C.navy,marginBottom:4}}>Convidar {invModal.worker.nome.split(" ")[0]}</h3>
              <p style={{...B,fontSize:13,color:C.sub,lineHeight:1.5,margin:0}}>O colaborador vai receber seu convite no app dele e poderá aceitar ou recusar. Quando aceitar, o WhatsApp será revelado pra você.</p>
            </div>
            <div style={{padding:"20px 24px"}}>
              {units.length>1 && (
                <div style={{marginBottom:16}}>
                  <label style={{...B,fontSize:12,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>Para qual unidade?</label>
                  <select value={invModal.unitId} onChange={e=>setInvModal({...invModal,unitId:e.target.value})}
                    style={{padding:"10px 12px",borderRadius:9,border:`1.5px solid ${C.border2}`,background:C.white,...B,fontSize:13,color:C.navy,width:"100%",cursor:"pointer"}}>
                    {units.map(u=><option key={u.id} value={u.id}>{u.nome} — {u.bairro}, {u.cidade}/{u.estado}</option>)}
                  </select>
                </div>
              )}
              <Field label="Mensagem (opcional)" placeholder="Olá! Tenho um turno de 6h às 14h. Topa conversar?" value={invModal.message} onChange={v=>setInvModal({...invModal,message:v})} />
              <div style={{padding:"10px 12px",background:C.bg,borderRadius:9,...B,fontSize:11.5,color:C.sub,lineHeight:1.5,marginBottom:14}}>
                ℹ️ Você pode ter no máximo <strong>5 convites pendentes</strong> ao mesmo tempo. A relação de trabalho é diretamente entre vocês — Giobbi's apenas conecta.
              </div>
              {invError && <Alert type="error">{invError}</Alert>}
              <div style={{display:"flex",gap:10}}>
                <Btn label="Enviar convite" variant="primary" size="md" onClick={sendInvite} loading={invSaving} disabled={!invModal.unitId} />
                <Btn label="Cancelar" variant="ghost" size="md" onClick={()=>setInvModal(null)} disabled={invSaving} />
              </div>
            </div>
          </div>
        </div>
      )}
      {invToast && (
        <div style={{position:"fixed",top:80,left:"50%",transform:"translateX(-50%)",background:invToast.type==="success"?C.greenBg:C.redBg,border:`1px solid ${invToast.type==="success"?C.greenBorder:C.redBorder}`,borderRadius:10,padding:"12px 18px",...B,fontSize:13,color:invToast.type==="success"?C.green:C.red,fontWeight:600,zIndex:998,boxShadow:"0 6px 20px rgba(0,0,0,.1)",maxWidth:480}}>
          {invToast.msg}
        </div>
      )}

      {/* Header — mesmo estilo do colaborador/landing/admin */}
      <header className="hdr">
        <div style={{width:"100%",padding:"0 24px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:18}}>
          <img src={VORKER_LOGO} alt="Vorker" style={{height:44,objectFit:"contain"}} />
          <div style={{display:"flex",alignItems:"center",gap:12}}>
            <span style={{...B,fontSize:13,color:C.sub}} className="breadcrumb-text">Olá, {(company.resp_nome||company.nome_fant||company.razao||"").split(" ")[0]}</span>
            <Btn label="Sair" variant="ghost" size="sm" onClick={onLogout} />
          </div>
        </div>
      </header>

      {/* Tab bar — sub-header branco com pílulas */}
      <div style={{background:"#fff",borderBottom:`1px solid ${C.border}`,padding:"8px 20px",display:"flex",gap:4,position:"sticky",top:60,zIndex:200,overflowX:"auto"}}>
        {[
          {id:"talent",      icon:"🔍", label:"Talent Browser"},
          {id:"profile",     icon:"🏢", label:"Meu Perfil"},
          {id:"vorker-team", icon:"⚡", label:"Time Vorker", soon:true},
        ].map(t=>(
          <button key={t.id}
            onClick={()=>!t.soon&&setTab(t.id)}
            className={`tab-pill ${tab===t.id?"active":""} ${t.soon?"disabled":""}`}>
            <span style={{fontSize:14}}>{t.icon}</span>
            {t.label}
            {t.soon&&<span style={{fontSize:9,fontWeight:700,color:"#7C3AED",background:"#F3E8FF",borderRadius:5,padding:"1px 5px",letterSpacing:.4,marginLeft:3}}>EM BREVE</span>}
          </button>
        ))}
      </div>

      <div style={{maxWidth:1280,margin:"0 auto",padding:"28px 32px"}}>

        {/* ── TAB: TALENT BROWSER ── */}
        {tab==="talent"&&<>
          {/* Unit selector */}
          <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22,marginBottom:20}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
              <div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>Selecione a unidade onde precisa de colaboradores</div>
              {units.length===0&&<Btn label="+ Cadastrar unidade" variant="outline" size="sm" onClick={()=>{setTab("profile");setSubTab("unidades");}} />}
            </div>
            {units.length===0
              ? <div style={{background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:10,padding:"16px 20px",display:"flex",alignItems:"center",gap:14}}>
                  <span style={{fontSize:28}}>⚠️</span>
                  <div>
                    <div style={{...H,fontSize:14,fontWeight:700,color:C.amber,marginBottom:4}}>Nenhuma unidade cadastrada</div>
                    <div style={{...B,fontSize:13,color:C.sub,marginBottom:10}}>Você precisa cadastrar ao menos uma unidade para buscar colaboradores na região.</div>
                    <Btn label="+ Cadastrar unidade →" variant="amber" size="sm" onClick={()=>{setTab("profile");setSubTab("unidades");}} />
                  </div>
                </div>
              : <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
                  {units.map(u=>(
                    <div key={u.id} onClick={()=>{setSelUnit(u);setWorkers([]);setFiltered([]);}}
                      style={{padding:"12px 18px",borderRadius:10,cursor:"pointer",border:`1.5px solid ${selUnit?.id===u.id?C.green:C.border2}`,background:selUnit?.id===u.id?C.greenBg:"#fff",transition:"all .15s"}}>
                      <div style={{...H,fontSize:14,fontWeight:700,color:selUnit?.id===u.id?C.green:C.navy}}>{u.nome}</div>
                      <div style={{...B,fontSize:12,color:C.muted,marginTop:2}}>📍 {u.bairro}, {u.cidade}/{u.estado}</div>
                      <div style={{...B,fontSize:11,color:C.muted,marginTop:1}}>CEP: {u.cep}</div>
                    </div>
                  ))}
                </div>
            }
          </div>

          {selUnit&&<>
            {/* Status bar */}
            <div style={{background:loading?C.amberBg:C.greenBg,border:`1px solid ${loading?C.amberBorder:C.greenBorder}`,borderRadius:10,padding:"10px 18px",marginBottom:16,display:"flex",alignItems:"center",gap:10}}>
              {loading&&<span style={{width:14,height:14,borderRadius:7,border:`2px solid ${C.amber}`,borderTopColor:"transparent",animation:"spin .7s linear infinite",display:"inline-block",flexShrink:0}} />}
              <span style={{...B,fontSize:13,fontWeight:600,color:loading?C.amber:C.green}}>{calcMsg||`Unidade: ${selUnit.nome}`}</span>
              {!loading&&<Btn label="↻ Atualizar" variant="ghost" size="sm" onClick={loadWorkers} />}
            </div>

            {/* Filters */}
            {!loading&&workers.length>0&&(
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:"16px 20px",marginBottom:16,display:"flex",gap:16,flexWrap:"wrap",alignItems:"flex-end"}}>
                <div>
                  <label style={{...B,fontSize:11,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>ESPECIALIDADE</label>
                  <select value={fSpecV} onChange={e=>{setFSpec(e.target.value);setFLevel(0);}}
                    style={{padding:"8px 12px",borderRadius:8,border:`1.5px solid ${C.border2}`,background:"#fff",...B,fontSize:13,cursor:"pointer"}}>
                    <option value="all">Todas</option>
                    {SPECS.map(s=><option key={s.id} value={s.id}>{s.icon} {s.label}</option>)}
                  </select>
                </div>
                {fSpecV!=="all"&&(
                  <div>
                    <label style={{...B,fontSize:11,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>EXPERIÊNCIA MÍNIMA</label>
                    <select value={fLevelV} onChange={e=>setFLevel(parseInt(e.target.value))}
                      style={{padding:"8px 12px",borderRadius:8,border:`1.5px solid ${C.border2}`,background:"#fff",...B,fontSize:13,cursor:"pointer"}}>
                      <option value={0}>Qualquer experiência</option>
                      <option value={2}>6 meses ou mais</option>
                      <option value={3}>1 ano ou mais</option>
                      <option value={4}>3 anos ou mais</option>
                      <option value={5}>5 anos ou mais</option>
                    </select>
                  </div>
                )}
                <div>
                  <label style={{...B,fontSize:11,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>DIA</label>
                  <select value={fDiaV} onChange={e=>setFDia(e.target.value)}
                    style={{padding:"8px 12px",borderRadius:8,border:`1.5px solid ${C.border2}`,background:"#fff",...B,fontSize:13,cursor:"pointer"}}>
                    <option value="all">Todos os dias</option>
                    {DAYS.map(d=><option key={d} value={d}>{d}</option>)}
                  </select>
                </div>
                <div>
                  <label style={{...B,fontSize:11,fontWeight:600,color:C.sub,display:"block",marginBottom:6}}>TURNO</label>
                  <select value={fTurnoV} onChange={e=>setFTurno(e.target.value)}
                    style={{padding:"8px 12px",borderRadius:8,border:`1.5px solid ${C.border2}`,background:"#fff",...B,fontSize:13,cursor:"pointer"}}>
                    <option value="all">Todos os turnos</option>
                    {SHIFTS.map(s=><option key={s.id} value={s.id}>{s.label}</option>)}
                  </select>
                </div>
                <div style={{...B,fontSize:12,color:C.muted,marginLeft:"auto"}}>
                  {filtered.length} colaborador{filtered.length!==1?"es":""} encontrado{filtered.length!==1?"s":""}
                </div>
              </div>
            )}

            {!loading&&filtered.length===0&&workers.length===0&&(
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:56,textAlign:"center"}}>
                <div style={{fontSize:48,marginBottom:14}}>🔍</div>
                <div style={{...H,fontSize:18,fontWeight:700,color:C.navy,marginBottom:8}}>Nenhum colaborador encontrado</div>
                <div style={{...B,fontSize:14,color:C.muted}}>Não há colaboradores aprovados dentro do raio de cobertura desta unidade ainda.</div>
              </div>
            )}
            {!loading&&filtered.length===0&&workers.length>0&&(
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:56,textAlign:"center"}}>
                <div style={{fontSize:48,marginBottom:14}}>🎯</div>
                <div style={{...H,fontSize:18,fontWeight:700,color:C.navy,marginBottom:8}}>Nenhum resultado com esses filtros</div>
                <div style={{...B,fontSize:14,color:C.muted}}>Tente remover alguns filtros.</div>
              </div>
            )}
            {!loading&&filtered.length>0&&(
              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(300px,1fr))",gap:14}}>
                {filtered.map(w=>{
                  const tempoShort = (t) => t==="Menos de 6 meses"?"<6m":t==="6 meses a 1 ano"?"6m-1a":t==="1 a 3 anos"?"1-3a":t==="3 a 5 anos"?"3-5a":t==="Mais de 5 anos"?"+5a":t;
                  const flex = w.flexibilidade && FLEX_LABEL[w.flexibilidade];
                  return (
                  <div key={w.id} onClick={()=>setSelWorker(w)}
                    style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:20,cursor:"pointer",transition:"all .18s"}}
                    onMouseEnter={e=>{e.currentTarget.style.borderColor=C.green;e.currentTarget.style.boxShadow="0 4px 16px rgba(22,163,74,.1)";}}
                    onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.boxShadow="none";}}>
                    <div style={{display:"flex",gap:12,alignItems:"center",marginBottom:14}}>
                      {w.foto_rosto ? (
                        <img src={w.foto_rosto} alt={w.nome} style={{width:46,height:46,borderRadius:23,objectFit:"cover",border:`2px solid ${C.greenBorder}`,flexShrink:0}} />
                      ) : (
                        <div style={{width:46,height:46,borderRadius:23,background:C.greenBg,border:`2px solid ${C.greenBorder}`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                          <span style={{...H,fontSize:16,fontWeight:900,color:C.green}}>{w.nome?.[0]}</span>
                        </div>
                      )}
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{...H,fontSize:15,fontWeight:700,color:C.navy,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{w.nome}</div>
                        <div style={{...B,fontSize:12,color:C.muted}}>{w.cidade}/{w.estado}</div>
                      </div>
                      <div style={{textAlign:"right",flexShrink:0}}>
                        <div style={{...H,fontSize:16,fontWeight:900,color:C.green}}>{w.distLabel}</div>
                        <div style={{...B,fontSize:10,color:C.muted}}>distância</div>
                      </div>
                    </div>
                    <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:10}}>
                      {SPECS.filter(s=>w.specs?.includes(s.id)).slice(0,3).map(s=>{
                        const tempo = w.func_exp?.[s.id]?.tempo;
                        return (
                          <div key={s.id} style={{display:"inline-flex",alignItems:"center",gap:5,background:C.bg,border:`1px solid ${C.border2}`,borderRadius:7,padding:"3px 9px"}}>
                            <span style={{fontSize:13}}>{s.icon}</span>
                            <span style={{...B,fontSize:11,fontWeight:600,color:C.navy}}>{s.label}</span>
                            {tempo && <span style={{...B,fontSize:9.5,color:C.green,fontWeight:700,background:C.greenBg,border:`1px solid ${C.greenBorder}`,padding:"0 5px",borderRadius:5,marginLeft:1}}>{tempoShort(tempo)}</span>}
                          </div>
                        );
                      })}
                      {(w.specs?.length||0)>3&&<span style={{...B,fontSize:11,color:C.muted,padding:"4px 6px"}}>+{w.specs.length-3}</span>}
                    </div>
                    {flex && (
                      <div style={{display:"inline-flex",alignItems:"center",gap:5,marginBottom:10,...B,fontSize:11,color:C.sub}}>
                        <span style={{fontSize:12}}>{flex.icon}</span>
                        <span style={{fontWeight:600,color:C.navy}}>{flex.label}</span>
                      </div>
                    )}
                    <div style={{borderTop:`1px solid ${C.border}`,paddingTop:10,display:"flex",gap:4,flexWrap:"wrap",marginBottom:12}}>
                      {DAYS.filter(d=>(w.disponibilidade?.[d]||[]).length>0).map(d=>(
                        <span key={d} style={{...B,fontSize:10,fontWeight:600,color:C.green,background:C.greenBg,padding:"2px 6px",borderRadius:4}}>{d}</span>
                      ))}
                      {DAYS.every(d=>!(w.disponibilidade?.[d]?.length>0)) && <span style={{...B,fontSize:10,color:C.muted,fontStyle:"italic"}}>Sem disponibilidade marcada</span>}
                    </div>
                    {(() => {
                      const inv = inviteFor(w.id);
                      if(inv?.status === "accepted") return (
                        <div onClick={e=>{e.stopPropagation();window.open(whatsappMsg(w),"_blank");}}
                          style={{background:"#25D366",borderRadius:8,padding:"9px 14px",textAlign:"center",display:"flex",alignItems:"center",justifyContent:"center",gap:7,cursor:"pointer"}}>
                          <span style={{fontSize:15}}>💬</span>
                          <span style={{...H,fontSize:13,fontWeight:700,color:"#fff"}}>Conversar pelo WhatsApp</span>
                        </div>
                      );
                      if(inv?.status === "pending") return (
                        <div style={{background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:8,padding:"9px 14px",textAlign:"center",display:"flex",alignItems:"center",justifyContent:"center",gap:7}}>
                          <span style={{fontSize:14}}>⏳</span>
                          <span style={{...H,fontSize:13,fontWeight:700,color:C.amber}}>Convite enviado</span>
                        </div>
                      );
                      return (
                        <div onClick={e=>{e.stopPropagation();openInviteModal(w);}}
                          style={{background:C.green,borderRadius:8,padding:"9px 14px",textAlign:"center",display:"flex",alignItems:"center",justifyContent:"center",gap:7,cursor:"pointer",boxShadow:"0 2px 8px rgba(22,163,74,.25)"}}>
                          <span style={{fontSize:15}}>📨</span>
                          <span style={{...H,fontSize:13,fontWeight:700,color:"#fff"}}>Convidar para conversar</span>
                        </div>
                      );
                    })()}
                  </div>
                  );
                })}
              </div>
            )}
          </>}
        </>}

        {/* ── TAB: MEU PERFIL ── */}
        {tab==="profile"&&<>
          <div style={{display:"grid",gridTemplateColumns:"230px 1fr",gap:24,alignItems:"start"}}>

            {/* SIDEBAR */}
            <aside style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:"18px 12px 14px",position:"sticky",top:20}}>
              <div style={{padding:"0 14px 12px",...B,fontSize:10.5,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:1.5}}>Navegação</div>
              {[
                {id:"visao-geral",   icon:"📊", label:"Visão geral"},
                {id:"dados-empresa", icon:"🏢", label:"Dados da empresa"},
                {id:"unidades",      icon:"📍", label:"Unidades de trabalho"},
                {id:"usuarios",      icon:"👥", label:"Usuários e acesso", soon:true},
                {id:"preferencias",  icon:"⚙️", label:"Preferências", soon:true},
                {id:"planos",        icon:"💳", label:"Planos e faturamento", soon:true},
              ].map(it=>(
                <button key={it.id} onClick={()=>!it.soon&&setSubTab(it.id)} disabled={it.soon}
                  style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"10px 14px",background:subTab===it.id?C.greenBg:"transparent",border:"none",borderRadius:9,cursor:it.soon?"default":"pointer",...B,fontSize:13,fontWeight:subTab===it.id?700:600,color:it.soon?C.muted:subTab===it.id?C.green:C.sub,marginBottom:2,transition:"all .15s"}}>
                  <span style={{fontSize:14}}>{it.icon}</span>
                  <span style={{flex:1,textAlign:"left"}}>{it.label}</span>
                  {it.soon&&<span style={{...B,fontSize:9,fontWeight:700,color:"#7C3AED",background:"#F3E8FF",borderRadius:7,padding:"2px 7px",letterSpacing:.5}}>EM BREVE</span>}
                </button>
              ))}

              <div style={{marginTop:18,padding:14,background:C.white,border:`1px solid ${C.border}`,borderRadius:12}}>
                <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:8,flexWrap:"wrap"}}>
                  <span style={{width:28,height:28,borderRadius:8,background:"#F3E8FF",display:"flex",alignItems:"center",justifyContent:"center",fontSize:14}}>⚡</span>
                  <span style={{...H,fontSize:13,fontWeight:800,color:C.navy}}>Time Vorker</span>
                  <span style={{...B,fontSize:9,fontWeight:700,color:"#7C3AED",background:"#F3E8FF",borderRadius:6,padding:"2px 6px",letterSpacing:.5}}>EM BREVE</span>
                </div>
                <div style={{...B,fontSize:11.5,color:C.sub,lineHeight:1.55,marginBottom:12}}>Monte seu time fixo com os melhores Vorkers.</div>
                <button style={{...B,fontSize:12,fontWeight:700,color:"#7C3AED",background:"#fff",border:"1.5px solid #7C3AED",borderRadius:9,padding:"9px 14px",cursor:"pointer",width:"100%"}}>Quero saber mais</button>
              </div>
            </aside>

            {/* MAIN */}
            <div>

              {/* ─── VISÃO GERAL ─── */}
              {subTab==="visao-geral"&&<>
                <div style={{marginBottom:24}}>
                  <h2 style={{...H,fontSize:24,fontWeight:900,color:C.navy,letterSpacing:-.5,marginBottom:6}}>
                    Bem-vindo, {((company.resp_nome||company.nome_fant||company.razao||"").split(" ")[0])} <span style={{color:C.green}}>👋</span>
                  </h2>
                  <p style={{...B,fontSize:14,color:C.sub,margin:0}}>Gerencie as informações da sua empresa, unidades e encontre os melhores Vorkers</p>
                </div>

                <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:12,marginBottom:20}}>
                  {[
                    {v:units.length, l:"Unidades",          icon:"🏢", color:C.green,   bg:C.greenBg},
                    {v:invites.filter(i=>i.status==="accepted").length, l:"Convites aceitos", icon:"✓", color:"#7C3AED", bg:"#F3E8FF"},
                    {v:invites.filter(i=>i.status==="pending").length,  l:"Convites enviados", icon:"📨", color:"#F59E0B", bg:"#FEF3C7"},
                    {v:0,             l:"Vorkers próximos",   icon:"📍", color:"#06B6D4", bg:"#CFFAFE"},
                  ].map((s,i)=>(
                    <div key={i} style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:"16px 18px"}}>
                      <div style={{width:34,height:34,borderRadius:10,background:s.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16,marginBottom:10}}>{s.icon}</div>
                      <div style={{...H,fontSize:28,fontWeight:900,color:C.navy,letterSpacing:-.5,lineHeight:1}}>{s.v}</div>
                      <div style={{...B,fontSize:12,color:C.muted,marginTop:5}}>{s.l}</div>
                    </div>
                  ))}
                </div>

                <div style={{display:"grid",gridTemplateColumns:"2fr 1fr",gap:14}}>
                  {/* LEFT — Unidades */}
                  <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:18}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
                      <div style={{...H,fontSize:14,fontWeight:800,color:C.navy}}>Unidades de trabalho</div>
                    </div>
                    {units.length===0?(
                      <div style={{padding:"30px 0",textAlign:"center",...B,fontSize:13,color:C.muted}}>Nenhuma unidade cadastrada ainda.</div>
                    ):units.map(u=>(
                      <div key={u.id} style={{padding:"12px 14px",border:`1px solid ${C.border}`,borderRadius:10,marginBottom:8,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                        <div style={{display:"flex",gap:12,alignItems:"center",minWidth:0}}>
                          <span style={{width:9,height:9,borderRadius:4.5,background:C.green,flexShrink:0}} />
                          <div style={{minWidth:0}}>
                            <div style={{...H,fontSize:13,fontWeight:700,color:C.navy}}>{u.nome}</div>
                            <div style={{...B,fontSize:11.5,color:C.muted,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{u.rua}, {u.numero} · {u.bairro} · {u.cidade}/{u.estado}</div>
                          </div>
                        </div>
                        <span style={{...B,fontSize:10.5,fontWeight:700,color:C.green,background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:6,padding:"3px 8px",flexShrink:0,marginLeft:10}}>Ativa</span>
                      </div>
                    ))}
                    <button onClick={()=>setSubTab("unidades")} style={{...B,fontSize:13,fontWeight:600,color:C.green,background:"none",border:"none",cursor:"pointer",padding:"10px 0 0",display:"inline-flex",alignItems:"center",gap:5}}>
                      + Adicionar nova unidade
                    </button>
                  </div>

                  {/* RIGHT — Ações rápidas + Empresa */}
                  <div style={{display:"flex",flexDirection:"column",gap:14}}>
                    <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:18}}>
                      <div style={{...H,fontSize:13,fontWeight:800,color:C.navy,marginBottom:8}}>Ações rápidas</div>
                      {[
                        {icon:"🔍", title:"Buscar Vorkers",     desc:"Encontre talentos próximos das suas unidades",  onClick:()=>setTab("talent")},
                        {icon:"➕", title:"Adicionar unidade",  desc:"Cadastre uma nova localização operacional",     onClick:()=>setSubTab("unidades")},
                        {icon:"👤", title:"Gerenciar acessos",  desc:"Convide novos administradores",                 soon:true},
                      ].map((a,i,arr)=>(
                        <button key={i} onClick={a.onClick} disabled={a.soon}
                          style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"10px 0",background:"transparent",border:"none",borderBottom:i<arr.length-1?`1px solid ${C.border}`:"none",cursor:a.soon?"default":"pointer",textAlign:"left",opacity:a.soon?.5:1}}>
                          <span style={{fontSize:16,flexShrink:0}}>{a.icon}</span>
                          <div style={{flex:1,minWidth:0}}>
                            <div style={{...H,fontSize:13,fontWeight:700,color:C.navy}}>{a.title}</div>
                            <div style={{...B,fontSize:11,color:C.muted,marginTop:2,lineHeight:1.4}}>{a.desc}</div>
                          </div>
                          <span style={{color:C.muted,fontSize:14,flexShrink:0}}>→</span>
                        </button>
                      ))}
                    </div>

                    <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:18}}>
                      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
                        <div style={{...H,fontSize:13,fontWeight:800,color:C.navy}}>Informações da empresa</div>
                        <Badge status={company.status} />
                      </div>
                      {[
                        ["Razão social", company.razao],
                        ["Segmento",     company.seg],
                        ["Cidade",       `${company.cidade}/${company.estado}`],
                        ["CNPJ",         company.cnpj],
                        ["E-mail",       company.resp_email],
                      ].map(([k,v],i,arr)=>(
                        <div key={k} style={{padding:"7px 0",borderBottom:i<arr.length-1?`1px solid ${C.border}`:"none"}}>
                          <div style={{...B,fontSize:10.5,color:C.muted,textTransform:"uppercase",letterSpacing:.5,marginBottom:2}}>{k}</div>
                          <div style={{...B,fontSize:12.5,color:C.navy,fontWeight:600,wordBreak:"break-word"}}>{v||"—"}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:18,marginTop:14}}>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14,gap:10,flexWrap:"wrap"}}>
                    <div style={{...H,fontSize:14,fontWeight:800,color:C.navy}}>📨 Convites enviados</div>
                    <div style={{...B,fontSize:12,color:C.muted}}>{invites.length} no total · {invites.filter(i=>i.status==="pending").length} pendentes</div>
                  </div>
                  {invites.length===0 ? (
                    <div style={{padding:"24px 0",textAlign:"center",...B,fontSize:13,color:C.muted}}>
                      Você ainda não enviou nenhum convite.<br/>
                      <button onClick={()=>setTab("talent")} style={{...B,fontSize:13,fontWeight:600,color:C.green,background:"none",border:"none",cursor:"pointer",marginTop:8,textDecoration:"underline"}}>Ir para o Talent Browser →</button>
                    </div>
                  ) : (
                    <div style={{display:"flex",flexDirection:"column",gap:8}}>
                      {invites.slice(0,8).map(inv=>{
                        const statusCfg = {
                          pending:  {label:"⏳ Aguardando resposta", bg:C.amberBg, color:C.amber, border:C.amberBorder},
                          accepted: {label:"✓ Aceito",                bg:C.greenBg, color:C.green, border:C.greenBorder},
                          declined: {label:"✕ Recusado",              bg:C.redBg,   color:C.red,   border:C.redBorder},
                        }[inv.status] || {label:inv.status, bg:C.bg, color:C.muted, border:C.border};
                        return (
                          <div key={inv.id} style={{padding:"10px 12px",border:`1px solid ${C.border}`,borderRadius:10,display:"flex",gap:10,alignItems:"center"}}>
                            {inv.workers?.foto_rosto
                              ? <img src={inv.workers.foto_rosto} alt="" style={{width:36,height:36,borderRadius:18,objectFit:"cover",flexShrink:0}} />
                              : <div style={{width:36,height:36,borderRadius:18,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,...H,fontSize:14,fontWeight:800,color:"#fff"}}>{inv.workers?.nome?.[0]||"?"}</div>}
                            <div style={{flex:1,minWidth:0}}>
                              <div style={{...H,fontSize:13,fontWeight:700,color:C.navy,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{inv.workers?.nome||"Worker"}</div>
                              <div style={{...B,fontSize:11.5,color:C.muted,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>
                                {inv.company_units?.nome ? `${inv.company_units.nome} · ` : ""}{new Date(inv.created_at).toLocaleDateString("pt-BR")}
                              </div>
                            </div>
                            <span style={{...B,fontSize:10.5,fontWeight:700,color:statusCfg.color,background:statusCfg.bg,border:`1px solid ${statusCfg.border}`,borderRadius:6,padding:"3px 8px",whiteSpace:"nowrap",flexShrink:0}}>{statusCfg.label}</span>
                            {inv.status==="accepted" && inv.workers?.telefone && (
                              <a href={`https://wa.me/55${inv.workers.telefone.replace(/\D/g,"")}`} target="_blank" rel="noopener noreferrer"
                                style={{textDecoration:"none",background:"#25D366",borderRadius:8,padding:"6px 10px",...H,fontSize:11.5,fontWeight:700,color:"#fff",whiteSpace:"nowrap",flexShrink:0,display:"inline-flex",alignItems:"center",gap:5}}>
                                💬 Conversar pelo WhatsApp
                              </a>
                            )}
                          </div>
                        );
                      })}
                      {invites.length>8 && <div style={{...B,fontSize:11.5,color:C.muted,textAlign:"center",paddingTop:6}}>e mais {invites.length-8}…</div>}
                    </div>
                  )}
                </div>

                <div style={{marginTop:24,padding:"22px 28px",borderRadius:14,background:"linear-gradient(135deg,#16A34A,#15803D)",display:"flex",justifyContent:"space-between",alignItems:"center",gap:20,flexWrap:"wrap"}}>
                  <div style={{minWidth:0}}>
                    <div style={{...B,fontSize:10.5,fontWeight:700,color:"rgba(255,255,255,.7)",textTransform:"uppercase",letterSpacing:1.5,marginBottom:6}}>Time Vorker — em breve</div>
                    <div style={{...H,fontSize:18,fontWeight:900,color:"#fff",lineHeight:1.25,marginBottom:4}}>Monte seu time fixo com a Time Vorker</div>
                    <div style={{...B,fontSize:13,color:"rgba(255,255,255,.85)",lineHeight:1.5}}>Tenha sua equipe dedicada de Vorkers só para sua marca, com estabilidade e performance.</div>
                  </div>
                  <button style={{...B,fontSize:13,fontWeight:700,color:C.green,background:"#fff",border:"none",borderRadius:9,padding:"11px 20px",cursor:"pointer",whiteSpace:"nowrap"}}>Quero saber mais</button>
                </div>
              </>}

              {/* ─── UNIDADES DE TRABALHO ─── */}
              {subTab==="unidades"&&<>
                <div style={{marginBottom:18}}>
                  <h2 style={{...H,fontSize:22,fontWeight:900,color:C.navy,letterSpacing:-.5,marginBottom:4}}>Unidades de trabalho</h2>
                  <p style={{...B,fontSize:13,color:C.sub,margin:0}}>Cadastre as localizações onde sua empresa precisa de Vorkers.</p>
                </div>

                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:22,marginBottom:14}}>
                  <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:14}}>Suas unidades</div>
                  {units.length===0&&<Alert type="warning">Nenhuma unidade cadastrada. Adicione abaixo para poder usar o Talent Browser.</Alert>}
                  {units.map(u=>(
                    <div key={u.id} style={{background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:10,padding:"14px 16px",marginBottom:10,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                      <div>
                        <div style={{...H,fontSize:14,fontWeight:700,color:C.navy}}>{u.nome}</div>
                        <div style={{...B,fontSize:12,color:C.sub,marginTop:3}}>{u.rua}, {u.numero} — {u.bairro}</div>
                        <div style={{...B,fontSize:12,color:C.muted}}>{u.cidade}/{u.estado} · CEP {u.cep}</div>
                      </div>
                      <button onClick={()=>setDeleteModal({id:u.id,name:u.nome})}
                        style={{background:C.redBg,border:`1px solid ${C.redBorder}`,borderRadius:7,padding:"5px 10px",cursor:"pointer",...B,fontSize:12,color:C.red,flexShrink:0}}>Remover</button>
                    </div>
                  ))}
                </div>

                <div style={{background:C.bg,border:`1.5px dashed ${C.border2}`,borderRadius:14,padding:22}}>
                  <div style={{...H,fontSize:14,fontWeight:700,color:C.navy,marginBottom:14}}>+ Adicionar unidade</div>
                  <Field label="Nome da unidade" placeholder="Ex: Loja Lapa, CD Guarulhos" value={newUnit.nome} onChange={v=>setNewUnit(u=>({...u,nome:v}))} />

                  {company.cep&&(
                    <button onClick={()=>setNewUnit({
                      nome: newUnit.nome || "Sede",
                      cep: company.cep, rua: company.rua, numero: company.numero,
                      complemento: company.complemento || "", bairro: company.bairro,
                      cidade: company.cidade, estado: company.estado,
                    })}
                      style={{display:"flex",alignItems:"center",gap:11,width:"100%",padding:"12px 14px",background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:10,cursor:"pointer",marginBottom:14,textAlign:"left",transition:"all .15s"}}
                      onMouseEnter={e=>e.currentTarget.style.background="#DCFCE7"}
                      onMouseLeave={e=>e.currentTarget.style.background=C.greenBg}>
                      <span style={{fontSize:18,flexShrink:0}}>📋</span>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{...H,fontSize:13,fontWeight:700,color:C.green,marginBottom:2}}>Usar o mesmo endereço do cadastro da empresa</div>
                        <div style={{...B,fontSize:11.5,color:C.sub,lineHeight:1.4}}>Para empresas sem filiais — preenche o endereço com os dados do cadastro</div>
                      </div>
                    </button>
                  )}

                  <AddressBlock data={newUnit} setData={setNewUnit} loading={uCepLoad} setLoading={setUCepLoad} />
                  <Btn label={savingUnit?"Salvando...":"+ Adicionar unidade"} variant={newUnit.nome&&newUnit.cep&&newUnit.rua&&newUnit.numero?"primary":"ghost"} size="md"
                    onClick={addUnit} disabled={!newUnit.nome||!newUnit.cep||!newUnit.rua||!newUnit.numero} loading={savingUnit} />
                </div>
              </>}

              {/* ─── DADOS DA EMPRESA ─── */}
              {subTab==="dados-empresa"&&<>
                <div style={{marginBottom:18}}>
                  <h2 style={{...H,fontSize:22,fontWeight:900,color:C.navy,letterSpacing:-.5,marginBottom:4}}>Dados da empresa</h2>
                  <p style={{...B,fontSize:13,color:C.sub,margin:0}}>Informações cadastrais e do responsável pelo acesso.</p>
                </div>

                {companyToast&&<Alert type={companyToast.type}>{companyToast.msg}</Alert>}

                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:24}}>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,gap:12,flexWrap:"wrap"}}>
                    <div style={{display:"flex",alignItems:"center",gap:10}}>
                      <div style={{...H,fontSize:13,fontWeight:800,color:C.navy,textTransform:"uppercase",letterSpacing:.5}}>Empresa</div>
                      <Badge status={company.status} />
                    </div>
                    {!editingCompany && <Btn label="Editar dados" variant="ghost" size="sm" onClick={startEditCompany} />}
                  </div>

                  {!editingCompany ? (
                    <>
                      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",columnGap:24,rowGap:0}}>
                        {[
                          ["Razão social",  company.razao],
                          ["Nome fantasia", company.nome_fant||"—"],
                          ["CNPJ",          company.cnpj],
                          ["Segmento",      company.seg],
                          ["Site",          company.site||"—"],
                          ["Cidade",        `${company.cidade}/${company.estado}`],
                        ].map(([k,v])=>(
                          <div key={k} style={{padding:"10px 0",borderBottom:`1px solid ${C.border}`}}>
                            <div style={{...B,fontSize:10.5,color:C.muted,textTransform:"uppercase",letterSpacing:.5,marginBottom:3}}>{k}</div>
                            <div style={{...B,fontSize:13,color:C.navy,fontWeight:600,wordBreak:"break-word"}}>{v}</div>
                          </div>
                        ))}
                      </div>

                      <div style={{...H,fontSize:13,fontWeight:800,color:C.navy,marginTop:24,marginBottom:14,textTransform:"uppercase",letterSpacing:.5}}>Responsável pelo acesso</div>

                      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",columnGap:24,rowGap:0}}>
                        {[
                          ["Nome",     company.resp_nome],
                          ["Cargo",    company.resp_cargo||"—"],
                          ["WhatsApp", company.resp_tel],
                          ["E-mail",   company.resp_email],
                        ].map(([k,v])=>(
                          <div key={k} style={{padding:"10px 0",borderBottom:`1px solid ${C.border}`}}>
                            <div style={{...B,fontSize:10.5,color:C.muted,textTransform:"uppercase",letterSpacing:.5,marginBottom:3}}>{k}</div>
                            <div style={{...B,fontSize:13,color:C.navy,fontWeight:600,wordBreak:"break-word"}}>{v||"—"}</div>
                          </div>
                        ))}
                      </div>

                      {company.status==="pending"&&(
                        <div style={{marginTop:18,padding:"10px 14px",background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:9,...B,fontSize:12.5,color:C.amber,lineHeight:1.55}}>
                          ⏳ Seu cadastro está em análise pela equipe Vorker. Em até 24h úteis você receberá retorno.
                        </div>
                      )}
                    </>
                  ) : (
                    <>
                      <div style={{padding:"10px 14px",background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:9,...B,fontSize:12.5,color:C.amber,lineHeight:1.55,marginBottom:18}}>
                        ⚠️ Editar dados do cadastro fará seu cadastro voltar para análise da equipe Vorker. Em até 24h úteis você terá retorno.
                      </div>

                      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",columnGap:14,rowGap:0}}>
                        <Field label="Razão social" value={editData.razao} onChange={v=>setEditData({...editData,razao:v})} required />
                        <Field label="Nome fantasia" value={editData.nome_fant} onChange={v=>setEditData({...editData,nome_fant:v})} />
                      </div>
                      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",columnGap:14,rowGap:0}}>
                        <Field label="CNPJ" value={company.cnpj} disabled hint="Não pode ser alterado" />
                        <SelectField label="Segmento" value={editData.seg} onChange={v=>setEditData({...editData,seg:v})} options={SEGS} required />
                      </div>
                      <Field label="Site" placeholder="https://..." value={editData.site} onChange={v=>setEditData({...editData,site:v})} />

                      <div style={{...H,fontSize:13,fontWeight:800,color:C.navy,marginTop:18,marginBottom:8,textTransform:"uppercase",letterSpacing:.5}}>Endereço</div>
                      <AddressBlock data={editData} setData={setEditData} loading={editCepLoad} setLoading={setEditCepLoad} />

                      <div style={{...H,fontSize:13,fontWeight:800,color:C.navy,marginTop:18,marginBottom:8,textTransform:"uppercase",letterSpacing:.5}}>Responsável pelo acesso</div>
                      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",columnGap:14,rowGap:0}}>
                        <Field label="Nome" value={editData.resp_nome} onChange={v=>setEditData({...editData,resp_nome:v})} required />
                        <Field label="Cargo" value={editData.resp_cargo} onChange={v=>setEditData({...editData,resp_cargo:v})} />
                      </div>
                      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",columnGap:14,rowGap:0}}>
                        <Field label="WhatsApp" value={editData.resp_tel} onChange={v=>setEditData({...editData,resp_tel:maskPhone(v)})} maxLength={15} />
                        <Field label="E-mail" value={editData.resp_email} onChange={v=>setEditData({...editData,resp_email:v})} type="email" required />
                      </div>

                      <div style={{display:"flex",gap:10,marginTop:18,flexWrap:"wrap"}}>
                        <Btn label="Salvar e enviar para análise" variant="primary" size="md" onClick={saveCompanyEdit} loading={savingCompany} disabled={!editData.razao||!editData.seg||!editData.resp_nome||!editData.resp_email} />
                        <Btn label="Cancelar" variant="ghost" size="md" onClick={()=>setEditingCompany(false)} disabled={savingCompany} />
                      </div>
                    </>
                  )}
                </div>
              </>}

              {/* ─── PLACEHOLDERS ─── */}
              {(subTab==="usuarios"||subTab==="preferencias"||subTab==="planos")&&(
                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:60,textAlign:"center"}}>
                  <div style={{fontSize:42,marginBottom:14}}>🚧</div>
                  <div style={{...H,fontSize:18,fontWeight:800,color:C.navy,marginBottom:6}}>Em breve</div>
                  <div style={{...B,fontSize:13,color:C.muted,maxWidth:380,margin:"0 auto",lineHeight:1.6}}>
                    Essa área está em desenvolvimento e ficará disponível em uma das próximas atualizações.
                  </div>
                </div>
              )}

            </div>
          </div>
        </>}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// AUTH CHOICE — tela de escolha unificada
// ═══════════════════════════════════════════════════════════════
function AuthChoice({ onNav }) {
  return (
    <div style={{minHeight:"75vh",display:"flex",alignItems:"center",justifyContent:"center",padding:"60px 20px",background:C.bg}}>
      <div style={{maxWidth:560,width:"100%"}}>
        <div style={{textAlign:"center",marginBottom:40}}>
          <h2 style={{...H,fontSize:34,fontWeight:900,color:C.navy,letterSpacing:-1.2,marginBottom:10}}>Bem-vindo ao VORKER</h2>
          <p style={{...B,fontSize:15,color:C.muted}}>Como deseja acessar?</p>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16,marginBottom:20}}>
          {/* Empresa */}
          <div onClick={()=>onNav("company-auth")}
            style={{background:C.white,border:`1.5px solid ${C.border}`,borderRadius:16,padding:32,cursor:"pointer",textAlign:"center",transition:"all .18s"}}
            onMouseEnter={e=>{e.currentTarget.style.borderColor=C.green;e.currentTarget.style.boxShadow="0 4px 20px rgba(22,163,74,.1)";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.boxShadow="none";}}>
            <div style={{fontSize:48,marginBottom:14}}>🏢</div>
            <div style={{...H,fontSize:20,fontWeight:900,color:C.navy,marginBottom:8}}>Sou uma empresa</div>
            <div style={{...B,fontSize:13,color:C.sub,lineHeight:1.65,marginBottom:20}}>Acesse o Talent Browser e encontre colaboradores verificados na sua região.</div>
            <div style={{background:C.green,borderRadius:9,padding:"11px 20px",...H,fontSize:14,fontWeight:700,color:"#fff"}}>Entrar como empresa →</div>
          </div>

          {/* Colaborador */}
          <div onClick={()=>onNav("worker-auth")}
            style={{background:C.white,border:`1.5px solid ${C.border}`,borderRadius:16,padding:32,cursor:"pointer",textAlign:"center",transition:"all .18s"}}
            onMouseEnter={e=>{e.currentTarget.style.borderColor=C.blue;e.currentTarget.style.boxShadow="0 4px 20px rgba(37,99,235,.1)";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.boxShadow="none";}}>
            <div style={{fontSize:48,marginBottom:14}}>👤</div>
            <div style={{...H,fontSize:20,fontWeight:900,color:C.navy,marginBottom:8}}>Sou colaborador</div>
            <div style={{...B,fontSize:13,color:C.sub,lineHeight:1.65,marginBottom:20}}>Acesse sua conta e aguarde convites de empresas na sua região.</div>
            <div style={{background:C.blue,borderRadius:9,padding:"11px 20px",...H,fontSize:14,fontWeight:700,color:"#fff"}}>Entrar como colaborador →</div>
          </div>
        </div>

        {/* Cadastro links */}
        <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:12,padding:"18px 24px",display:"flex",justifyContent:"center",gap:32,flexWrap:"wrap"}}>
          <span style={{...B,fontSize:13,color:C.sub}}>Ainda não tem conta?</span>
          <span onClick={()=>onNav("company-register")} style={{...B,fontSize:13,color:C.green,cursor:"pointer",fontWeight:600}}>Cadastrar empresa →</span>
          <span onClick={()=>onNav("worker-register")} style={{...B,fontSize:13,color:C.blue,cursor:"pointer",fontWeight:600}}>Cadastrar como colaborador →</span>
        </div>
      </div>
    </div>
  );
}

// ─── WORKER PROFILE (self-view com edição por seção) ──────────
const WInfoLine = ({ icon, label, value }) => (
  <div style={{display:"flex",alignItems:"center",gap:10,padding:"8px 0"}}>
    <span style={{fontSize:18}}>{icon}</span>
    <div>
      <div style={{...B,fontSize:10.5,color:C.muted,textTransform:"uppercase",letterSpacing:.5,marginBottom:2}}>{label}</div>
      <div style={{...B,fontSize:13,color:C.navy,fontWeight:600}}>{value||"—"}</div>
    </div>
  </div>
);

function WorkerProfile({ worker, onLogout, onUpdate }) {
  const [w, setW] = useState(worker);
  const [editing, setEditing] = useState(null);
  const [d, setD] = useState(null);
  const [cepLoad, setCepLoad] = useState(false);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState(null);
  const [empresaNew, setEmpresaNew] = useState("");
  const [welcomeShown, setWelcomeShown] = useState(()=>{ try { return !localStorage.getItem("vorker:welcome_dismissed"); } catch { return true; } });
  const [invites, setInvites] = useState([]);
  const [invSaving, setInvSaving] = useState(false);
  const fotoRef = useRef(null);
  const selfieRef = useRef(null);

  const dismissWelcome = () => { try { localStorage.setItem("vorker:welcome_dismissed","1"); } catch {} setWelcomeShown(false); };

  useEffect(() => { if(w.id) fetchInvitesByWorker(w.id).then(setInvites).catch(()=>{}); }, [w.id]);

  const respond = async (id, status) => {
    setInvSaving(true);
    try {
      await respondInvite(id, status);
      setInvites(invs => invs.map(i => i.id===id ? {...i, status, responded_at:new Date().toISOString()} : i));
    } catch(e) { setToast({type:"error", msg:"Erro ao responder convite. Tente novamente."}); setTimeout(()=>setToast(null), 4000); }
    finally { setInvSaving(false); }
  };

  const flash = (type,msg,ms=5000) => { setToast({type,msg}); setTimeout(()=>setToast(null), ms); };
  const readFile = (file,key) => { const r=new FileReader(); r.onload=e=>setD(prev=>({...prev,[key]:e.target.result})); r.readAsDataURL(file); };

  const startEdit = (section) => {
    let data = {};
    if(section==="identidade") data = {nome:w.nome||"", foto_rosto:w.foto_rosto||null, selfie_doc:w.selfie_doc||null, doc_tipo:w.doc_tipo||"RG"};
    if(section==="contato")    data = {telefone:w.telefone||"", cep:w.cep||"", rua:w.rua||"", numero:w.numero||"", complemento:w.complemento||"", bairro:w.bairro||"", cidade:w.cidade||"", estado:w.estado||"", raio_km:w.raio_km||10, deslocamento:w.deslocamento||""};
    if(section==="disponibilidade") data = {disponibilidade: JSON.parse(JSON.stringify(w.disponibilidade||{})), flexibilidade:w.flexibilidade||""};
    if(section==="especialidades")  data = {specs:[...(w.specs||[])], spec_levels:JSON.parse(JSON.stringify(w.spec_levels||{})), func_exp:JSON.parse(JSON.stringify(w.func_exp||{})), specCustom:w.spec_levels?.custom?.label||""};
    if(section==="empresas")        data = {empresas_selected:[...(w.empresas_selected||[])], empresas_custom:[...(w.empresas_custom||[])]};
    if(section==="perfil")          data = {perfil_trabalho: JSON.parse(JSON.stringify(w.perfil_trabalho||{}))};
    if(section==="outros")          data = {pcd:!!w.pcd, pcd_tipo:w.pcd_tipo||"", trabalho_equipe:w.trabalho_equipe||"", atend_cliente:w.atend_cliente||"", tipo_trabalho:w.tipo_trabalho||""};
    setD(data); setEditing(section); setEmpresaNew("");
  };

  const cancelEdit = () => { setEditing(null); setD(null); setEmpresaNew(""); };

  const saveSection = async () => {
    setSaving(true);
    try {
      let changes = {...d, status:"pending", reject_note:""};
      if(editing==="disponibilidade") {
        changes.dias = Object.keys(d.disponibilidade).filter(day=>d.disponibilidade[day]?.length>0);
        changes.turnos = [...new Set(Object.values(d.disponibilidade).flat())];
      }
      if(editing==="especialidades") {
        if(d.specs.includes("custom") && d.specCustom) {
          changes.spec_levels = {...d.spec_levels, custom: {...(d.spec_levels?.custom||{}), label: d.specCustom}};
        }
        delete changes.specCustom;
      }
      if(editing==="outros" && !d.pcd) changes.pcd_tipo = "";
      await updateWorkerDB(w.id, changes);
      const newW = {...w, ...changes};
      setW(newW); onUpdate(newW);
      setEditing(null); setD(null); setEmpresaNew("");
      flash("warning","Dados atualizados. Seu cadastro voltou para análise da equipe Vorker.",6000);
    } catch(e) {
      flash("error", `Erro ao salvar: ${e?.message || "tente novamente"}`);
    }
    finally { setSaving(false); }
  };

  const toggleSpec = (id) => {
    setD(prev=>{
      const has = prev.specs.includes(id);
      const specs = has ? prev.specs.filter(s=>s!==id) : [...prev.specs, id];
      const func_exp = {...prev.func_exp};
      if(has) delete func_exp[id];
      return {...prev, specs, func_exp};
    });
  };
  const setSpecTempo = (id, tempo) => setD(prev=>({...prev, func_exp:{...prev.func_exp, [id]:{...(prev.func_exp[id]||{}), tempo}}}));
  const toggleEmpresaPreset = (id) => setD(prev=>({...prev, empresas_selected: prev.empresas_selected.includes(id) ? prev.empresas_selected.filter(x=>x!==id) : [...prev.empresas_selected, id]}));
  const addEmpresaCustom = () => { const n=empresaNew.trim(); if(!n) return; setD(prev=>({...prev, empresas_custom:[...prev.empresas_custom, n]})); setEmpresaNew(""); };
  const removeEmpresaCustom = (i) => setD(prev=>({...prev, empresas_custom: prev.empresas_custom.filter((_,idx)=>idx!==i)}));
  const toggleShift = (day, shiftId) => {
    setD(prev=>{
      const cur = prev.disponibilidade[day]||[];
      const next = cur.includes(shiftId) ? cur.filter(s=>s!==shiftId) : [...cur, shiftId];
      return {...prev, disponibilidade:{...prev.disponibilidade, [day]:next}};
    });
  };

  const especialidades = [
    ...SPECS.filter(s=>w.specs?.includes(s.id)).map(s=>({id:s.id,label:s.label,icon:s.icon,tempo:w.func_exp?.[s.id]?.tempo})),
    ...(w.specs?.includes("custom")?[{id:"custom",label:w.spec_levels?.custom?.label||"Função própria",icon:"⭐",tempo:w.func_exp?.custom?.tempo}]:[]),
  ];
  const empresasView = [
    ...(w.empresas_selected||[]).map(id=>{ const e=EMPRESAS_PRESET.find(x=>x.id===id); return e?{label:e.label,custom:false}:null; }).filter(Boolean),
    ...(w.empresas_custom||[]).map(nome=>({label:nome,custom:true})),
  ];

  const completeness = (() => {
    let s = 0, max = 0;
    max += 2;
    if(w.foto_rosto) s++;
    if(w.selfie_doc) s++;
    max += 2;
    const cells = Object.values(w.disponibilidade||{}).reduce((a,b)=>a+(b?.length||0),0);
    s += Math.min(cells,12)/12;
    if(w.flexibilidade) s++;
    max += 1.5;
    if(w.specs?.length>0){
      s += 1;
      const semTempo = w.specs.filter(x=>!w.func_exp?.[x]?.tempo).length;
      s += ((w.specs.length - semTempo) / w.specs.length) * 0.5;
    }
    max += 1;
    const totalEmp = (w.empresas_selected?.length||0)+(w.empresas_custom?.length||0);
    if(totalEmp>0) s++;
    max += 1.5;
    const ans = Object.keys(PERFIL_LABELS).filter(k=>w.perfil_trabalho?.[k]).length;
    s += (ans/5) * 1.5;
    max += 3;
    if(w.trabalho_equipe) s++;
    if(w.atend_cliente) s++;
    if(w.tipo_trabalho) s++;
    return Math.round((s/max)*100);
  })();
  const completeColor = completeness>=90?C.green : completeness>=70?"#65A30D" : completeness>=40?C.amber : C.red;

  const getMissing = (section) => {
    if(section==="identidade"){
      const list=[];
      if(!w.foto_rosto) list.push("uma foto de perfil");
      if(!w.selfie_doc) list.push(`a foto do seu ${w.doc_tipo||"documento"}`);
      return list;
    }
    if(section==="disponibilidade"){
      const list=[];
      const cells = Object.values(w.disponibilidade||{}).reduce((a,b)=>a+(b?.length||0),0);
      if(cells===0)      list.push("seus turnos disponíveis");
      else if(cells<6)   list.push(`mais turnos (você marcou só ${cells})`);
      if(!w.flexibilidade) list.push("sua flexibilidade pra avisos curtos");
      return list;
    }
    if(section==="especialidades"){
      const list=[];
      if(!w.specs?.length) list.push("suas especialidades");
      else {
        const sem = w.specs.filter(s=>!w.func_exp?.[s]?.tempo);
        if(sem.length>0) list.push(`o tempo de experiência em ${sem.length} função(ões)`);
      }
      return list;
    }
    if(section==="empresas"){
      const total = (w.empresas_selected?.length||0)+(w.empresas_custom?.length||0);
      return total===0 ? ["as empresas onde já trabalhou"] : [];
    }
    if(section==="perfil"){
      const ans = Object.keys(PERFIL_LABELS).filter(k=>w.perfil_trabalho?.[k]).length;
      return ans<5 ? [`as ${5-ans} pergunta(s) restantes`] : [];
    }
    if(section==="outros"){
      const list=[];
      if(!w.trabalho_equipe) list.push("preferência de trabalho em equipe");
      if(!w.atend_cliente)   list.push("experiência com atendimento");
      if(!w.tipo_trabalho)   list.push("tipo de trabalho preferido");
      return list;
    }
    return [];
  };

  const renderMissing = (section) => {
    if(editing===section) return null;
    const list = getMissing(section);
    if(list.length===0) return null;
    return (
      <div style={{padding:"10px 14px",background:C.blueBg,border:`1px solid ${C.blueBorder}`,borderRadius:9,...B,fontSize:12.5,color:C.blue,lineHeight:1.55,marginBottom:14,display:"flex",alignItems:"flex-start",gap:10}}>
        <span style={{fontSize:16,flexShrink:0,marginTop:1}}>💡</span>
        <div style={{flex:1}}>
          <strong>Pra ser chamado mais vezes, falta:</strong> {list.join(", ")}.{" "}
          <button onClick={()=>startEdit(section)} style={{...B,fontSize:12.5,fontWeight:700,color:C.blue,background:"transparent",border:"none",cursor:"pointer",padding:0,textDecoration:"underline"}}>Alterar agora →</button>
        </div>
      </div>
    );
  };

  const sectionStyle = {background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:20,marginBottom:14};
  const colorMap = {
    green:  {bg:C.greenBg,  border:C.greenBorder},
    blue:   {bg:C.blueBg,   border:C.blueBorder},
    amber:  {bg:C.amberBg,  border:C.amberBorder},
    violet: {bg:"#F3E8FF",  border:"#E9D5FF"},
  };

  const renderSectionHeader = ({ id, icon, color="green", title, subtitle }) => {
    const c = colorMap[color] || colorMap.green;
    return (
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14,gap:14,flexWrap:"wrap"}}>
        <div style={{display:"flex",alignItems:"center",gap:14,minWidth:0,flex:1}}>
          <div style={{width:48,height:48,borderRadius:12,background:c.bg,border:`1.5px solid ${c.border}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:24,flexShrink:0}}>{icon}</div>
          <div style={{minWidth:0}}>
            <div style={{...H,fontSize:16,fontWeight:800,color:C.navy,marginBottom:2,lineHeight:1.2}}>{title}</div>
            <div style={{...B,fontSize:12,color:C.muted,lineHeight:1.4}}>{subtitle}</div>
          </div>
        </div>
        {editing!==id && <Btn label="✏️ Alterar" variant="outline" size="md" onClick={()=>startEdit(id)} />}
      </div>
    );
  };

  const renderSaveCancel = (canSave=true) => (
    <div style={{marginTop:14,paddingTop:14,borderTop:`1px solid ${C.border}`}}>
      <div style={{padding:"10px 14px",background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:9,...B,fontSize:13,color:C.amber,lineHeight:1.5,marginBottom:12}}>
        ⚠️ Quando você salvar, seu cadastro vai voltar pra análise. Em até 1 dia útil a equipe Vorker te dá retorno.
      </div>
      <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
        <Btn label="Salvar e enviar para análise" variant="primary" size="md" onClick={saveSection} loading={saving} disabled={!canSave} />
        <Btn label="Cancelar" variant="ghost" size="md" onClick={cancelEdit} disabled={saving} />
      </div>
    </div>
  );

  return (
    <div style={{padding:"40px 20px",background:C.bg,minHeight:"calc(100vh - 60px)"}}>
      <div style={{maxWidth:920,margin:"0 auto"}}>
        {toast && <Alert type={toast.type}>{toast.msg}</Alert>}

        {welcomeShown && (
          <div style={{background:C.greenBg,border:`1.5px solid ${C.greenBorder}`,borderRadius:12,padding:"16px 18px",marginBottom:14,display:"flex",alignItems:"flex-start",gap:14}}>
            <div style={{fontSize:32,flexShrink:0,lineHeight:1}}>👋</div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{...H,fontSize:15,fontWeight:800,color:C.green,marginBottom:6}}>Olá! Bem-vindo ao seu perfil</div>
              <div style={{...B,fontSize:13,color:C.sub,lineHeight:1.6,marginBottom:5}}>Aqui você pode alterar seus dados a qualquer momento. Toque no botão <strong style={{color:C.green}}>✏️ Alterar</strong> em cada caixa pra preencher ou mudar.</div>
              <div style={{...B,fontSize:13,color:C.sub,lineHeight:1.6}}>As caixas com <strong style={{color:C.blue}}>💡</strong> mostram o que ainda falta. Quanto mais completo, mais empresas vão te chamar pra trabalhar.</div>
            </div>
            <button onClick={dismissWelcome} aria-label="Fechar" style={{background:"transparent",border:"none",cursor:"pointer",color:C.green,fontSize:24,padding:"0 4px",flexShrink:0,lineHeight:1,fontWeight:700}}>×</button>
          </div>
        )}

        {/* CONVITES RECEBIDOS */}
        {invites.filter(i=>i.status==="pending").length>0 && (
          <div style={{background:C.white,border:`2px solid ${C.amberBorder}`,borderRadius:14,padding:20,marginBottom:14,boxShadow:"0 4px 20px rgba(217,119,6,.1)"}}>
            <div style={{...H,fontSize:14,fontWeight:800,color:C.amber,textTransform:"uppercase",letterSpacing:.5,marginBottom:14,display:"flex",alignItems:"center",gap:8}}>
              <span style={{fontSize:18}}>📨</span>
              Convites recebidos · aguardando você
            </div>
            {invites.filter(i=>i.status==="pending").map(inv=>(
              <div key={inv.id} style={{padding:14,background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:10,marginBottom:10}}>
                <div style={{marginBottom:8}}>
                  <div style={{...H,fontSize:15,fontWeight:800,color:C.navy}}>{inv.companies?.nome_fant || inv.companies?.razao || "Empresa"}</div>
                  <div style={{...B,fontSize:12,color:C.muted}}>
                    {inv.company_units?.nome ? `${inv.company_units.nome} · ` : ""}
                    {inv.company_units?.cidade || inv.companies?.cidade}/{inv.company_units?.estado || inv.companies?.estado}
                    {" · "}{new Date(inv.created_at).toLocaleDateString("pt-BR")}
                  </div>
                </div>
                {inv.message && (
                  <div style={{padding:"10px 12px",background:C.white,borderRadius:7,...B,fontSize:13,color:C.sub,marginBottom:10,lineHeight:1.5,border:`1px solid ${C.border}`,fontStyle:"italic"}}>
                    "{inv.message}"
                  </div>
                )}
                <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                  <Btn label="✓ Aceitar e revelar contato" variant="primary" size="md" onClick={()=>respond(inv.id,"accepted")} loading={invSaving} />
                  <Btn label="Recusar" variant="ghost" size="md" onClick={()=>respond(inv.id,"declined")} disabled={invSaving} />
                </div>
              </div>
            ))}
          </div>
        )}
        {invites.filter(i=>i.status==="accepted").length>0 && (
          <div style={{background:C.white,border:`2px solid ${C.greenBorder}`,borderRadius:14,padding:20,marginBottom:14,boxShadow:"0 4px 20px rgba(22,163,74,.1)"}}>
            <div style={{...H,fontSize:14,fontWeight:800,color:C.green,textTransform:"uppercase",letterSpacing:.5,marginBottom:14,display:"flex",alignItems:"center",gap:8}}>
              <span style={{fontSize:18}}>✓</span>
              Convites aceitos · entre em contato
            </div>
            {invites.filter(i=>i.status==="accepted").map(inv=>(
              <div key={inv.id} style={{padding:14,background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:10,marginBottom:10}}>
                <div style={{marginBottom:10}}>
                  <div style={{...H,fontSize:15,fontWeight:800,color:C.navy}}>{inv.companies?.nome_fant || inv.companies?.razao || "Empresa"}</div>
                  <div style={{...B,fontSize:12,color:C.muted}}>
                    {inv.company_units?.nome ? `${inv.company_units.nome} · ` : ""}
                    {inv.company_units?.cidade || inv.companies?.cidade}/{inv.company_units?.estado || inv.companies?.estado}
                  </div>
                </div>
                <div style={{padding:"12px 14px",background:C.white,borderRadius:8,border:`1px solid ${C.greenBorder}`}}>
                  <div style={{...H,fontSize:11,fontWeight:700,color:C.green,marginBottom:8,textTransform:"uppercase",letterSpacing:.5}}>Contato da empresa</div>
                  {inv.companies?.resp_nome && <div style={{...B,fontSize:13,color:C.navy,marginBottom:4}}>👤 {inv.companies.resp_nome}</div>}
                  {inv.companies?.resp_tel && (
                    <div style={{...B,fontSize:13,color:C.navy,marginBottom:4}}>
                      📱 <a href={`https://wa.me/55${inv.companies.resp_tel.replace(/\D/g,"")}`} target="_blank" rel="noopener noreferrer" style={{color:C.green,fontWeight:700,textDecoration:"underline"}}>{inv.companies.resp_tel}</a>
                    </div>
                  )}
                  {inv.companies?.resp_email && <div style={{...B,fontSize:13,color:C.navy}}>✉️ {inv.companies.resp_email}</div>}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* HEADER CARD */}
        <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:16,padding:24,marginBottom:14,boxShadow:"0 4px 20px rgba(0,0,0,.04)"}}>
          <div style={{display:"flex",gap:18,alignItems:"flex-start"}}>
            {w.foto_rosto ? (
              <img src={w.foto_rosto} alt={w.nome} style={{width:88,height:88,borderRadius:44,objectFit:"cover",border:`2px solid ${C.greenBorder}`,flexShrink:0}} />
            ) : (
              <div style={{width:88,height:88,borderRadius:44,background:C.green,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                <span style={{...H,fontSize:34,fontWeight:900,color:"#fff"}}>{w.nome?.[0]}</span>
              </div>
            )}
            <div style={{flex:1,minWidth:0}}>
              <SL>Meu Perfil</SL>
              <h2 style={{...H,fontSize:26,fontWeight:900,color:C.navy,marginTop:4,marginBottom:8}}>{w.nome}</h2>
              <div style={{display:"flex",gap:14,alignItems:"center",flexWrap:"wrap"}}>
                <Badge status={w.status} />
                {w.cidade && <span style={{...B,fontSize:13,color:C.sub}}>📍 {w.cidade}/{w.estado}</span>}
                {w.raio_km && <span style={{...B,fontSize:13,color:C.sub}}>{w.raio_km}km de raio</span>}
              </div>
            </div>
          </div>
          {w.status==="approved" && (
            <div style={{marginTop:16,padding:"10px 14px",background:C.greenBg,border:`1px solid ${C.greenBorder}`,borderRadius:9,...B,fontSize:12.5,color:C.green,lineHeight:1.55}}>
              ✓ Seu perfil está visível para empresas. Você será notificado por e-mail quando alguma quiser te convidar.
            </div>
          )}
          {w.status==="pending" && (
            <div style={{marginTop:16,padding:"10px 14px",background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:9,...B,fontSize:12.5,color:C.amber,lineHeight:1.55}}>
              ⏳ Seu cadastro está em análise pela equipe Vorker. Em até 24h úteis você terá retorno por e-mail.
            </div>
          )}
          <div style={{marginTop:18,paddingTop:16,borderTop:`1px solid ${C.border}`}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
              <span style={{...B,fontSize:12,color:C.sub,fontWeight:600}}>Completude do perfil</span>
              <span style={{...H,fontSize:14,fontWeight:900,color:completeColor}}>{completeness}%</span>
            </div>
            <div style={{height:8,background:C.bg,borderRadius:4,overflow:"hidden"}}>
              <div style={{height:"100%",width:`${completeness}%`,background:completeColor,transition:"width .4s ease, background-color .3s"}} />
            </div>
            {completeness<100
              ? <div style={{...B,fontSize:11.5,color:C.muted,marginTop:8,lineHeight:1.5}}>💡 Quanto mais completo seu perfil, mais empresas conseguem te encontrar e te chamar pra turnos.</div>
              : <div style={{...B,fontSize:11.5,color:C.green,marginTop:8,fontWeight:600}}>✓ Perfil completo. Você está visível para todas as buscas.</div>
            }
          </div>
        </div>

        {/* IDENTIDADE / FOTOS */}
        <div style={sectionStyle}>
          {renderSectionHeader({id:"identidade", icon:"👤", color:"green", title:"Sua foto e documento", subtitle:"Foto sua e a foto do seu RG ou CNH"})}
          {renderMissing("identidade")}
          {editing!=="identidade" ? (
            <div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8,marginBottom:14}}>
                <WInfoLine icon="🧑" label="Nome completo" value={w.nome} />
                <WInfoLine icon="🪪" label="CPF" value={w.cpf} />
                <WInfoLine icon="🎂" label="Nascimento" value={w.nascimento ? new Date(w.nascimento).toLocaleDateString("pt-BR") : "—"} />
                <WInfoLine icon="✉️" label="E-mail" value={w.email} />
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                {[
                  {label:"Foto de perfil", src:w.foto_rosto, fallback:"📷"},
                  {label:`Foto do ${w.doc_tipo||"documento"}`, src:w.selfie_doc, fallback:"🪪"},
                ].map(item=>(
                  <div key={item.label} style={{padding:14,background:C.bg,borderRadius:10,textAlign:"center"}}>
                    {item.src
                      ? <img src={item.src} alt={item.label} style={{width:"100%",maxWidth:160,height:160,objectFit:"cover",borderRadius:9,marginBottom:8}} />
                      : <div style={{height:160,display:"flex",alignItems:"center",justifyContent:"center",fontSize:42}}>{item.fallback}</div>}
                    <div style={{...B,fontSize:12,color:C.sub,fontWeight:600}}>{item.label}</div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div>
              <Field label="Nome completo" value={d.nome} onChange={v=>setD({...d,nome:v})} required />
              <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:14,marginTop:6}}>
                <Field label="CPF" value={w.cpf} disabled hint="Não pode ser alterado" />
                <Field label="Nascimento" value={w.nascimento ? new Date(w.nascimento).toLocaleDateString("pt-BR") : ""} disabled hint="Não pode ser alterado" />
                <Field label="E-mail" value={w.email} disabled hint="Não pode ser alterado" />
              </div>
              <SelectField label="Tipo de documento" value={d.doc_tipo} onChange={v=>setD({...d,doc_tipo:v})} options={["RG","CNH"]} />
              <div style={{...H,fontSize:12,fontWeight:700,color:C.muted,marginTop:14,marginBottom:8,textTransform:"uppercase",letterSpacing:.5}}>Foto de perfil</div>
              <div className={`upload-zone ${d.foto_rosto?"has":""}`} onClick={()=>fotoRef.current?.click()} style={{textAlign:"center"}}>
                {d.foto_rosto
                  ? <div><img src={d.foto_rosto} alt="" style={{width:130,height:130,borderRadius:65,objectFit:"cover",border:`3px solid ${C.green}`,marginBottom:8}} /><div style={{...B,fontSize:12,color:C.green,fontWeight:600}}>Clique para alterar</div></div>
                  : <div><div style={{fontSize:36,marginBottom:8}}>📷</div><div style={{...B,fontSize:13,color:C.sub}}>Clique para enviar a foto</div></div>}
              </div>
              <input ref={fotoRef} type="file" accept="image/*" style={{display:"none"}} onChange={e=>{const f=e.target.files[0]; if(f) readFile(f,"foto_rosto");}} />
              <div style={{...H,fontSize:12,fontWeight:700,color:C.muted,marginTop:14,marginBottom:8,textTransform:"uppercase",letterSpacing:.5}}>Foto do {d.doc_tipo}</div>
              <div className={`upload-zone ${d.selfie_doc?"has":""}`} onClick={()=>selfieRef.current?.click()} style={{textAlign:"center"}}>
                {d.selfie_doc
                  ? <div><img src={d.selfie_doc} alt="" style={{maxWidth:220,maxHeight:165,borderRadius:10,objectFit:"cover",border:`2px solid ${C.green}`,marginBottom:8}} /><div style={{...B,fontSize:12,color:C.green,fontWeight:600}}>Clique para alterar</div></div>
                  : <div><div style={{fontSize:36,marginBottom:8}}>🪪</div><div style={{...B,fontSize:13,color:C.sub}}>Clique para enviar a foto do seu {d.doc_tipo}</div></div>}
              </div>
              <input ref={selfieRef} type="file" accept="image/*" style={{display:"none"}} onChange={e=>{const f=e.target.files[0]; if(f) readFile(f,"selfie_doc");}} />
              {renderSaveCancel(!!d.nome.trim())}
            </div>
          )}
        </div>

        {/* CONTATO E ENDEREÇO */}
        <div style={sectionStyle}>
          {renderSectionHeader({id:"contato", icon:"📱", color:"blue", title:"Como falar com você", subtitle:"WhatsApp e onde você mora"})}
          {editing!=="contato" ? (
            <div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8,marginBottom:12}}>
                <WInfoLine icon="📱" label="WhatsApp"  value={w.telefone} />
                <WInfoLine icon="🚗" label="Transporte" value={w.deslocamento} />
                <WInfoLine icon="📍" label="Distância" value={w.raio_km?`${w.raio_km}km`:"—"} />
              </div>
              {(w.rua||w.cep) && (
                <div style={{padding:"10px 14px",background:C.bg,borderRadius:9,...B,fontSize:13,color:C.sub,lineHeight:1.65}}>
                  {w.rua}{w.numero?`, ${w.numero}`:""}{w.complemento?` — ${w.complemento}`:""}
                  {w.bairro && <><br/>{w.bairro} · {w.cidade}/{w.estado}</>}
                  {w.cep && <>{` · CEP ${w.cep}`}</>}
                </div>
              )}
            </div>
          ) : (
            <div>
              <Field label="WhatsApp" value={d.telefone} onChange={v=>setD({...d,telefone:maskPhone(v)})} maxLength={15} />
              <AddressBlock data={d} setData={setD} loading={cepLoad} setLoading={setCepLoad} />
              <div style={{display:"grid",gridTemplateColumns:"2fr 1fr",gap:14}}>
                <SelectField label="Como você vai pro trabalho?" value={d.deslocamento} onChange={v=>setD({...d,deslocamento:v})} options={DESLOCAMENTOS} />
                <Field label="Distância máxima (km)" value={String(d.raio_km||"")} onChange={v=>setD({...d,raio_km:parseInt(v.replace(/\D/g,""))||0})} maxLength={3} />
              </div>
              {renderSaveCancel(!!(d.telefone && d.cep && d.rua && d.numero))}
            </div>
          )}
        </div>

        {/* DISPONIBILIDADE */}
        <div style={sectionStyle}>
          {renderSectionHeader({id:"disponibilidade", icon:"📅", color:"amber", title:"Quando você pode trabalhar", subtitle:"Dias da semana e turnos disponíveis"})}
          {renderMissing("disponibilidade")}
          {editing!=="disponibilidade" ? (
            <div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:6}}>
                {DAYS.map(day=>{
                  const turnos = w.disponibilidade?.[day]||[];
                  return (
                    <div key={day} style={{textAlign:"center"}}>
                      <div style={{...H,fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",marginBottom:6}}>{day}</div>
                      {turnos.length===0
                        ? <div style={{height:24,background:C.bg,borderRadius:5,display:"flex",alignItems:"center",justifyContent:"center",...B,fontSize:10,color:C.muted}}>—</div>
                        : turnos.map(tid=>{ const sh=SHIFTS.find(x=>x.id===tid); return sh ? <div key={tid} style={{background:sh.color+"22",border:`1px solid ${sh.color}66`,color:sh.color,borderRadius:5,padding:"3px 0",marginBottom:3,...B,fontSize:10,fontWeight:700}}>{sh.label}</div> : null; })}
                    </div>
                  );
                })}
              </div>
              {w.flexibilidade && FLEX_LABEL[w.flexibilidade] && (
                <div style={{marginTop:14,padding:"10px 14px",background:C.bg,borderRadius:9,...B,fontSize:13,color:C.sub,display:"flex",alignItems:"center",gap:8}}>
                  <span style={{fontSize:14}}>{FLEX_LABEL[w.flexibilidade].icon}</span>
                  <span><strong style={{color:C.navy,fontWeight:700}}>{FLEX_LABEL[w.flexibilidade].desc}</strong></span>
                </div>
              )}
            </div>
          ) : (
            <div>
              <div style={{...B,fontSize:13,color:C.sub,marginBottom:12,lineHeight:1.5}}>Toque nos turnos que você pode trabalhar em cada dia. Quanto mais turnos você marcar, mais empresas conseguem te chamar.</div>
              <div>
                {DAYS.map(day=>(
                  <div key={day} style={{display:"grid",gridTemplateColumns:"80px 1fr",gap:10,alignItems:"center",marginBottom:8}}>
                    <div style={{...H,fontSize:13,fontWeight:700,color:C.navy}}>{DAY_FULL[day]}</div>
                    <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                      {SHIFTS.map(sh=>{
                        const on = (d.disponibilidade[day]||[]).includes(sh.id);
                        return (
                          <button key={sh.id} onClick={()=>toggleShift(day,sh.id)}
                            style={{padding:"7px 11px",borderRadius:8,border:`1.5px solid ${on?sh.color:C.border2}`,background:on?sh.color+"15":C.white,color:on?sh.color:C.sub,...B,fontSize:11.5,fontWeight:on?700:600,cursor:"pointer",transition:"all .15s",display:"inline-flex",alignItems:"center",gap:5}}>
                            <span>{sh.icon}</span>{sh.label}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
              <div style={{...H,fontSize:12,fontWeight:700,color:C.muted,marginTop:18,marginBottom:8,textTransform:"uppercase",letterSpacing:.5}}>Você aceita ser chamado em cima da hora?</div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
                {Object.entries(FLEX_LABEL).map(([key,val])=>(
                  <button key={key} onClick={()=>setD({...d,flexibilidade:key})}
                    style={{padding:"12px 14px",borderRadius:10,border:`1.5px solid ${d.flexibilidade===key?C.green:C.border2}`,background:d.flexibilidade===key?C.greenBg:C.white,cursor:"pointer",textAlign:"left",transition:"all .15s"}}>
                    <div style={{...H,fontSize:13,fontWeight:700,color:C.navy,marginBottom:3}}>{val.icon} {val.label}</div>
                    <div style={{...B,fontSize:11,color:C.sub}}>{val.desc}</div>
                  </button>
                ))}
              </div>
              {renderSaveCancel()}
            </div>
          )}
        </div>

        {/* ESPECIALIDADES */}
        <div style={sectionStyle}>
          {renderSectionHeader({id:"especialidades", icon:"🛠️", color:"green", title:"O que você sabe fazer", subtitle:"Funções e há quanto tempo você faz cada uma"})}
          {renderMissing("especialidades")}
          {editing!=="especialidades" ? (
            especialidades.length>0 ? (
              <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                {especialidades.map(s=>(
                  <div key={s.id} style={{padding:"10px 14px",background:C.bg,border:`1px solid ${C.border}`,borderRadius:10,display:"flex",alignItems:"center",gap:10}}>
                    <span style={{fontSize:18}}>{s.icon}</span>
                    <div>
                      <div style={{...H,fontSize:13,fontWeight:700,color:C.navy}}>{s.label}</div>
                      {s.tempo && <div style={{...B,fontSize:11,color:C.muted}}>{s.tempo}</div>}
                    </div>
                  </div>
                ))}
              </div>
            ) : <div style={{...B,fontSize:13,color:C.muted}}>Nenhuma especialidade cadastrada ainda.</div>
          ) : (
            <div>
              <div style={{...B,fontSize:13,color:C.sub,marginBottom:12,lineHeight:1.5}}>Marque o que você sabe fazer. Pode marcar mais de um. Depois diga há quanto tempo você faz cada coisa.</div>
              <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:14}}>
                {SPECS.map(s=>{
                  const on = d.specs.includes(s.id);
                  return (
                    <button key={s.id} onClick={()=>toggleSpec(s.id)}
                      style={{padding:"9px 13px",borderRadius:9,border:`1.5px solid ${on?C.green:C.border2}`,background:on?C.greenBg:C.white,cursor:"pointer",...B,fontSize:12.5,fontWeight:on?700:600,color:on?C.green:C.sub,display:"inline-flex",alignItems:"center",gap:6,transition:"all .15s"}}>
                      <span style={{fontSize:14}}>{s.icon}</span>{s.label}
                    </button>
                  );
                })}
                <button onClick={()=>toggleSpec("custom")}
                  style={{padding:"9px 13px",borderRadius:9,border:`1.5px dashed ${d.specs.includes("custom")?C.green:C.border2}`,background:d.specs.includes("custom")?C.greenBg:C.white,cursor:"pointer",...B,fontSize:12.5,fontWeight:600,color:d.specs.includes("custom")?C.green:C.sub}}>
                  ⭐ Função própria
                </button>
              </div>
              {d.specs.includes("custom") && (
                <Field label="Nome da função própria" placeholder="Ex: Repositor de cosméticos" value={d.specCustom} onChange={v=>setD({...d,specCustom:v})} />
              )}
              {d.specs.length>0 && (
                <>
                  <div style={{...H,fontSize:12,fontWeight:700,color:C.muted,marginBottom:8,textTransform:"uppercase",letterSpacing:.5}}>Há quanto tempo você faz cada função?</div>
                  {d.specs.map(sid=>{
                    const spec = sid==="custom" ? {id:"custom",icon:"⭐",label:d.specCustom||"Função própria"} : SPECS.find(x=>x.id===sid);
                    if(!spec) return null;
                    return (
                      <div key={sid} style={{display:"grid",gridTemplateColumns:"160px 1fr",gap:12,alignItems:"center",marginBottom:8}}>
                        <div style={{...B,fontSize:13,color:C.navy,fontWeight:600}}><span style={{fontSize:15,marginRight:6}}>{spec.icon}</span>{spec.label}</div>
                        <select value={d.func_exp[sid]?.tempo||""} onChange={e=>setSpecTempo(sid, e.target.value)}
                          style={{padding:"8px 12px",borderRadius:9,border:`1.5px solid ${C.border2}`,background:C.white,...B,fontSize:13,color:C.navy,cursor:"pointer"}}>
                          <option value="">— selecione —</option>
                          {EXP_TIMES.map(t=><option key={t} value={t}>{t}</option>)}
                        </select>
                      </div>
                    );
                  })}
                </>
              )}
              {renderSaveCancel(d.specs.length>0 && (!d.specs.includes("custom") || d.specCustom.trim().length>0))}
            </div>
          )}
        </div>

        {/* EMPRESAS */}
        <div style={sectionStyle}>
          {renderSectionHeader({id:"empresas", icon:"🏢", color:"blue", title:"Onde você já trabalhou", subtitle:"Mercados, lojas ou outras empresas"})}
          {renderMissing("empresas")}
          {editing!=="empresas" ? (
            empresasView.length>0 ? (
              <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                {empresasView.map((e,i)=>(
                  <div key={i} style={{padding:"7px 11px",background:e.custom?C.amberBg:C.bg,border:`1px solid ${e.custom?C.amberBorder:C.border}`,borderRadius:8,...B,fontSize:12,color:e.custom?C.amber:C.navy,fontWeight:600}}>{e.label}</div>
                ))}
              </div>
            ) : <div style={{...B,fontSize:13,color:C.muted}}>Nenhuma empresa cadastrada ainda.</div>
          ) : (
            <div>
              <div style={{...B,fontSize:13,color:C.sub,marginBottom:12,lineHeight:1.5}}>Toque nas empresas onde você já trabalhou. Se a sua não estiver na lista, adicione embaixo.</div>
              <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:14}}>
                {EMPRESAS_PRESET.map(e=>{
                  const on = d.empresas_selected.includes(e.id);
                  return (
                    <button key={e.id} onClick={()=>toggleEmpresaPreset(e.id)}
                      style={{padding:"7px 11px",borderRadius:8,border:`1.5px solid ${on?C.green:C.border2}`,background:on?C.greenBg:C.white,cursor:"pointer",...B,fontSize:12,fontWeight:on?700:600,color:on?C.green:C.sub,transition:"all .15s"}}>
                      {e.label}
                    </button>
                  );
                })}
              </div>
              <div style={{...H,fontSize:12,fontWeight:700,color:C.muted,marginBottom:8,textTransform:"uppercase",letterSpacing:.5}}>Outras empresas (não listadas acima)</div>
              <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:10}}>
                {d.empresas_custom.map((nome,i)=>(
                  <div key={i} style={{padding:"7px 11px",background:C.amberBg,border:`1px solid ${C.amberBorder}`,borderRadius:8,...B,fontSize:12,color:C.amber,fontWeight:600,display:"inline-flex",alignItems:"center",gap:6}}>
                    {nome}
                    <span onClick={()=>removeEmpresaCustom(i)} style={{cursor:"pointer",color:C.red,fontWeight:800,marginLeft:2}}>×</span>
                  </div>
                ))}
              </div>
              <div style={{display:"flex",gap:8,alignItems:"flex-end"}}>
                <div style={{flex:1}}>
                  <Field label="Adicionar empresa" placeholder="Ex: Mercado Local LTDA" value={empresaNew} onChange={setEmpresaNew} />
                </div>
                <Btn label="+ Adicionar" variant="outline" size="md" onClick={addEmpresaCustom} disabled={!empresaNew.trim()} />
              </div>
              {renderSaveCancel()}
            </div>
          )}
        </div>

        {/* PERFIL COMPORTAMENTAL */}
        <div style={sectionStyle}>
          {renderSectionHeader({id:"perfil", icon:"🧠", color:"violet", title:"Como você trabalha", subtitle:"5 perguntas rápidas sobre o seu jeito"})}
          {renderMissing("perfil")}
          {editing!=="perfil" ? (
            <div>
              {Object.entries(PERFIL_LABELS).map(([key,cfg])=>{
                const ans = w.perfil_trabalho?.[key];
                const ansLabel = ans ? cfg.opts[ans] : null;
                return (
                  <div key={key} style={{padding:"10px 0",borderBottom:`1px solid ${C.border}`}}>
                    <div style={{...B,fontSize:11.5,color:C.muted,marginBottom:3}}>{cfg.title}</div>
                    <div style={{...B,fontSize:13,color:ansLabel?C.navy:C.muted,fontWeight:ansLabel?600:400}}>{ansLabel||"— não respondido —"}</div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div>
              {Object.entries(PERFIL_LABELS).map(([key,cfg])=>(
                <div key={key} style={{marginBottom:14}}>
                  <div style={{...H,fontSize:13,fontWeight:700,color:C.navy,marginBottom:8}}>{cfg.title}</div>
                  <div style={{display:"flex",flexDirection:"column",gap:6}}>
                    {Object.entries(cfg.opts).map(([optKey,optLabel])=>{
                      const sel = d.perfil_trabalho[key]===optKey;
                      return (
                        <button key={optKey} onClick={()=>setD({...d,perfil_trabalho:{...d.perfil_trabalho,[key]:optKey}})}
                          style={{padding:"10px 14px",borderRadius:9,border:`1.5px solid ${sel?C.green:C.border2}`,background:sel?C.greenBg:C.white,cursor:"pointer",textAlign:"left",...B,fontSize:13,color:sel?C.green:C.sub,fontWeight:sel?600:500,transition:"all .15s"}}>
                          {optLabel}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
              {renderSaveCancel()}
            </div>
          )}
        </div>

        {/* OUTROS */}
        <div style={sectionStyle}>
          {renderSectionHeader({id:"outros", icon:"📋", color:"amber", title:"Suas preferências", subtitle:"Tipo de trabalho que você gosta e PCD"})}
          {renderMissing("outros")}
          {editing!=="outros" ? (
            <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8}}>
              <WInfoLine icon="♿" label="PCD" value={w.pcd ? (w.pcd_tipo||"Sim") : "Não"} />
              <WInfoLine icon="🤝" label="Em equipe ou sozinho" value={w.trabalho_equipe} />
              <WInfoLine icon="💬" label="Atende cliente?" value={w.atend_cliente} />
              <WInfoLine icon="🛒" label="Onde gosta de trabalhar" value={w.tipo_trabalho} />
            </div>
          ) : (
            <div>
              <div style={{display:"flex",gap:8,marginBottom:14}}>
                <button onClick={()=>setD({...d,pcd:true})} style={{flex:1,padding:"10px 14px",borderRadius:9,border:`1.5px solid ${d.pcd?C.green:C.border2}`,background:d.pcd?C.greenBg:C.white,cursor:"pointer",...B,fontSize:13,color:d.pcd?C.green:C.sub,fontWeight:d.pcd?700:600}}>Sou PCD</button>
                <button onClick={()=>setD({...d,pcd:false,pcd_tipo:""})} style={{flex:1,padding:"10px 14px",borderRadius:9,border:`1.5px solid ${!d.pcd?C.green:C.border2}`,background:!d.pcd?C.greenBg:C.white,cursor:"pointer",...B,fontSize:13,color:!d.pcd?C.green:C.sub,fontWeight:!d.pcd?700:600}}>Não sou PCD</button>
              </div>
              {d.pcd && <Field label="Tipo de PCD" placeholder="Ex: Auditiva, motora, visual..." value={d.pcd_tipo} onChange={v=>setD({...d,pcd_tipo:v})} />}
              <SelectField label="Você prefere trabalhar:" value={d.trabalho_equipe} onChange={v=>setD({...d,trabalho_equipe:v})} options={["Prefiro trabalhar em equipe","Prefiro trabalhar sozinho","Os dois"]} />
              <SelectField label="Você gosta de atender clientes?" value={d.atend_cliente} onChange={v=>setD({...d,atend_cliente:v})} options={["Gosto e tenho experiência","Gosto, mas tenho pouca experiência","Prefiro funções de bastidor"]} />
              <SelectField label="Onde você prefere trabalhar?" value={d.tipo_trabalho} onChange={v=>setD({...d,tipo_trabalho:v})} options={["Loja / atendimento","Estoque / depósito","Centro de distribuição","Dark store / delivery","Tanto faz"]} />
              {renderSaveCancel()}
            </div>
          )}
        </div>

        <div style={{textAlign:"center",marginTop:24}}>
          <Btn label="Sair" variant="ghost" size="md" onClick={onLogout} />
        </div>
      </div>
    </div>
  );
}

// ─── AUTH SCREEN (worker only) ─────────────────────────────────
function AuthScreen({ type, onLogin, onRegister, onBack }) {
  const [email,setEmail]=useState("");
  const [pass,setPass]=useState("");
  const [error,setError]=useState("");
  const [loading,setLoading]=useState(false);

  const handleLogin = async () => {
    if(!email||!pass){ setError("Preencha e-mail e senha."); return; }
    setLoading(true); setError("");
    try {
      const { data: worker, error: err } = await supabase
        .from("workers")
        .select("*")
        .eq("email", email)
        .maybeSingle();
      if(err||!worker){ setError("E-mail não encontrado. Confira ou crie sua conta."); setLoading(false); return; }
      if(worker.status==="pending"){ setError("Seu cadastro ainda está em análise pela equipe Giobbi's. Em até 24h úteis você receberá retorno."); setLoading(false); return; }
      if(worker.status==="paused"){ setError("Seu perfil está temporariamente pausado e não aparece nas buscas. Entre em contato com a equipe Giobbi's para reativar."); setLoading(false); return; }
      if(worker.status==="rejected"){ setError(worker.reject_note ? `Seu cadastro foi reprovado. Motivo: ${worker.reject_note}` : "Seu cadastro foi reprovado. Entre em contato com a equipe Giobbi's."); setLoading(false); return; }
      onLogin(worker);
    } catch(e) {
      setError("Erro ao conectar. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{minHeight:"75vh",display:"flex",alignItems:"center",justifyContent:"center",padding:"60px 20px",background:C.bg}}>
      <div style={{maxWidth:420,width:"100%"}}>
        <button onClick={onBack} style={{...B,fontSize:13,color:C.sub,background:"none",border:"none",cursor:"pointer",marginBottom:24}}>← Voltar</button>
        <SL>Área do Colaborador</SL>
        <h2 style={{...H,fontSize:32,fontWeight:900,color:C.navy,letterSpacing:-1.2,marginBottom:28}}>Bem-vindo de volta.</h2>
        <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:28,boxShadow:"0 4px 20px rgba(0,0,0,.06)"}}>
          <Field label="E-mail" placeholder="seu@email.com" value={email} onChange={setEmail} type="email" />
          <Field label="Senha" placeholder="••••••••" value={pass} onChange={setPass} type="password" />
          {error&&<Alert type="error">{error}</Alert>}
          <Btn label="Entrar →" variant="primary" size="lg" full onClick={handleLogin} loading={loading} />
          <div style={{display:"flex",alignItems:"center",gap:12,margin:"16px 0"}}>
            <div style={{flex:1,height:1,background:C.border}} /><span style={{...B,fontSize:12,color:C.muted}}>ou</span><div style={{flex:1,height:1,background:C.border}} />
          </div>
          <Btn label="Criar conta →" variant="ghost" size="lg" full onClick={onRegister} />
        </div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// ROOT
// ═══════════════════════════════════════════════════════════════
export default function VORKERApp() {
  const [screen,  setScreen]  = useState("home");
  const [wData,   setWData]   = useState(null);
  const [cData,   setCData]   = useState(null);
  const [company, setCompany] = useState(null);
  const [worker,  setWorker]  = useState(null);
  const [admin,   setAdmin]   = useState(false);

  const userType = admin?"admin":company?"company":worker?"worker":null;
  const userName = admin?"Admin":company?(company.nome_fant||company.razao):worker?(worker.nome||"").split(" ")[0]:null;

  const onNav = s => {
    if(s==="home"){ setAdmin(false); setWorker(null); if(!company) setScreen("home"); else setScreen("home"); }
    setScreen(s);
  };

  const handleCompanyLogin = (co) => { setCompany(co); setScreen("company-app"); };
  const handleCompanyLogout = () => { setCompany(null); setScreen("home"); };

  const handleWorkerLogin  = (w) => { setWorker(w); setScreen("worker-app"); };
  const handleWorkerLogout = () => { setWorker(null); setScreen("home"); };

  return (
    <>
      <GlobalStyles />
      {!admin&&!company&&<Header onNav={onNav} user={userName} type={userType} landing={screen==="home"||(screen==="worker-app"&&!worker)} />}
      {!admin&&!company&&!worker&&screen==="home"             &&<Landing          onNav={onNav} />}
      {!admin&&!company&&!worker&&screen==="auth-choice"      &&<AuthChoice       onNav={onNav} />}
      {!admin&&!company&&!worker&&screen==="worker-auth"      &&<AuthScreen       type="worker"  onBack={()=>onNav("auth-choice")} onLogin={handleWorkerLogin} onRegister={()=>onNav("worker-register")} />}
      {!admin&&!company&&!worker&&screen==="worker-register"  &&<WorkerRegister   onBack={()=>onNav("worker-auth")} onDone={d=>{setWData(d);onNav("worker-success");}} />}
      {!admin&&!company&&!worker&&screen==="worker-success"   &&<WorkerSuccess    data={wData} onEnter={()=>onNav("home")} />}
      {!admin&&!company&& worker&&screen==="worker-app"       &&<WorkerProfile    worker={worker} onLogout={handleWorkerLogout} onUpdate={setWorker} />}
      {!admin&&!company&&screen==="company-auth"     &&<CompanyLogin     onBack={()=>onNav("auth-choice")} onLogin={handleCompanyLogin} onRegister={()=>onNav("company-register")} />}
      {!admin&&!company&&screen==="company-register" &&<CompanyRegister  onBack={()=>onNav("company-auth")} onDone={d=>{setCData(d);onNav("company-success");}} />}
      {!admin&&!company&&screen==="company-success"  &&<CompanySuccess   data={cData} onEnter={()=>onNav("home")} />}
      {!admin&&company  &&screen==="company-app"     &&<TalentBrowser    company={company} onLogout={handleCompanyLogout} onUpdateCompany={setCompany} />}
      {!admin&&!company&&screen==="admin-login"      &&<AdminLogin       onLogin={()=>setAdmin(true)} />}
      {admin                                         &&<AdminPanel onLogout={()=>{setAdmin(false);setScreen("home");}} />}
    </>
  );
}
